def _mutation_feedback_min_line_coverage() -> float:
    raw = os.environ.get("TATG_MUTATION_FEEDBACK_MIN_LINE_COVERAGE", "0.80")
    try:
        return max(0.0, min(1.0, float(raw)))
    except (TypeError, ValueError):
        return 0.80


def _mutation_feedback_allowed_for_generation(
    feedback: dict[str, Any] | None,
    *,
    force: bool = False,
) -> bool:
    if force:
        return True
    if not isinstance(feedback, dict):
        return False
    threshold = _mutation_feedback_min_line_coverage()
    if threshold <= 0.0:
        return True
    try:
        line_cov = float(feedback.get("line_coverage"))
    except (TypeError, ValueError):
        return False
    return line_cov >= threshold


def _regular_mutation_feedback_requested(request: Any) -> bool:
    """Return whether structural feedback rounds may invoke PITest.

    ``--with-mutation`` enables the final mutation-extra stage; it must not also
    leak PITest objectives into structural coverage rounds.  Keep the old mixed
    behaviour behind an explicit compatibility flag so existing experiments can
    reproduce it without making it the default.
    """
    if not bool(getattr(request, "with_mutation", False)):
        return False
    return os.environ.get(
        "TATG_ENABLE_REGULAR_MUTATION_FEEDBACK",
        "0",
    ).strip().lower() in {"1", "true", "yes", "on"}


def _should_run_legacy_repair_pipeline(
    *,
    e2e_timed_out: bool,
    dry_run: bool,
    has_repair_candidates: bool,
    test_command_enabled: bool,
    generation_failed: bool,
    mutation_extra_only_from_existing_tests: bool,
    current: dict[str, Any] | None,
    outcome: dict[str, Any] | None,
    retain_existing_tests: bool = False,
    existing_test_count: int = 0,
    streaming_submitted: int = 0,
) -> bool:
    """Return whether the class-scope repair pipeline still owns work.

    Streaming candidates are already isolated, validated, and locally repaired.
    When that lifecycle restores a retained green suite, replaying rejected
    candidates through the legacy class-scope repair loop can rewrite unrelated
    green tests and lower target coverage.  Keep the legacy path available when
    the on-disk suite itself is failing or when generation did not use streaming
    candidate validation.
    """

    if (
        e2e_timed_out
        or dry_run
        or not has_repair_candidates
        or not (test_command_enabled or generation_failed)
    ):
        return False
    if not isinstance(current, dict) or not isinstance(outcome, dict):
        return True
    green_suite = (
        int(current.get("return_code", 1) or 0) == 0
        and int(outcome.get("failed_test_count", 0) or 0) == 0
    )
    if mutation_extra_only_from_existing_tests and green_suite:
        return False
    if (
        retain_existing_tests
        and int(existing_test_count or 0) > 0
        and int(streaming_submitted or 0) > 0
        and green_suite
    ):
        return False
    return True


def _mutation_extra_existing_suite_is_green(
    *,
    mutation_extra_only_from_existing_tests: bool,
    test_command_enabled: bool,
    current: dict[str, Any] | None,
    outcome: dict[str, Any] | None,
    existing_test_count: int,
) -> bool:
    """Return whether the retained baseline is a valid mutation-only result.

    New hardening candidates may all fail while the archived target-reaching
    suite remains green.  That is a legitimate completed/no-gain mutation run,
    not a structural generation failure and not grounds for rolling the suite
    back to a different pre-run file.
    """

    return bool(
        mutation_extra_only_from_existing_tests
        and test_command_enabled
        and int(existing_test_count or 0) > 0
        and isinstance(current, dict)
        and isinstance(outcome, dict)
        and int(current.get("return_code", 1) or 0) == 0
        and int(outcome.get("failed_test_count", 0) or 0) == 0
    )


def _normalize_java_major(version: str | None) -> str:
    text = str(version or "").strip()
    if not text:
        return ""
    if text.startswith("1."):
        parts = text.split(".")
        if len(parts) >= 2 and parts[1].isdigit():
            return parts[1]
    match = re.match(r"^(\d+)", text)
    return match.group(1) if match else ""


def _java_home_major(java_home: str | Path | None) -> str:
    """Return the Java major declared by a JDK home, when inspectable."""

    if not java_home:
        return ""
    home = Path(java_home).expanduser()
    release_file = home / "release"
    try:
        release_text = release_file.read_text(encoding="utf-8", errors="ignore")
    except OSError:
        release_text = ""
    match = re.search(
        r'(?m)^\s*JAVA_VERSION\s*=\s*"(?P<version>[^"]+)"',
        release_text,
    )
    if match:
        return _normalize_java_major(match.group("version"))
    return ""


def _homebrew_java_home_candidates(major: str) -> list[str]:
    """Discover Homebrew JDKs without embedding a workstation path."""

    brew = shutil.which("brew")
    if not brew:
        return []
    candidates: list[str] = []
    for formula in (f"openjdk@{major}", "openjdk"):
        try:
            proc = subprocess.run(
                [brew, "--prefix", formula],
                text=True,
                capture_output=True,
                timeout=10,
                check=False,
            )
        except Exception:
            continue
        prefix = str(proc.stdout or "").strip()
        if proc.returncode != 0 or not prefix:
            continue
        root = Path(prefix)
        mac_home = root / "libexec" / "openjdk.jdk" / "Contents" / "Home"
        candidate = mac_home if mac_home.exists() else root
        if not (candidate / "bin" / "java").exists():
            continue
        detected_major = _java_home_major(candidate)
        if detected_major and detected_major != major:
            continue
        candidates.append(str(candidate))
    return candidates


@lru_cache(maxsize=16)
def _resolve_java_home_for_version(version: str | None) -> str | None:
    major = _normalize_java_major(version)
    if not major:
        return None
    env_keys = [
        f"JAVA_HOME_{major}",
        f"JDK_HOME_{major}",
        f"JAVA{major}_HOME",
    ]
    for key in env_keys:
        candidate = str(os.environ.get(key) or "").strip()
        if candidate and (Path(candidate) / "bin" / "java").exists():
            return candidate

    # macOS canonical JDK resolver; returns non-zero when that version is absent.
    # Additional installations are configured through the versioned environment
    # variables above rather than package-manager paths embedded in the source.
    if sys.platform == "darwin":
        resolver = str(
            os.environ.get("TATG_JAVA_HOME_RESOLVER")
            or "/usr/libexec/java_home"
        ).strip()
        try:
            proc = subprocess.run(
                [resolver, "-v", major],
                text=True,
                capture_output=True,
                timeout=10,
                check=False,
            )
            if proc.returncode == 0:
                path = str(proc.stdout or "").strip()
                detected_major = _java_home_major(path)
                if path and (not detected_major or detected_major == major):
                    return path
        except Exception:
            pass
    for path in _homebrew_java_home_candidates(major):
        return path
    return None


def _detect_java_version_from_env(env: dict[str, str] | None = None) -> str | None:
    try:
        proc = subprocess.run(
            ["java", "-version"],
            text=True,
            capture_output=True,
            timeout=10,
            check=False,
            env=env,
        )
    except Exception:
        return None
    text = f"{proc.stdout or ''}\n{proc.stderr or ''}"
    match = re.search(r'version\s+"([^"]+)"', text)
    return match.group(1) if match else None


def _pitest_java_toolchain_hint(
    *,
    requested_java_version: str | None,
    effective_java_version: str | None,
    error_hint: str | None,
) -> str | None:
    if error_hint not in {
        "pitest_minion_abnormal_exit",
        "java_version_incompatible",
    }:
        return error_hint
    requested_major = _normalize_java_major(requested_java_version)
    effective_major = _normalize_java_major(effective_java_version)
    if requested_major and effective_major and requested_major != effective_major:
        return "pitest_java_version_mismatch"
    return error_hint


def _pitest_java_runtime_retry_hint(error_hint: str | None) -> bool:
    """Return whether a PITest failure warrants a compatible-JDK retry."""

    hint = str(error_hint or "")
    return hint in {
        "java_version_incompatible",
        "pitest_java_version_mismatch",
    } or hint.startswith("pitest_minion_")


def _derive_default_test_file(source_file: Path) -> Path:
    """Derive the canonical test file path for a Java/Python source file."""
    if source_file.suffix == ".java":
        return derive_java_test_file(source_file)
    return source_file.with_name(source_file.stem + "Test" + source_file.suffix)


def _discover_green_test_files(
    source_file: Path,
    *,
    project_root: Path | str | None = None,
    max_files: int = 4,
) -> list[Path]:
    """Find package-matching tests even when a project uses a custom test root.

    The canonical Maven/Gradle path remains first.  The bounded fallback only
    accepts the target source package and conventional generated/native test
    class names, so a same-simple-name test from another module or package
    cannot become branch-analysis scaffold evidence.
    """

    source = Path(source_file).resolve()
    canonical = _derive_default_test_file(source).resolve()
    if source.suffix != ".java" or max_files <= 0:
        return [canonical] if canonical.is_file() else []

    try:
        source_text = source.read_text(encoding="utf-8", errors="ignore")
    except OSError:
        source_text = ""
    package_match = re.search(
        r"(?m)^\s*package\s+([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*)\s*;",
        source_text,
    )
    source_package = package_match.group(1) if package_match else ""
    expected_names = {
        f"{source.stem}Test.java",
        f"{source.stem}_TATGTest.java",
    }

    roots: list[Path] = []
    if project_root:
        roots.append(Path(project_root).resolve())
    for parent in source.parents:
        if (parent / "src" / "test").is_dir():
            roots.append(parent.resolve())
            break

    candidates: list[Path] = []
    if canonical.is_file():
        candidates.append(canonical)
    seen = {str(path) for path in candidates}
    for root in dict.fromkeys(roots):
        test_root = root / "src" / "test"
        if not test_root.is_dir():
            continue
        for expected_name in sorted(expected_names):
            for candidate in sorted(test_root.rglob(expected_name)):
                resolved = candidate.resolve()
                if str(resolved) in seen or not resolved.is_file():
                    continue
                try:
                    candidate_head = resolved.read_text(
                        encoding="utf-8", errors="ignore"
                    )[:16000]
                except OSError:
                    continue
                candidate_package_match = re.search(
                    r"(?m)^\s*package\s+([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*)\s*;",
                    candidate_head,
                )
                candidate_package = (
                    candidate_package_match.group(1)
                    if candidate_package_match
                    else ""
                )
                if candidate_package != source_package:
                    continue
                seen.add(str(resolved))
                candidates.append(resolved)
                if len(candidates) >= max_files:
                    return candidates
    return candidates


def _method_test_filter_for_build_system(
    build_system: BuildSystem,
    test_class_name: str,
    method_name: str,
) -> str:
    """Return the build-system-specific filter string for one test method."""
    if build_system == BuildSystem.GRADLE:
        return f"{test_class_name}.{method_name}"
    if build_system == BuildSystem.MAVEN:
        return f"{test_class_name}#{method_name}"
    return f"{test_class_name}#{method_name}"


def _isolated_method_test_filter_for_build_system(
    build_system: BuildSystem,
    test_class_name: str,
    method_name: str,
) -> str:
    """Return the filter used after a sandbox file has been reduced to one test."""
    if build_system == BuildSystem.MAVEN:
        return test_class_name
    return _method_test_filter_for_build_system(build_system, test_class_name, method_name)


def _apply_test_filter_to_command(
    command: str,
    build_system: BuildSystem,
    test_filter: str,
) -> str:
    """Apply a single-test filter to one shell command string."""
    command = str(command or "").strip()
    if not command:
        return command

    if build_system == BuildSystem.GRADLE:
        if "--tests" in command:
            return re.sub(r"--tests\s+\S+", f"--tests {test_filter}", command, count=1)
        return f"{command} --tests {test_filter}"

    if build_system == BuildSystem.MAVEN:
        if "-Dtest=" in command:
            return re.sub(r"-Dtest=[^\s]+", f"-Dtest={test_filter}", command, count=1)
        return f"{command} -Dtest={test_filter}"

    return command


def _apply_test_filter_to_commands(
    commands: list[str],
    build_system: BuildSystem,
    test_filter: str,
) -> list[str]:
    """Return *commands* rewritten to run only one test filter."""
    return [
        _apply_test_filter_to_command(cmd, build_system, test_filter)
        for cmd in commands
        if str(cmd or "").strip()
    ]


def _collect_target_test_files(
    commands: list,
    targets: list,
    *,
    strict_per_cmd: bool = False,
) -> list[Path]:
    """Collect candidate test files that may be modified by this run.

    When ``strict_per_cmd`` is True, only files explicitly declared by each
    command via ``output_file`` are returned; the fallback that derives test
    files from *all* targets is suppressed.  This is the correct mode when the
    caller wants to snapshot/rollback for a single command in isolation (so
    one command's failure cannot accidentally trample another command's file).
    """
    files: dict[str, Path] = {}
    for cmd in commands:
        output_file = getattr(cmd, "output_file", None)
        if isinstance(output_file, Path):
            resolved = output_file.resolve()
            files[str(resolved)] = resolved

    if files:
        return list(files.values())

    if strict_per_cmd:
        # Strict mode: refuse to widen the snapshot set to every target's
        # derived path. The caller treats an empty list as "no per-cmd file
        # to snapshot" and falls back to the outer-level safety net.
        return []

    for target in targets:
        source = getattr(target, "source_file", None)
        if not source:
            continue
        sf = Path(source)
        tf = _derive_default_test_file(sf).resolve()
        files[str(tf)] = tf
    return list(files.values())


def _snapshot_test_files(test_files: list[Path]) -> dict[str, str | None]:
    """Snapshot current test file content (None means file did not exist)."""
    snapshots: dict[str, str | None] = {}
    for p in test_files:
        key = str(p.resolve())
        if p.exists():
            snapshots[key] = p.read_text(encoding="utf-8", errors="ignore")
        else:
            snapshots[key] = None
    return snapshots


def _mutation_score_changed_without_suite_change(
    before_summary: Any,
    after_summary: Any,
    *,
    suite_changed: bool,
) -> bool:
    """Reject a PIT delta when the executable test suite is byte-identical."""

    if suite_changed:
        return False
    if not isinstance(before_summary, dict) or not isinstance(after_summary, dict):
        return False
    before_score = before_summary.get("mutation_score")
    after_score = after_summary.get("mutation_score")
    return bool(
        isinstance(before_score, (int, float))
        and isinstance(after_score, (int, float))
        and abs(float(after_score) - float(before_score)) > 1e-12
    )


def _junit_import_lines(junit_family: str | None) -> list[str]:
    fam = str(junit_family or "").strip().lower()
    if fam == "junit5":
        return [
            "import org.junit.jupiter.api.Test;",
            "import static org.junit.jupiter.api.Assertions.*;",
        ]
    return [
        "import org.junit.Test;",
        "import static org.junit.Assert.*;",
    ]


def _empty_java_test_class_skeleton(
    test_file: Path,
    source_text: str | None = None,
    *,
    junit_family: str | None = None,
) -> str:
    """Return a minimal Java test class preserving package and class name."""
    package_line = ""
    if source_text:
        match = re.search(r"(?m)^\s*package\s+([\w.]+)\s*;", source_text)
        if match:
            package_line = f"package {match.group(1)};\n\n"
    class_name = re.sub(r"\W+", "", test_file.stem) or "TATGEmptyTest"
    imports = "\n".join(_junit_import_lines(junit_family))
    if imports:
        imports += "\n\n"
    return f"{package_line}{imports}public class {class_name} {{\n}}\n"


def _xml_local_name(tag: object) -> str:
    return str(tag or "").rsplit("}", 1)[-1]


def _local_maven_parent_poms(project_root: Path) -> list[Path]:
    """Return the source-visible local Maven parent chain, nearest first."""
    current_pom = Path(project_root).resolve() / "pom.xml"
    if not current_pom.exists():
        return []

    parents: list[Path] = []
    seen = {current_pom.resolve()}
    while current_pom.exists():
        try:
            root = ET.parse(current_pom).getroot()
        except (ET.ParseError, OSError):
            break
        parent_node = next(
            (node for node in list(root) if _xml_local_name(node.tag) == "parent"),
            None,
        )
        if parent_node is None:
            break
        relative_node = next(
            (
                node
                for node in list(parent_node)
                if _xml_local_name(node.tag) == "relativePath"
            ),
            None,
        )
        # An explicitly empty <relativePath/> disables local parent lookup.
        if relative_node is not None and not str(relative_node.text or "").strip():
            break
        relative_path = (
            str(relative_node.text or "").strip()
            if relative_node is not None
            else "../pom.xml"
        )
        parent_pom = (current_pom.parent / relative_path).resolve()
        if parent_pom in seen or not parent_pom.is_file():
            break
        parents.append(parent_pom)
        seen.add(parent_pom)
        current_pom = parent_pom
    return parents


def _method_probe_base(path: Path) -> Path:
    resolved = Path(path).resolve()
    for candidate in (resolved, *resolved.parents):
        if candidate.name.startswith("tatg-method-probe-"):
            return candidate
    return resolved.parent


def _method_probe_workspace_root(path: Path) -> Path:
    base = _method_probe_base(path)
    workspace = base / "workspace"
    return workspace if workspace.exists() else Path(path)


def _copy_local_maven_parent_context(
    project_root: Path,
    *,
    workspace_root: Path,
    parent_poms: list[Path],
) -> Path:
    """Place a copied Maven module under its original local parent layout."""
    project_root = Path(project_root).resolve()
    if not parent_poms:
        return workspace_root

    top_root = parent_poms[-1].parent.resolve()
    try:
        module_relative = project_root.relative_to(top_root)
    except ValueError:
        return workspace_root

    for parent_pom in reversed(parent_poms):
        try:
            destination = workspace_root / parent_pom.relative_to(top_root)
        except ValueError:
            continue
        destination.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(parent_pom, destination)

        maven_config = parent_pom.parent / ".mvn"
        if maven_config.is_dir():
            copied_config = destination.parent / ".mvn"
            if not copied_config.exists():
                shutil.copytree(maven_config, copied_config)

    return workspace_root / module_relative


def _create_method_probe_sandboxes(project_root: Path, worker_count: int) -> list[Path]:
    """Create worker-local project sandboxes for isolated method validation.

    Sandboxes are temporary directories under the system temp path, so the
    implementation is portable across devices and OSes.
    """
    count = max(1, int(worker_count or 1))

    sandboxes: list[Path] = []
    ignore = shutil.ignore_patterns(
        ".git",
        ".idea",
        ".tatg",
        "__pycache__",
        "target",
        "build",
        ".gradle",
        ".m2",
        ".pytest_cache",
    )
    project_root = Path(project_root).resolve()
    parent_poms = _local_maven_parent_poms(project_root)
    for idx in range(count):
        base = Path(tempfile.mkdtemp(prefix=f"tatg-method-probe-{idx}-"))
        workspace_root = base / "workspace"
        sandbox_root = _copy_local_maven_parent_context(
            project_root,
            workspace_root=workspace_root,
            parent_poms=parent_poms,
        )
        try:
            shutil.copytree(project_root, sandbox_root, ignore=ignore)
        except Exception:
            shutil.rmtree(base, ignore_errors=True)
            raise
        else:
            atexit.register(shutil.rmtree, base, ignore_errors=True)
            sandboxes.append(sandbox_root)
    return sandboxes


def _cleanup_method_probe_sandboxes(sandbox_map: dict[str, list[Path]]) -> int:
    """Remove temporary method-probe sandboxes immediately after validation."""
    cleaned = 0
    seen_bases: set[Path] = set()
    for sandboxes in sandbox_map.values():
        for sandbox_root in sandboxes:
            try:
                base = _method_probe_base(sandbox_root)
            except Exception:
                continue
            if base in seen_bases:
                continue
            seen_bases.add(base)
            try:
                existed = base.exists()
                shutil.rmtree(base, ignore_errors=True)
                if existed and not base.exists():
                    cleaned += 1
            except Exception:
                pass
    return cleaned


def _rewrite_sandbox_literal_jacoco_destfiles(sandbox_root: Path) -> int:
    """Point literal JaCoCo javaagent destfiles in copied POMs at the sandbox.

    Some projects keep a hard-coded surefire ``<argLine>`` with an absolute
    ``destfile=/original/project/target/jacoco.exec``. Maven command-line
    ``-DargLine`` properties do not override that literal plugin config, so
    candidate tests can pass while JaCoCo writes outside the sandbox.  This is
    confined to copied method-probe workspaces and only rewrites existing
    JaCoCo ``destfile=...`` segments.
    """
    project_root = Path(sandbox_root)
    root = _method_probe_workspace_root(project_root)
    if not root.exists():
        return 0
    rewritten = 0
    pattern = re.compile(r"(destfile=)([^<>'\"\s]+jacoco\.exec)")
    local_dest = (project_root / "target" / "jacoco.exec").as_posix()
    for pom in root.rglob("pom.xml"):
        try:
            text = pom.read_text(encoding="utf-8", errors="ignore")
        except Exception:
            continue
        new_text = pattern.sub(lambda match: f"{match.group(1)}{local_dest}", text)
        if new_text == text:
            continue
        try:
            pom.write_text(new_text, encoding="utf-8")
            rewritten += 1
        except Exception:
            continue
    return rewritten


def _payload_test_file(payload: dict[str, Any]) -> str:
    """Best-effort test file path extraction from backend payloads."""
    direct = str(
        payload.get("test_file")
        or payload.get("generated_tests")
        or payload.get("_tatg_output_file")
        or ""
    )
    if direct:
        return direct
    nested = payload.get("results")
    if isinstance(nested, dict):
        for one in nested.values():
            if isinstance(one, dict):
                candidate = str(one.get("test_file") or one.get("generated_tests") or "")
                if candidate:
                    return candidate
    return ""


def _payload_candidate_code(payload: dict[str, Any]) -> str:
    """Best-effort full candidate test source extraction from backend payloads."""
    direct = payload.get("final_code") or payload.get("generated_code")
    if isinstance(direct, str) and direct.strip():
        return direct
    nested = payload.get("results")
    if isinstance(nested, dict):
        for one in nested.values():
            if isinstance(one, dict):
                candidate = one.get("final_code") or one.get("generated_code")
                if isinstance(candidate, str) and candidate.strip():
                    return candidate
    snapshot = payload.get("_tatg_test_file_snapshot")
    if isinstance(snapshot, str) and snapshot.strip():
        return snapshot
    return ""


def _payload_merge_code(payload: dict[str, Any]) -> str:
    """Return the source fragment best suited for merging into the real test file."""
    if payload.get("streaming_method_validation"):
        validated_source = payload.get("streaming_validation_full_source")
        if isinstance(validated_source, str) and validated_source.strip():
            return validated_source
    if payload.get("streaming_repaired") or payload.get("streaming_method_validation"):
        direct = payload.get("final_code") or payload.get("generated_code")
        if isinstance(direct, str) and direct.strip():
            return direct
    if payload.get("method_name") and isinstance(payload.get("generated_code"), str):
        generated = str(payload.get("generated_code") or "")
        if generated.strip():
            return generated
    nested = payload.get("results")
    if isinstance(nested, dict):
        for one in nested.values():
            if not isinstance(one, dict):
                continue
            if one.get("method_name") and isinstance(one.get("generated_code"), str):
                generated = str(one.get("generated_code") or "")
                if generated.strip():
                    return generated
    return _payload_candidate_code(payload)


def _recover_json_method_patch_for_streaming(
    candidate_code: str,
    payload: dict[str, Any],
) -> tuple[str, dict[str, Any]] | None:
    """Recover a method-level JSON patch from a failed generation payload."""
    text = str(candidate_code or "")
    if not _looks_like_json_test_patch(text):
        return None
    try:
        from tatg.engines.tatg_adapter import TATGEngineAdapter

        extracted = TATGEngineAdapter._extract_patch_from_json_output(
            text,
            return_metadata=True,
        )
    except Exception:
        return None
    if not isinstance(extracted, tuple) or len(extracted) != 2:
        return None
    patch_code, metadata = extracted
    if not isinstance(patch_code, str) or not patch_code.strip():
        return None
    recovered_metadata = dict(metadata) if isinstance(metadata, dict) else {}
    recovered_metadata["streaming_recovered_failed_generation_json_patch"] = True
    recovered_metadata["streaming_recovered_failed_generation_return_code"] = payload.get("return_code")
    recovered_metadata.setdefault(
        "tatg_generated_test_overload_map",
        recovered_metadata.get("test_overload_map", {}),
    )
    recovered_metadata.setdefault(
        "tatg_generated_test_behavior_map",
        recovered_metadata.get("test_behavior_map", {}),
    )
    recovered_metadata.setdefault(
        "tatg_generated_test_objective_map",
        recovered_metadata.get("test_objective_map", {}),
    )
    recovered_metadata.setdefault(
        "tatg_generated_test_candidate_role_map",
        recovered_metadata.get("test_candidate_role_map", {}),
    )
    recovered_metadata.setdefault(
        "tatg_generated_test_baseline_skeleton_map",
        recovered_metadata.get("test_baseline_skeleton_map", {}),
    )
    recovered_metadata.setdefault(
        "tatg_generated_test_skeleton_fact_ids_map",
        recovered_metadata.get("test_skeleton_fact_ids_map", {}),
    )
    recovered_metadata.setdefault(
        "tatg_generated_test_obligation_map",
        recovered_metadata.get("test_obligation_map", {}),
    )
    recovered_metadata.setdefault(
        "tatg_generated_test_input_family_map",
        recovered_metadata.get("test_input_family_map", {}),
    )
    recovered_metadata.setdefault(
        "tatg_generated_test_oracle_type_map",
        recovered_metadata.get("test_oracle_type_map", {}),
    )
    recovered_metadata.setdefault(
        "tatg_generated_test_repair_axis_map",
        recovered_metadata.get("test_repair_axis_map", {}),
    )
    return patch_code, recovered_metadata


def _payload_nested_value(payload: dict[str, Any], key: str) -> Any:
    if key in payload:
        return payload.get(key)
    nested = payload.get("results")
    if isinstance(nested, dict):
        for one in nested.values():
            if isinstance(one, dict) and key in one:
                return one.get(key)
    return None

def _synthesize_java_test_shell(test_file: Path, project_root: Path) -> str:
    """Create a minimal Java test class for merging method-only snippets."""
    class_name = test_file.stem or "GeneratedTest"
    package_name = ""
    try:
        rel = test_file.resolve().relative_to(project_root.resolve())
        parts = list(rel.parts)
        for marker in (("src", "test", "java"), ("src", "main", "java")):
            marker_len = len(marker)
            for index in range(0, max(0, len(parts) - marker_len)):
                if tuple(parts[index : index + marker_len]) == marker:
                    package_parts = parts[index + marker_len : -1]
                    if package_parts:
                        package_name = ".".join(package_parts)
                    raise StopIteration
    except StopIteration:
        pass
    except Exception:
        package_name = ""

    package_decl = f"package {package_name};\n\n" if package_name else ""
    return f"{package_decl}public class {class_name} {{\n}}\n"


def _count_candidate_test_methods(source_text: str | None) -> int:
    if not source_text:
        return 0
    return len(
        re.findall(
            r"(?m)^\s*@(?:org\.junit(?:\.jupiter\.api)?\.)?"
            r"(Test|ParameterizedTest|RepeatedTest|TestFactory|TestTemplate)\b",
            source_text,
        )
    )


def _java_import_lines(source_text: str) -> list[str]:
    return re.findall(r"(?m)^\s*import\s+(?:static\s+)?[A-Za-z_][\w.]*(?:\.\*)?\s*;\s*$", source_text or "")


def _looks_like_full_java_source(source_text: str) -> bool:
    text = str(source_text or "")
    return bool(
        re.search(r"(?m)^\s*package\s+[A-Za-z_][\w.]*\s*;", text)
        or re.search(r"\b(?:class|interface|enum|record)\s+[A-Za-z_][A-Za-z0-9_]*\b", text)
    )


def _looks_like_json_test_patch(source_text: str) -> bool:
    """Return true when text is a JSON new_tests/test_code_lines payload.

    Method-level repair can legitimately return a JSON patch.  If the JSON
    projection fails, that payload must not fall through to Java-source
    heuristics, because quoted ``test_code_lines`` can contain ``@Test`` and a
    method name while still being invalid Java source.
    """
    text = str(source_text or "").lstrip()
    if not text:
        return False
    if not (text.startswith("{") or text.startswith("[")):
        return False
    head = text[:4000]
    return bool(re.search(r'"(?:new_tests|test_code_lines|new_imports_lines)"\s*:', head))


def _junit_test_annotation_anchors(source_text: str) -> list[re.Match[str]]:
    return list(
        re.finditer(
            r"(?<![A-Za-z0-9_])@(?:org\.junit(?:\.jupiter\.api)?\.)?Test\b",
            source_text or "",
        )
    )


def _junit_test_method_blocks(source_text: str) -> list[tuple[str, str]]:
    """Return ``[(method_name, source_block)]`` for Java ``@Test`` methods."""
    if not source_text:
        return []
    blocks: list[tuple[str, str]] = []
    anchors = _junit_test_annotation_anchors(source_text)
    for anchor in anchors:
        open_brace = source_text.find("{", anchor.end())
        if open_brace == -1:
            continue
        header = source_text[anchor.end() : open_brace]
        name_matches = list(re.finditer(r"\b([A-Za-z_]\w*)\s*\(", header))
        if not name_matches:
            continue
        close_brace = _find_matching_brace(source_text, open_brace)
        if close_brace == -1:
            continue
        method_name = name_matches[-1].group(1)
        blocks.append((method_name, source_text[anchor.start() : close_brace + 1]))
    return blocks


def _source_constant_dispatch_spec(
    *,
    source_text: str,
    class_name: str,
    method_name: str,
    target_descriptor: str = "",
    source_file: Path | None = None,
) -> dict[str, Any]:
    """Return a narrow, source-proven finite constant-dispatch specification.

    This intentionally recognizes only exact equality comparisons between one
    target parameter and qualified Java constants.  It does not infer enum
    members, invent values, or treat arbitrary literals as an exhaustive
    domain.  The result is suitable for deterministic candidate replay, not a
    claim that every constant closes a coverage gap.
    """
    signature, body = _source_backed_exact_target_method_source(
        source_text=source_text,
        class_name=class_name,
        method_name=method_name,
        target_descriptor=target_descriptor,
    )
    if not signature or not body:
        return {}
    bindings = _method_parameter_bindings(
        f"{signature} {{{body}}}",
        target_descriptor,
    )
    parameter_types = {name: parameter_type for parameter_type, name in bindings}
    parameter_names = set(parameter_types)
    if not parameter_names:
        return {}

    qualified_constant = r"[A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)+"
    identifier = r"[A-Za-z_$][\w$]*"
    comparisons = re.compile(
        rf"\b(?P<left>{identifier})\s*==\s*(?P<right>{qualified_constant})\b"
        rf"|\b(?P<reverse>{qualified_constant})\s*==\s*(?P<reverse_param>{identifier})\b"
    )
    constants_by_parameter: dict[str, list[str]] = {}
    evidence_by_parameter: dict[str, list[str]] = {}
    for match in comparisons.finditer(_strip_comments_and_literals(body)):
        parameter = str(match.group("left") or match.group("reverse_param") or "")
        constant = str(match.group("right") or match.group("reverse") or "")
        if parameter not in parameter_names or not constant:
            continue
        constants_by_parameter.setdefault(parameter, [])
        if constant not in constants_by_parameter[parameter]:
            constants_by_parameter[parameter].append(constant)
        evidence_by_parameter.setdefault(parameter, []).append(match.group(0).strip())

    eligible = [
        (parameter, constants)
        for parameter, constants in constants_by_parameter.items()
        if len(constants) >= 3
    ]
    if len(eligible) != 1:
        return {}
    parameter, constants = eligible[0]
    parameter_type = re.sub(r"<.*>", "", parameter_types.get(parameter, ""))
    parameter_type = re.sub(r"\[\s*\]", "", parameter_type).strip()
    parameter_simple = parameter_type.rsplit(".", 1)[-1]
    constant_prefixes = {
        constant.rsplit(".", 1)[0]
        for constant in constants
        if "." in constant
    }
    declaration_source = source_text
    declaration_file = ""
    if (
        parameter_simple
        and not re.search(
            rf"\b(?:class|enum|interface|record)\s+{re.escape(parameter_simple)}\b",
            source_text,
        )
        and source_file is not None
    ):
        candidate = Path(source_file).with_name(f"{parameter_simple}.java")
        try:
            declaration_source = candidate.read_text(encoding="utf-8", errors="ignore")
            declaration_file = str(candidate)
        except OSError:
            declaration_source = ""
    declared_constants: list[str] = []
    completed_default_constant = ""
    if declaration_source and parameter_simple and len(constant_prefixes) == 1:
        masked_declaration = _strip_comments_and_literals(declaration_source)
        for match in re.finditer(
            rf"\bpublic\s+static\s+final\s+{re.escape(parameter_simple)}\s+"
            r"(?P<name>[A-Za-z_$][\w$]*)\b",
            masked_declaration,
        ):
            name = str(match.group("name") or "")
            if name and name not in declared_constants:
                declared_constants.append(name)
        prefix = next(iter(constant_prefixes))
        missing_constants = [
            f"{prefix}.{name}"
            for name in declared_constants
            if f"{prefix}.{name}" not in constants
        ]
        # A single source-declared remainder is the only value that can enter
        # the final default branch. Multiple remainders would make the mapping
        # ambiguous, so keep the narrower explicit comparison set.
        if len(missing_constants) == 1:
            constants.append(missing_constants[0])
            completed_default_constant = missing_constants[0]
    return {
        "parameter_name": parameter,
        "constants": constants[:24],
        "source_evidence": evidence_by_parameter.get(parameter, [])[:24],
        "target_descriptor": target_descriptor,
        "proof_status": "source_proven_exact_constant_dispatch",
        "finite_declaration_source": declaration_file,
        "default_constant_completed": completed_default_constant,
    }


def _deterministic_replay_specs_enabled(
    *,
    backend: str,
    method_name: str,
    target_file: Any,
    baseline_branch_coverage: float | None,
    feedback_by_label: Any,
) -> bool:
    """Keep structural and mutation replay eligibility independent.

    Structural deterministic replay remains gated to a measured branch gap.
    Mutation-extra already has exact live-mutant evidence, so a high structural
    branch score must not disable input/oracle replay for a low mutation score.
    """

    if (
        str(backend or "").strip().lower() != "tatg"
        or not str(method_name or "").strip()
        or not target_file
    ):
        return False
    mutation_feedback = any(
        isinstance(row, dict)
        and bool(row.get("mutation_feedback_only"))
        and bool(row.get("mutation_objectives"))
        for row in (
            feedback_by_label.values()
            if isinstance(feedback_by_label, dict)
            else []
        )
    )
    return bool(
        mutation_feedback
        or baseline_branch_coverage is None
        or baseline_branch_coverage < 0.75
    )


def _deterministic_constant_variant_sources(
    *,
    candidate_code: str,
    dispatch_spec: dict[str, Any],
    target_method_name: str,
    max_variants: int = 12,
) -> list[dict[str, Any]]:
    """Clone one target-calling test across source-proven dispatch constants.

    The seed must contain exactly one distinct dispatch constant.  Replacing a
    qualified token is deliberately stricter than rewriting an arbitrary
    argument expression: receiver construction and the exact target call stay
    byte-for-byte identical.  Returned variants still require ordinary
    compile, JUnit, and candidate-level JaCoCo validation before promotion.
    """
    code = str(candidate_code or "")
    constants = [
        str(value).strip()
        for value in list(dispatch_spec.get("constants") or [])
        if str(value).strip()
    ]
    if len(constants) < 3 or not code or max_variants <= 0:
        return []
    blocks = _junit_test_method_blocks(code)
    if len(blocks) != 1:
        return []
    test_name, test_block = blocks[0]
    if not test_code_calls_any_method(test_block, [target_method_name]):
        return []
    present = [
        constant
        for constant in constants
        if re.search(rf"(?<![\w$]){re.escape(constant)}(?![\w$])", test_block)
    ]
    if len(present) != 1:
        return []
    seed_constant = present[0]
    constant_occurrences = list(
        re.finditer(
            rf"(?<![\w$]){re.escape(seed_constant)}(?![\w$])",
            test_block,
        )
    )
    target_calls = list(
        re.finditer(rf"\b{re.escape(target_method_name)}\s*\(", test_block)
    )
    bound_target_call_start = -1
    local_binding_variable = ""
    for target_call in target_calls:
        open_paren = test_block.find("(", target_call.start())
        close_paren = _find_matching_paren_for_text(test_block, open_paren)
        if close_paren < 0:
            continue
        arguments = test_block[open_paren + 1:close_paren]
        if re.search(
            rf"(?<![\w$]){re.escape(seed_constant)}(?![\w$])",
            arguments,
        ):
            bound_target_call_start = target_call.start()
            break
    if bound_target_call_start < 0:
        assignment = re.search(
            rf"\b(?P<var>[A-Za-z_$][\w$]*)\s*=\s*"
            rf"{re.escape(seed_constant)}\s*;",
            test_block,
        )
        if assignment:
            variable = str(assignment.group("var") or "")
            variable_occurrences = list(
                re.finditer(rf"\b{re.escape(variable)}\b", test_block)
            )
            for target_call in target_calls:
                open_paren = test_block.find("(", target_call.start())
                close_paren = _find_matching_paren_for_text(test_block, open_paren)
                if close_paren < 0:
                    continue
                arguments = test_block[open_paren + 1:close_paren]
                if (
                    re.search(rf"\b{re.escape(variable)}\b", arguments)
                    and len(variable_occurrences) >= 3
                ):
                    local_binding_variable = variable
                    bound_target_call_start = target_call.start()
                    break
    if (
        (
            len(constant_occurrences) < 2
            and not local_binding_variable
        )
        or bound_target_call_start < 0
        or not any(
            occurrence.start() < bound_target_call_start
            for occurrence in constant_occurrences
        )
    ):
        return []
    variants: list[dict[str, Any]] = []
    for constant in constants:
        if constant == seed_constant or len(variants) >= min(12, max_variants):
            continue
        suffix = re.sub(r"[^A-Za-z0-9_$]+", "_", constant).strip("_")[-70:]
        variant_name = f"{test_name}__dispatch_{suffix}"
        variant_block = re.sub(
            rf"(?<![\w$]){re.escape(seed_constant)}(?![\w$])",
            constant,
            test_block,
        )
        variant_block = re.sub(
            rf"\b{re.escape(test_name)}\s*(?=\()",
            variant_name,
            variant_block,
            count=1,
        )
        if variant_block == test_block:
            continue
        variant_source = code.replace(test_block, variant_block, 1)
        variants.append({
            "source": variant_source,
            "test_method_name": variant_name,
            "seed_test_method_name": test_name,
            "seed_constant": seed_constant,
            "variant_constant": constant,
            "proof_status": "source_proven_unvalidated_variant",
        })
    return variants


def _source_verified_json_replay_spec(
    *,
    source_text: str,
    source_file: Path,
    class_name: str,
    method_name: str,
    target_descriptor: str = "",
) -> dict[str, Any]:
    """Return bounded public-entry JSON rows for a JsonParser helper.

    The gate is intentionally stricter than ordinary coverage guidance: the
    exact target must consume JsonParser, String compile/check entries must be
    source-visible, and operator values must resolve from declarations.
    """

    signature, body = _source_backed_exact_target_method_source(
        source_text=source_text,
        class_name=class_name,
        method_name=method_name,
        target_descriptor=target_descriptor,
    )
    if not signature or "JsonParser" not in signature or not body:
        return {}
    clean = _strip_comments_preserve_literals(source_text)
    has_compile = bool(
        re.search(
            r"\bpublic\s+static\s+[\w$.,<> ?\[\]]+\s+compile\s*\(\s*(?:final\s+)?String\b",
            clean,
        )
    )
    has_check = bool(
        re.search(
            r"\bpublic\s+static\s+String\s+check\s*\(\s*(?:final\s+)?String\b",
            clean,
        )
    )
    if not (has_compile and has_check):
        return {}
    constants = _qualified_string_constant_values(source_text, source_file)
    rows = _source_backed_json_expression_row_records(
        f"{source_text}\n{body}",
        owner=class_name,
        target_descriptor=target_descriptor,
        operator_values=constants,
    )
    rows = [
        row
        for row in rows
        if any(
            str(evidence).startswith("source-resolved")
            for evidence in list(row.get("source_evidence") or [])
        )
    ][:32]
    if len(rows) < 2:
        return {}
    return {
        "owner": class_name,
        "target_method": method_name,
        "rows": rows,
        "target_descriptor": target_descriptor,
        "proof_status": "source_verified_public_json_entry_rows",
    }


def _source_verified_numeric_string_replay_spec(
    *,
    source_text: str,
    class_name: str,
    method_name: str,
    target_descriptor: str = "",
) -> dict[str, Any]:
    """Return bounded numeric-string rows for a static ``Number`` parser.

    This is deliberately a type-and-source gate, not a method-name heuristic.
    A row is emitted only when the exact target has one String parameter,
    returns Number, is static, and its body contains the syntax predicate that
    justifies that row.  Rows remain untrusted until isolated JUnit and JaCoCo
    replay proves a target coverage gain.
    """
    signature, body = _source_backed_exact_target_method_source(
        source_text=source_text,
        class_name=class_name,
        method_name=method_name,
        target_descriptor=target_descriptor,
    )
    if not signature or not body:
        return {}
    bindings = _method_parameter_bindings(f"{signature} {{{body}}}", target_descriptor)
    if len(bindings) != 1:
        return {}
    parameter_type, _parameter_name = bindings[0]
    if re.sub(r"\s+", "", parameter_type) not in {"String", "java.lang.String"}:
        return {}
    if not re.search(r"\bstatic\b", signature):
        return {}
    method_token = re.escape(method_name)
    signature_head = signature.split(method_name, 1)[0]
    if not re.search(r"\b(?:java\.lang\.)?Number\s*$", signature_head.strip()):
        return {}

    clean = _strip_comments_preserve_literals(body)
    rows: list[dict[str, Any]] = []

    def add(row_id: str, value: str, evidence: str) -> None:
        if any(row["input_value"] == value for row in rows):
            return
        rows.append({
            "row_id": row_id,
            "input_value": value,
            "source_evidence": [evidence],
            "proof_status": "source_proven_unvalidated_input",
        })

    if re.search(r"\bcreate(?:Integer|Long|BigInteger)\s*\(", clean):
        add("decimal_integer", "1", "source calls an integral Number factory")
        add("signed_decimal_integer", "-1", "source calls an integral Number factory")
        add("integer_overflow_boundary", "2147483648", "source escalates integral Number factories")
    if re.search(r"(?:indexOf\s*\(\s*'\.'|charAt\s*\([^)]*\)\s*==\s*'\.')", clean):
        add("decimal_fraction", "1.5", "source tests a decimal-point token")
    if re.search(r"indexOf\s*\(\s*'[eE]'", clean) or (
        "indexOf('e')" in clean and "indexOf('E')" in clean
    ):
        add("exponent_lower", "1e2", "source tests an exponent token")
        add("exponent_upper", "1E2", "source tests an exponent token")
    for suffix, row_id in (("L", "long_suffix"), ("F", "float_suffix"), ("D", "double_suffix")):
        if re.search(rf"['\"]{suffix}['\"]|['\"]{suffix.lower()}['\"]", clean):
            add(row_id, f"1{suffix}", f"source tests the {suffix}/{suffix.lower()} type suffix")
    prefix_rows = (
        ("0x", "hex_prefix", "0x1"),
        ("0X", "hex_upper_prefix", "0X1"),
        ("#", "hash_hex_prefix", "#1"),
    )
    for prefix, row_id, value in prefix_rows:
        if prefix in clean:
            add(row_id, value, f"source tests the {prefix!r} prefix")

    if len(rows) < 3:
        return {}
    boundary_rows: list[dict[str, str]] = []

    def add_boundary(
        row_id: str,
        value: str,
        expected: str,
        evidence: str,
    ) -> None:
        boundary_rows.append({
            "row_id": row_id,
            "input_value": value,
            "expected": expected,
            "source_evidence": evidence,
        })

    for prefix, row_id in (
        ("-0x", "negative_hex"),
        ("-0X", "negative_hex_upper"),
        ("-#", "negative_hash_hex"),
    ):
        if json.dumps(prefix) in clean:
            add_boundary(
                row_id,
                f"{prefix}1",
                "integer",
                f"source-declared hexadecimal prefix {prefix!r}",
            )
    if (
        re.search(r"\bhexDigits\s*>\s*16\b", clean)
        and re.search(r"\bhexDigits\s*>\s*8\b", clean)
        and "createBigInteger" in clean
        and "createLong" in clean
    ):
        add_boundary(
            "hex_long_boundary",
            "0x100000000",
            "long",
            "source promotes hexadecimal values above 8 digits to Long",
        )
        add_boundary(
            "hex_big_integer_boundary",
            "0x10000000000000000",
            "big_integer",
            "source promotes hexadecimal values above 16 digits to BigInteger",
        )
    if all(call in clean for call in ("createInteger", "createLong", "createBigInteger")):
        add_boundary(
            "decimal_beyond_long",
            "9223372036854775808",
            "big_integer",
            "source falls through Integer and Long to BigInteger",
        )
    if "indexOf('e') + str.indexOf('E') + 1" in clean:
        if re.search(r"\bexpPos\s*>\s*str\.length\s*\(\s*\)", clean):
            add_boundary(
                "double_exponent_invalid",
                "1eE2",
                "number_format",
                "source rejects combined lower/upper exponent offsets beyond input length",
            )
        if re.search(r"\bexpPos\s*<\s*decPos\b", clean):
            add_boundary(
                "exponent_before_decimal_invalid",
                "1e.2",
                "number_format",
                "source rejects exponent position before decimal position",
            )
    if (
        re.search(r"case\s+'[lL]'", clean)
        and re.search(r"\bdec\s*==\s*null", clean)
        and re.search(r"\bexp\s*==\s*null", clean)
    ):
        add_boundary(
            "fractional_long_invalid",
            "1.0L",
            "number_format",
            "source permits long suffix only without decimal or exponent",
        )
    if re.search(r"\bdefault\s*:\s*throw\s+new\s+NumberFormatException", clean):
        add_boundary(
            "unknown_suffix_invalid",
            "1Q",
            "number_format",
            "source default suffix arm throws NumberFormatException",
        )
    if "f.isInfinite()" in clean and "f.floatValue() == 0.0F" in clean:
        add_boundary(
            "float_overflow_fallback",
            "1e1000F",
            "big_decimal",
            "source rejects infinite Float and falls through to wider factories",
        )
        add_boundary(
            "float_underflow_fallback",
            "1e-1000F",
            "big_decimal",
            "source rejects zero Float for a nonzero mantissa",
        )
    if "d.isInfinite()" in clean and re.search(r"d\.(?:doubleValue|floatValue)\(\)\s*==\s*0\.0D", clean):
        add_boundary(
            "double_overflow_fallback",
            "1e1000D",
            "big_decimal",
            "source rejects infinite Double and falls through to BigDecimal",
        )
        add_boundary(
            "double_underflow_fallback",
            "1e-1000D",
            "big_decimal",
            "source rejects zero Double for a nonzero mantissa",
        )
    return {
        "owner": class_name,
        "method_name": method_name,
        "rows": rows[:16],
        "boundary_rows": boundary_rows[:16],
        "target_descriptor": target_descriptor,
        "proof_status": "source_verified_numeric_string_rows",
    }


def _deterministic_numeric_string_variant_sources(
    *,
    candidate_code: str,
    replay_spec: dict[str, Any],
    max_variants: int = 12,
) -> list[dict[str, Any]]:
    """Build isolated tests for source-backed numeric string rows."""
    code = str(candidate_code or "")
    owner = str(replay_spec.get("owner") or "").strip()
    method_name = str(replay_spec.get("method_name") or "").strip()
    rows = list(replay_spec.get("rows") or [])
    if not code or not owner or not method_name or not rows or max_variants <= 0:
        return []
    seed_test_names = [name for name, _block in _junit_test_method_blocks(code)]
    if len(seed_test_names) != 1:
        return []
    if not test_code_calls_any_method(code, [method_name]):
        return []
    class_scaffold, removed_seed_tests = _drop_junit_test_methods_from_source(
        code,
        seed_test_names,
    )
    if removed_seed_tests != seed_test_names:
        return []
    if "org.junit.jupiter" in code:
        annotation = "@org.junit.jupiter.api.Test"
        assertions = "org.junit.jupiter.api.Assertions"
    elif "org.junit.Test" in code:
        annotation = "@org.junit.Test"
        assertions = "org.junit.Assert"
    else:
        return []

    variants: list[dict[str, Any]] = []
    for row in rows:
        if len(variants) >= min(16, max_variants):
            break
        row_id = re.sub(r"\W+", "_", str(row.get("row_id") or "row")).strip("_")
        input_value = str(row.get("input_value") or "")
        if not row_id:
            continue
        test_name = f"testDeterministicNumericStringReplay_{row_id}"
        method_block = f"""
{annotation}
public void {test_name}() throws Exception {{
    Number parsed = {owner}.{method_name}({json.dumps(input_value)});
    {assertions}.assertNotNull(parsed);
}}
"""
        variant_source = _insert_test_method_into_candidate_class(
            class_scaffold,
            method_block,
        )
        if not variant_source:
            continue
        variants.append({
            "row_id": row_id,
            "input_value": input_value,
            "source": variant_source,
            "test_method_name": test_name,
            "source_evidence": list(row.get("source_evidence") or [])[:4],
        })
    boundary_rows = list(replay_spec.get("boundary_rows") or [])
    if boundary_rows and len(variants) < min(16, max_variants):
        matrix_lines: list[str] = []
        evidence: list[str] = []
        type_names = {
            "integer": "java.lang.Integer",
            "long": "java.lang.Long",
            "big_integer": "java.math.BigInteger",
            "big_decimal": "java.math.BigDecimal",
        }
        for index, row in enumerate(boundary_rows[:16]):
            input_value = json.dumps(str(row.get("input_value") or ""))
            expected = str(row.get("expected") or "")
            source_evidence = str(row.get("source_evidence") or "").strip()
            if source_evidence:
                evidence.append(source_evidence)
            if expected == "number_format":
                matrix_lines.extend([
                    "    try {",
                    f"        {owner}.{method_name}({input_value});",
                    f"        {assertions}.fail(\"Expected NumberFormatException for \" + {input_value});",
                    "    } catch (NumberFormatException expectedException) {",
                    "        // Source-declared invalid syntax.",
                    "    }",
                ])
                continue
            expected_type = type_names.get(expected)
            if not expected_type:
                continue
            matrix_lines.extend([
                f"    Number boundary{index} = {owner}.{method_name}({input_value});",
                f"    {assertions}.assertTrue(boundary{index} instanceof {expected_type});",
            ])
        if matrix_lines:
            test_name = "testDeterministicNumericStringReplay_source_boundaries"
            method_block = "\n".join([
                annotation,
                f"public void {test_name}() throws Exception {{",
                *matrix_lines,
                "}",
            ])
            variant_source = _insert_test_method_into_candidate_class(
                class_scaffold,
                method_block,
            )
            if variant_source:
                variants.append({
                    "row_id": "source_boundary_matrix",
                    "source": variant_source,
                    "test_method_name": test_name,
                    "source_evidence": evidence[:16],
                })
    return variants


def _source_verified_reader_token_replay_spec(
    *,
    source_text: str,
    class_name: str,
    method_name: str,
    target_descriptor: str = "",
) -> dict[str, Any]:
    """Return public protocol rows for a Reader-backed token peeker.

    The exact helper must return an int token id, the owner must expose a
    Reader constructor, and a public token-returning entry must invoke the
    helper.  Expected tokens are admitted only when that entry's source maps
    helper constants to the public enum value.
    """
    signature, body = _source_backed_exact_target_method_source(
        source_text=source_text,
        class_name=class_name,
        method_name=method_name,
        target_descriptor=target_descriptor,
    )
    if not signature or not body or not re.search(r"\bint\s*$", signature.split(method_name, 1)[0].strip()):
        return {}
    clean = _strip_comments_preserve_literals(source_text)
    if not re.search(
        rf"\bpublic\s+{re.escape(class_name)}\s*\(\s*(?:java\.io\.)?Reader\b",
        clean,
    ):
        return {}
    entry_candidates: list[tuple[re.Match[str], str]] = []
    for candidate in re.finditer(
        rf"\bpublic\s+(?P<token_type>[A-Za-z_$][\w$.]*)\s+(?P<entry>[A-Za-z_$][\w$]*)\s*\(\s*\)\s*throws\s+IOException\s*\{{",
        clean,
    ):
        entry_open = clean.find("{", candidate.start())
        entry_close = _find_matching_brace(clean, entry_open)
        if entry_close < 0:
            continue
        candidate_body = clean[entry_open + 1:entry_close]
        token_type = candidate.group("token_type")
        public_token_returns = len(re.findall(
            rf"\breturn\s+{re.escape(token_type)}\s*\.\s*[A-Za-z_$][\w$]*\s*;",
            candidate_body,
        ))
        if (
            re.search(rf"\b{re.escape(method_name)}\s*\(\s*\)", candidate_body)
            and public_token_returns >= 5
        ):
            entry_candidates.append((candidate, candidate_body))
    if len(entry_candidates) != 1:
        return {}
    entry_match, entry_body = entry_candidates[0]
    token_type = entry_match.group("token_type")
    entry_method = entry_match.group("entry")
    required_mappings = {
        "BEGIN_ARRAY": "PEEKED_BEGIN_ARRAY",
        "END_ARRAY": "PEEKED_END_ARRAY",
        "BEGIN_OBJECT": "PEEKED_BEGIN_OBJECT",
        "END_OBJECT": "PEEKED_END_OBJECT",
        "NAME": "PEEKED_DOUBLE_QUOTED_NAME",
        "STRING": "PEEKED_DOUBLE_QUOTED",
        "BOOLEAN": "PEEKED_TRUE",
        "NULL": "PEEKED_NULL",
        "NUMBER": "PEEKED_NUMBER",
        "END_DOCUMENT": "PEEKED_EOF",
    }
    mapped = {
        public_token
        for public_token, internal_token in required_mappings.items()
        if internal_token in entry_body and re.search(
            rf"\b{re.escape(token_type)}\s*\.\s*{re.escape(public_token)}\b",
            entry_body,
        )
    }
    target_clean = _strip_comments_preserve_literals(body)
    one_hop_evidence: list[str] = []
    for helper_name in dict.fromkeys(re.findall(
        r"\b([a-z_][A-Za-z0-9_$]*)\s*\(\s*\)",
        target_clean,
    )):
        if helper_name == method_name:
            continue
        helper_signature, helper_body = _source_backed_exact_target_method_source(
            source_text=source_text,
            class_name=class_name,
            method_name=helper_name,
            target_descriptor="",
        )
        if not helper_signature or not helper_body or "private" not in helper_signature:
            continue
        one_hop_evidence.append(_strip_comments_preserve_literals(helper_body))
        if len(one_hop_evidence) >= 8:
            break
    replay_evidence = "\n".join([target_clean, *one_hop_evidence])
    row_defs = [
        ("begin_array", "[]", [], "BEGIN_ARRAY", "'['"),
        ("end_array", "[]", ["beginArray"], "END_ARRAY", "']'"),
        ("begin_object", "{}", [], "BEGIN_OBJECT", "'{'"),
        ("end_object", "{}", ["beginObject"], "END_OBJECT", "'}'"),
        ("quoted_name", '{\"a\":1}', ["beginObject"], "NAME", "PEEKED_DOUBLE_QUOTED_NAME"),
        ("quoted_string", '\"value\"', [], "STRING", "PEEKED_DOUBLE_QUOTED"),
        ("true_keyword", "true", [], "BOOLEAN", 'keyword = "true"'),
        ("false_keyword", "false", [], "BOOLEAN", 'keyword = "false"'),
        ("null_keyword", "null", [], "NULL", 'keyword = "null"'),
        ("integer_number", "1", [], "NUMBER", "PEEKED_LONG"),
        ("negative_number", "-1", [], "NUMBER", "case '-'"),
        ("fraction_number", "1.5", [], "NUMBER", "case '.'"),
        ("exponent_number", "1e2", [], "NUMBER", "case 'e'"),
        ("nonempty_array_value", "[1,2]", ["beginArray", "nextInt"], "NUMBER", "JsonScope.NONEMPTY_ARRAY"),
        ("nonempty_array_end", "[1]", ["beginArray", "nextInt"], "END_ARRAY", "JsonScope.NONEMPTY_ARRAY"),
        ("object_value", '{\"a\":1}', ["beginObject", "nextName"], "NUMBER", "JsonScope.DANGLING_NAME"),
        ("document_end", "1", ["nextInt"], "END_DOCUMENT", "JsonScope.NONEMPTY_DOCUMENT"),
        ("lenient_single_quote", "'value'", [], "STRING", "case '\\''"),
        ("lenient_unquoted", "value", [], "STRING", "PEEKED_UNQUOTED"),
        ("lenient_missing_array_value", "[,]", ["beginArray"], "NULL", "peekStack == JsonScope.EMPTY_ARRAY ||"),
    ]
    rows: list[dict[str, Any]] = []
    for row_id, payload, prefix_calls, expected_token, evidence in row_defs:
        if expected_token not in mapped or evidence not in replay_evidence:
            continue
        if any(
            not re.search(rf"\bpublic\s+[^;{{]+\s+{re.escape(call)}\s*\(\s*\)", clean)
            for call in prefix_calls
        ):
            continue
        if row_id.startswith("lenient_") and not re.search(
            r"\bpublic\s+(?:final\s+)?void\s+setLenient\s*\(\s*boolean\b",
            clean,
        ):
            continue
        rows.append({
            "row_id": row_id,
            "input_payload": payload,
            "prefix_calls": prefix_calls,
            "configuration_calls": (
                [{"method": "setLenient", "argument": "true"}]
                if row_id.startswith("lenient_")
                else []
            ),
            "expected_token": expected_token,
            "source_evidence": [
                f"target or source-called private helper contains {evidence}",
                f"public {entry_method} maps to {token_type}.{expected_token}",
            ],
        })
    protocol_rows = [
        {
            "row_id": "nonempty_object_end",
            "input_payload": '{"a":1}',
            "prefix_calls": ["beginObject", "nextName", "nextInt"],
            "expected_token": "END_OBJECT",
            "evidence": "JsonScope.NONEMPTY_OBJECT",
        },
        {
            "row_id": "nonempty_object_next_name",
            "input_payload": '{"a":1,"b":2}',
            "prefix_calls": ["beginObject", "nextName", "nextInt"],
            "expected_token": "NAME",
            "evidence": "JsonScope.NONEMPTY_OBJECT",
        },
        {
            "row_id": "lenient_array_semicolon",
            "input_payload": "[1;2]",
            "prefix_calls": ["beginArray", "nextInt"],
            "expected_token": "NUMBER",
            "evidence": "case ';'",
            "lenient": True,
        },
        {
            "row_id": "lenient_object_semicolon",
            "input_payload": '{"a":1;"b":2}',
            "prefix_calls": ["beginObject", "nextName", "nextInt"],
            "expected_token": "NAME",
            "evidence": "case ';'",
            "lenient": True,
        },
        {
            "row_id": "lenient_single_quoted_name",
            "input_payload": "{'a':1}",
            "prefix_calls": ["beginObject"],
            "expected_token": "NAME",
            "evidence": "PEEKED_SINGLE_QUOTED_NAME",
            "lenient": True,
        },
        {
            "row_id": "lenient_unquoted_name",
            "input_payload": "{a:1}",
            "prefix_calls": ["beginObject"],
            "expected_token": "NAME",
            "evidence": "PEEKED_UNQUOTED_NAME",
            "lenient": True,
        },
        {
            "row_id": "invalid_object_name",
            "input_payload": "{:1}",
            "prefix_calls": ["beginObject"],
            "expected_exception": "java.io.IOException",
            "evidence": 'syntaxError("Expected name")',
            "lenient": True,
        },
        {
            "row_id": "lenient_equals_name_separator",
            "input_payload": "{a=1}",
            "prefix_calls": ["beginObject", "nextName"],
            "expected_token": "NUMBER",
            "evidence": "case '='",
            "lenient": True,
        },
        {
            "row_id": "unterminated_array",
            "input_payload": "[1 2]",
            "prefix_calls": ["beginArray", "nextInt"],
            "expected_exception": "java.io.IOException",
            "evidence": 'syntaxError("Unterminated array")',
        },
        {
            "row_id": "unterminated_object",
            "input_payload": '{"a":1 "b":2}',
            "prefix_calls": ["beginObject", "nextName", "nextInt"],
            "expected_exception": "java.io.IOException",
            "evidence": 'syntaxError("Unterminated object")',
        },
        {
            "row_id": "closed_reader",
            "input_payload": "",
            "prefix_calls": ["close"],
            "expected_exception": "IllegalStateException",
            "evidence": "JsonScope.CLOSED",
        },
    ]
    for row in protocol_rows:
        if str(row["evidence"]) not in replay_evidence:
            continue
        expected_token = str(row.get("expected_token") or "")
        if expected_token and expected_token not in mapped:
            continue
        prefix_calls = list(row.get("prefix_calls") or [])
        if any(
            not re.search(rf"\bpublic\s+[^;{{]+\s+{re.escape(call)}\s*\(\s*\)", clean)
            for call in prefix_calls
        ):
            continue
        if row.get("lenient") and not re.search(
            r"\bpublic\s+(?:final\s+)?void\s+setLenient\s*\(\s*boolean\b",
            clean,
        ):
            continue
        rows.append({
            "row_id": row["row_id"],
            "input_payload": row["input_payload"],
            "prefix_calls": prefix_calls,
            "configuration_calls": (
                [{"method": "setLenient", "argument": "true"}]
                if row.get("lenient")
                else []
            ),
            "expected_token": expected_token,
            "expected_exception": str(row.get("expected_exception") or ""),
            "source_evidence": [
                f"target helper contains {row['evidence']}",
                f"public protocol reaches {row['row_id']}",
            ],
        })
    if len(rows) < 5:
        return {}
    return {
        "owner": class_name,
        "entry_method": entry_method,
        "token_type": token_type,
        "rows": rows,
        "target_descriptor": target_descriptor,
        "proof_status": "source_verified_reader_token_protocol_rows",
    }


def _deterministic_reader_token_variant_sources(
    *,
    candidate_code: str,
    replay_spec: dict[str, Any],
    max_variants: int = 16,
) -> list[dict[str, Any]]:
    """Build one isolated public token-protocol test per source-backed row."""
    code = str(candidate_code or "")
    owner = str(replay_spec.get("owner") or "").strip()
    entry_method = str(replay_spec.get("entry_method") or "").strip()
    token_type = str(replay_spec.get("token_type") or "").strip()
    rows = list(replay_spec.get("rows") or [])
    if not code or not owner or not entry_method or not token_type or not rows:
        return []
    seed_test_names = [name for name, _block in _junit_test_method_blocks(code)]
    if len(seed_test_names) != 1:
        return []
    class_scaffold, removed_seed_tests = _drop_junit_test_methods_from_source(code, seed_test_names)
    if removed_seed_tests != seed_test_names:
        return []
    if "org.junit.jupiter" in code:
        annotation = "@org.junit.jupiter.api.Test"
        assertions = "org.junit.jupiter.api.Assertions"
    elif "org.junit.Test" in code:
        annotation = "@org.junit.Test"
        assertions = "org.junit.Assert"
    else:
        return []
    variants: list[dict[str, Any]] = []
    for row in rows[:max_variants]:
        row_id = re.sub(r"\W+", "_", str(row.get("row_id") or "row")).strip("_")
        if not row_id:
            continue
        test_name = f"testDeterministicReaderTokenReplay_{row_id}"
        prefix = "\n".join(
            f"    reader.{call}();" for call in list(row.get("prefix_calls") or [])
        )
        configuration = "\n".join(
            f"    reader.{call.get('method')}({call.get('argument')});"
            for call in list(row.get("configuration_calls") or [])
            if isinstance(call, dict)
            and re.fullmatch(r"[A-Za-z_$][\w$]*", str(call.get("method") or ""))
            and str(call.get("argument") or "") in {"true", "false"}
        )
        if configuration:
            configuration += "\n"
        if prefix:
            prefix += "\n"
        expected_exception = str(row.get("expected_exception") or "").strip()
        assertion = (
            f"{assertions}.assertThrows({expected_exception}.class, () -> reader.{entry_method}());"
            if expected_exception
            else f"{assertions}.assertEquals({token_type}.{row.get('expected_token')}, reader.{entry_method}());"
        )
        method_block = f"""
{annotation}
public void {test_name}() throws Exception {{
    {owner} reader = new {owner}(new java.io.StringReader({json.dumps(str(row.get('input_payload') or ''))}));
{configuration}{prefix}    {assertion}
}}
"""
        source = _insert_test_method_into_candidate_class(class_scaffold, method_block)
        if source:
            variants.append({
                "row_id": row_id,
                "source": source,
                "test_method_name": test_name,
                "source_evidence": list(row.get("source_evidence") or [])[:4],
            })
    return variants


def _source_verified_filter_delegate_replay_spec(
    *,
    source_text: str,
    source_file: Path,
    class_name: str,
    method_name: str,
    target_descriptor: str = "",
) -> dict[str, Any]:
    """Return public parser/filter protocol rows proven by local source APIs."""
    signature, body = _source_backed_exact_target_method_source(
        source_text=source_text,
        class_name=class_name,
        method_name=method_name,
        target_descriptor=target_descriptor,
    )
    clean = _strip_comments_preserve_literals(source_text)
    if not signature or not body or not re.search(r"\bJsonToken\s*$", signature.split(method_name, 1)[0]):
        return {}
    constructor = re.search(
        rf"\bpublic\s+{re.escape(class_name)}\s*\(\s*JsonParser\s+\w+\s*,\s*TokenFilter\s+\w+\s*,\s*boolean\s+\w+\s*,\s*boolean\s+\w+\s*\)",
        clean,
    )
    target_clean = _strip_comments_preserve_literals(body)
    if not constructor or "delegate.nextToken()" not in target_clean or "switch (t.id())" not in target_clean:
        return {}
    filter_source = source_file.with_name("TokenFilter.java")
    factory_source = source_file.parent.parent / "JsonFactory.java"
    try:
        filter_text = _strip_comments_preserve_literals(filter_source.read_text(encoding="utf-8", errors="ignore"))
        factory_text = _strip_comments_preserve_literals(factory_source.read_text(encoding="utf-8", errors="ignore"))
    except OSError:
        return {}
    required_filter_apis = (
        r"\bpublic\s+TokenFilter\s+includeProperty\s*\(\s*String\b",
        r"\bpublic\s+TokenFilter\s+includeElement\s*\(\s*int\b",
        r"\bpublic\s+boolean\s+includeValue\s*\(\s*JsonParser\b",
        r"\bpublic\s+TokenFilter\s+includeRootValue\s*\(\s*int\b",
        r"\bpublic\s+TokenFilter\s+filterStartArray\s*\(\s*\)",
        r"\bpublic\s+TokenFilter\s+filterStartObject\s*\(\s*\)",
        r"\bpublic\s+(?:final\s+static|static\s+final)\s+TokenFilter\s+INCLUDE_ALL\b",
    )
    if not all(re.search(pattern, filter_text) for pattern in required_filter_apis):
        return {}
    if not re.search(r"\bcreateParser\s*\(\s*String\b", factory_text):
        return {}
    structured_shortcuts_proven = all(
        evidence in target_clean
        for evidence in (
            "case ID_START_ARRAY:",
            "case ID_START_OBJECT:",
            "TokenFilter.INCLUDE_ALL",
        )
    ) and bool(re.search(r"\bif\s*\(\s*f\s*==\s*null\s*\)", target_clean))
    package_match = re.search(r"(?m)^\s*package\s+([A-Za-z_$][\w$.]*)\s*;", source_text)
    filter_package = str(package_match.group(1) if package_match else "").strip()
    core_package = filter_package.rsplit(".", 1)[0] if "." in filter_package else ""
    if not filter_package or not core_package:
        return {}
    return {
        "owner": class_name,
        "owner_fqn": f"{filter_package}.{class_name}",
        "filter_fqn": f"{filter_package}.TokenFilter",
        "parser_fqn": f"{core_package}.JsonParser",
        "factory_fqn": f"{core_package}.JsonFactory",
        "token_fqn": f"{core_package}.JsonToken",
        "rows": [
            {"row_id": "property_include_with_path", "input": '{\"keep\":1,\"skip\":2}', "kind": "property", "include_path": True},
            {"row_id": "property_include_without_path", "input": '{\"keep\":1,\"skip\":2}', "kind": "property", "include_path": False},
            {"row_id": "array_second_element", "input": "[1,2]", "kind": "element", "include_path": True},
            {"row_id": "scalar_include", "input": "1", "kind": "scalar_true", "include_path": False},
            {"row_id": "scalar_exclude", "input": "1", "kind": "scalar_false", "include_path": False},
        ] + (
            [
                {"row_id": "include_all_array", "input": "[1]", "kind": "include_all_array", "include_path": False},
                {"row_id": "include_all_object", "input": '{\"a\":1}', "kind": "include_all_object", "include_path": False},
                {"row_id": "null_filter_array", "input": "[1]", "kind": "null_filter", "include_path": False},
                {"row_id": "null_filter_object", "input": '{\"a\":1}', "kind": "null_filter", "include_path": False},
                {"row_id": "array_start_include_all", "input": "[1]", "kind": "array_start_include_all", "include_path": False},
                {"row_id": "object_start_include_all", "input": '{\"a\":1}', "kind": "object_start_include_all", "include_path": False},
                {"row_id": "root_reject_array", "input": "[1]", "kind": "root_reject", "include_path": False},
                {"row_id": "root_reject_object", "input": '{\"a\":1}', "kind": "root_reject", "include_path": False},
                {"row_id": "single_match_stop", "input": '{\"a\":1,\"b\":2}', "kind": "single_match_stop", "include_path": False, "allow_multiple": False},
                {"row_id": "second_match_rejected", "input": '{\"a\":1,\"b\":2}', "kind": "second_match_rejected", "include_path": True, "allow_multiple": False},
                {"row_id": "delayed_nested_array", "input": "[[0,1]]", "kind": "delayed_nested_array", "include_path": True},
            ]
            if structured_shortcuts_proven
            else []
        ),
        "target_descriptor": target_descriptor,
        "proof_status": "source_verified_filter_delegate_protocol_rows",
    }


def _deterministic_filter_delegate_variant_sources(
    *,
    candidate_code: str,
    replay_spec: dict[str, Any],
    max_variants: int = 20,
) -> list[dict[str, Any]]:
    """Build isolated tests for source-proven parser/filter outcome relations."""
    if not str(candidate_code or "").strip():
        return []
    owner = str(replay_spec.get("owner") or "").strip()
    owner_fqn = str(replay_spec.get("owner_fqn") or "").strip()
    filter_fqn = str(replay_spec.get("filter_fqn") or "").strip()
    parser_fqn = str(replay_spec.get("parser_fqn") or "").strip()
    factory_fqn = str(replay_spec.get("factory_fqn") or "").strip()
    token_fqn = str(replay_spec.get("token_fqn") or "").strip()
    if not all((owner, owner_fqn, filter_fqn, parser_fqn, factory_fqn, token_fqn)):
        return []
    variants: list[dict[str, Any]] = []
    for row in list(replay_spec.get("rows") or [])[: max(0, max_variants)]:
        row_id = str(row.get("row_id") or "")
        payload = json.dumps(str(row.get("input") or ""))
        kind = str(row.get("kind") or "")
        if not owner or not row_id or not kind:
            continue
        if kind == "property":
            filter_body = f"@Override public {filter_fqn} includeProperty(String name) {{ return \"keep\".equals(name) ? INCLUDE_ALL : null; }}"
            filter_declaration = f"new {filter_fqn}() {{ {filter_body} }}"
            assertion = f"org.junit.Assert.assertTrue(tokens.contains({token_fqn}.VALUE_NUMBER_INT));"
        elif kind == "element":
            filter_body = f"@Override public {filter_fqn} includeElement(int index) {{ return index == 1 ? INCLUDE_ALL : null; }}"
            filter_declaration = f"new {filter_fqn}() {{ {filter_body} }}"
            assertion = "org.junit.Assert.assertEquals(2, values.get(values.size() - 1).intValue());"
        elif kind == "scalar_true":
            filter_body = f"@Override public boolean includeValue({parser_fqn} p) {{ return true; }}"
            filter_declaration = f"new {filter_fqn}() {{ {filter_body} }}"
            assertion = "org.junit.Assert.assertEquals(java.util.Arrays.asList(1), values);"
        elif kind == "scalar_false":
            filter_body = f"@Override public boolean includeValue({parser_fqn} p) {{ return false; }}"
            filter_declaration = f"new {filter_fqn}() {{ {filter_body} }}"
            assertion = "org.junit.Assert.assertTrue(tokens.isEmpty());"
        elif kind == "include_all_array":
            filter_declaration = f"{filter_fqn}.INCLUDE_ALL"
            assertion = f"org.junit.Assert.assertEquals(java.util.Arrays.asList({token_fqn}.START_ARRAY, {token_fqn}.VALUE_NUMBER_INT, {token_fqn}.END_ARRAY), tokens);"
        elif kind == "include_all_object":
            filter_declaration = f"{filter_fqn}.INCLUDE_ALL"
            assertion = f"org.junit.Assert.assertEquals(java.util.Arrays.asList({token_fqn}.START_OBJECT, {token_fqn}.FIELD_NAME, {token_fqn}.VALUE_NUMBER_INT, {token_fqn}.END_OBJECT), tokens);"
        elif kind == "null_filter":
            filter_declaration = "null"
            assertion = "org.junit.Assert.assertTrue(tokens.isEmpty());"
        elif kind == "array_start_include_all":
            filter_declaration = f"new {filter_fqn}() {{ @Override public {filter_fqn} filterStartArray() {{ return INCLUDE_ALL; }} }}"
            assertion = f"org.junit.Assert.assertEquals({token_fqn}.START_ARRAY, tokens.get(0));"
        elif kind == "object_start_include_all":
            filter_declaration = f"new {filter_fqn}() {{ @Override public {filter_fqn} filterStartObject() {{ return INCLUDE_ALL; }} }}"
            assertion = f"org.junit.Assert.assertEquals({token_fqn}.START_OBJECT, tokens.get(0));"
        elif kind == "root_reject":
            filter_declaration = f"new {filter_fqn}() {{ @Override public {filter_fqn} includeRootValue(int index) {{ return null; }} }}"
            assertion = "org.junit.Assert.assertTrue(tokens.isEmpty());"
        elif kind in {"single_match_stop", "second_match_rejected"}:
            filter_declaration = f"new {filter_fqn}() {{ @Override public {filter_fqn} includeProperty(String name) {{ return INCLUDE_ALL; }} }}"
            assertion = "org.junit.Assert.assertEquals(java.util.Arrays.asList(1), values);"
        elif kind == "delayed_nested_array":
            filter_declaration = f"new {filter_fqn}() {{ @Override public {filter_fqn} includeElement(int index) {{ return index == 1 ? INCLUDE_ALL : this; }} @Override public {filter_fqn} filterStartArray() {{ return this; }} }}"
            assertion = "org.junit.Assert.assertTrue(values.contains(1));"
        else:
            continue
        test_name = f"testDeterministicFilterDelegateReplay_{row_id}"
        source = "\n".join([
            "@org.junit.Test",
            f"public void {test_name}() throws Exception {{",
            f"    {parser_fqn} parser = new {factory_fqn}().createParser({payload});",
            f"    {filter_fqn} filter = {filter_declaration};",
            f"    {owner_fqn} subject = new {owner_fqn}(parser, filter, {str(bool(row.get('include_path'))).lower()}, {str(bool(row.get('allow_multiple', True))).lower()});",
            f"    java.util.List<{token_fqn}> tokens = new java.util.ArrayList<{token_fqn}>();",
            "    java.util.List<Integer> values = new java.util.ArrayList<Integer>();",
            f"    {token_fqn} token;",
            f"    while ((token = subject.nextToken()) != null) {{ tokens.add(token); if (token == {token_fqn}.VALUE_NUMBER_INT) values.add(subject.getIntValue()); }}",
            f"    {assertion}",
            "}",
        ])
        variants.append({"row_id": row_id, "source": source, "test_method_name": test_name})
    return variants


def _source_verified_factory_variant_replay_spec(
    *,
    source_text: str,
    source_file: Path,
    class_name: str,
    method_name: str,
    target_descriptor: str = "",
) -> dict[str, Any]:
    """Find source-visible factory variants that feed a switch target.

    This is deliberately a proof gate, not a family-name heuristic.  The
    target must contain a switch, a non-private entry accepting the factory
    base type must reach it through the local call graph, and every emitted
    factory expression must come from a local source declaration whose return
    type is the base type or one of its source-declared subtypes.
    """
    try:
        from tatg.engines.tatg_adapter import TATGEngineAdapter

        blocks = TATGEngineAdapter()._collect_method_blocks(source_text)
    except Exception:
        return {}
    targets = [
        block for block in blocks
        if str(block.get("name") or "") == method_name
    ]
    if len(targets) != 1:
        return {}
    target_body = _strip_comments_preserve_literals(str(targets[0].get("body") or ""))
    if not re.search(r"\bswitch\s*\(", target_body):
        return {}

    # Build a conservative, local call graph.  Calls must resolve to exactly
    # one method name in this class; dynamic dispatch is intentionally out of
    # scope for deterministic replay.
    known_names = {str(block.get("name") or "") for block in blocks}
    calls_by_name: dict[str, set[str]] = {}
    for block in blocks:
        name = str(block.get("name") or "")
        body = _strip_comments_preserve_literals(str(block.get("body") or ""))
        calls_by_name[name] = {
            called for called in known_names
            if called != name and re.search(rf"\b{re.escape(called)}\s*\(", body)
        }

    def _reaches_target(entry: str) -> bool:
        frontier = [(entry, 0)]
        seen: set[str] = set()
        while frontier:
            current, depth = frontier.pop(0)
            if current == method_name:
                return True
            if current in seen or depth >= 5:
                continue
            seen.add(current)
            frontier.extend((called, depth + 1) for called in calls_by_name.get(current, set()))
        return False

    entry_candidates: list[tuple[str, str]] = []
    for block in blocks:
        if bool(block.get("is_private")):
            continue
        name = str(block.get("name") or "")
        signature = str(block.get("signature") or "")
        for parameter_type in _java_signature_parameter_types(signature, name):
            if parameter_type and _reaches_target(name):
                entry_candidates.append((name, parameter_type))
    if not entry_candidates:
        return {}

    source_dir = source_file.parent
    java_sources: list[tuple[Path, str]] = []
    try:
        for path in sorted(source_dir.glob("*.java")):
            java_sources.append((path, path.read_text(encoding="utf-8", errors="ignore")))
    except OSError:
        return {}
    declared_subtypes: dict[str, set[str]] = {}
    for _, text in java_sources:
        clean = _strip_comments_preserve_literals(text)
        for match in re.finditer(
            r"\b(?:public\s+)?(?:abstract\s+|final\s+)?class\s+"
            r"(?P<name>[A-Za-z_$][\w$]*)\s+extends\s+"
            r"(?P<base>[A-Za-z_$][\w$]*)\b",
            clean,
        ):
            declared_subtypes.setdefault(match.group("base"), set()).add(match.group("name"))

    def _all_subtypes(base: str) -> set[str]:
        result = {base}
        frontier = [base]
        while frontier:
            parent = frontier.pop()
            for child in declared_subtypes.get(parent, set()):
                if child not in result:
                    result.add(child)
                    frontier.append(child)
        return result

    def _argument_for_type(type_text: str) -> str | None:
        compact = re.sub(r"\s+", "", str(type_text or ""))
        simple = _normalized_java_type_identity(type_text)
        if simple == "String":
            return '"tatg"'
        if simple in {"double", "Double", "float", "Float"}:
            return "2.0"
        if simple in {"int", "Integer", "long", "Long", "short", "Short", "byte", "Byte"}:
            return "2"
        if simple in {"boolean", "Boolean"}:
            return "false"
        if compact in {"Set<String>", "java.util.Set<String>"}:
            return 'java.util.Collections.singleton("tatg")'
        if compact in {"Set<Double>", "java.util.Set<Double>"}:
            return "java.util.Collections.singleton(2.0)"
        return None

    for entry_name, base_type in entry_candidates:
        allowed_returns = _all_subtypes(base_type)
        factories: list[dict[str, Any]] = []
        for _, text in java_sources:
            clean = _strip_comments_preserve_literals(text)
            owner_match = re.search(
                r"\b(?:public\s+)?(?:abstract\s+|final\s+)?class\s+"
                r"(?P<name>[A-Za-z_$][\w$]*)\b",
                clean,
            )
            if not owner_match:
                continue
            owner = owner_match.group("name")
            for match in re.finditer(
                r"\bpublic\s+static\s+(?P<return>[A-Za-z_$][\w$]*)\s+"
                r"(?P<name>[A-Za-z_$][\w$]*)\s*\((?P<params>[^()]*)\)",
                clean,
                re.DOTALL,
            ):
                return_type = match.group("return")
                if return_type not in allowed_returns:
                    continue
                parameters = _split_top_level_java_args(match.group("params"))
                arguments: list[str] = []
                for parameter in parameters:
                    parameter_match = re.match(
                        r"(?:final\s+)?(?P<type>.+?)\s+[A-Za-z_$][\w$]*\s*$",
                        parameter.strip(),
                    )
                    argument = (
                        _argument_for_type(parameter_match.group("type"))
                        if parameter_match
                        else None
                    )
                    if argument is None:
                        arguments = []
                        break
                    arguments.append(argument)
                if parameters and not arguments:
                    continue
                expression = f"{owner}.{match.group('name')}({', '.join(arguments)})"
                factories.append({
                    "factory_id": f"{owner}.{match.group('name')}",
                    "expression": expression,
                    "return_type": return_type,
                })
        unique: dict[str, dict[str, Any]] = {}
        for row in factories:
            unique.setdefault(str(row["factory_id"]), row)
        if len(unique) >= 3:
            ordered = sorted(
                unique.values(),
                key=lambda row: (
                    0 if str(row["factory_id"]).split(".", 1)[0] == base_type else 1,
                    str(row["factory_id"]),
                ),
            )
            return {
                "entry_method": entry_name,
                "base_type": base_type,
                "factories": ordered[:24],
                "target_descriptor": target_descriptor,
                "proof_status": "source_verified_factory_call_graph",
            }
    return {}


def _deterministic_factory_variant_sources(
    *,
    candidate_code: str,
    replay_spec: dict[str, Any],
    max_variants: int = 16,
) -> list[dict[str, Any]]:
    """Replace one proven factory seed while preserving entry and oracle."""
    code = str(candidate_code or "")
    entry_method = str(replay_spec.get("entry_method") or "")
    factories = list(replay_spec.get("factories") or [])
    blocks = _junit_test_method_blocks(code)
    if len(blocks) != 1 or not entry_method or len(factories) < 3:
        return []
    test_name, test_block = blocks[0]
    if not test_code_calls_any_method(test_block, [entry_method]):
        return []
    present: list[tuple[dict[str, Any], int, int]] = []
    for factory in factories:
        factory_id = str(factory.get("factory_id") or "")
        marker = re.search(rf"\b{re.escape(factory_id)}\s*\(", test_block)
        if not marker:
            continue
        open_paren = test_block.find("(", marker.start())
        close_paren = _find_matching_paren_for_text(test_block, open_paren)
        if close_paren >= 0:
            present.append((factory, marker.start(), close_paren + 1))
    if len(present) != 1:
        return []
    seed, start, end = present[0]
    seed_factory_id = str(seed.get("factory_id") or "")
    seed_expression = test_block[start:end]
    variants: list[dict[str, Any]] = []
    for factory in factories:
        expression = str(factory.get("expression") or "")
        if (
            not expression
            or str(factory.get("factory_id") or "") == seed_factory_id
            or len(variants) >= max_variants
        ):
            continue
        suffix = re.sub(r"[^A-Za-z0-9_$]+", "_", str(factory.get("factory_id") or "")).strip("_")
        variant_name = f"{test_name}__factory_{suffix}"[:180]
        variant_block = test_block[:start] + expression + test_block[end:]
        variant_block = re.sub(
            rf"\b{re.escape(test_name)}\s*(?=\()",
            variant_name,
            variant_block,
            count=1,
        )
        variants.append({
            "row_id": str(factory.get("factory_id") or ""),
            "source": code.replace(test_block, variant_block, 1),
            "test_method_name": variant_name,
            "seed_expression": seed_expression,
            "variant_expression": expression,
            "proof_status": "source_proven_unvalidated_factory_variant",
        })
    return variants


def _source_verified_array_config_replay_spec(
    *,
    source_text: str,
    source_file: Path,
    class_name: str,
    method_name: str,
    target_descriptor: str = "",
) -> dict[str, Any]:
    """Prove a finite array/configuration decision tree from local source.

    The accepted shape is intentionally narrow: a constructor-reached target
    reads a String array from a configuration field, distinguishes
    null/empty/non-empty input, and has source-visible builder controls for
    missing and duplicate values.  This gives deterministic normal and exact
    exception rows without asking the model to invent setup APIs.
    """
    signature, body = _source_backed_exact_target_method_source(
        source_text=source_text,
        class_name=class_name,
        method_name=method_name,
        target_descriptor=target_descriptor,
    )
    if not signature or not body:
        return {}
    clean_source = _strip_comments_preserve_literals(source_text)
    clean_body = _strip_comments_preserve_literals(body)
    array_match = re.search(
        r"\bString\s*\[\]\s+(?P<local>[A-Za-z_$][\w$]*)\s*=\s*"
        r"this\.(?P<field>[A-Za-z_$][\w$]*)\.(?P<getter>get[A-Za-z_$][\w$]*)\s*\(\s*\)\s*;",
        clean_body,
    )
    if not array_match:
        return {}
    local = array_match.group("local")
    field = array_match.group("field")
    array_getter = array_match.group("getter")
    if not (
        re.search(rf"\bif\s*\(\s*{re.escape(local)}\s*!=\s*null\s*\)", clean_body)
        and re.search(rf"\b{re.escape(local)}\.length\s*==\s*0\b", clean_body)
        and re.search(r"\bfor\s*\(", clean_body)
    ):
        return {}
    field_match = re.search(
        rf"\b(?:private|protected|public)?\s*(?:final\s+)?"
        rf"(?P<type>[A-Za-z_$][\w$]*)\s+{re.escape(field)}\s*;",
        clean_source,
    )
    if not field_match:
        return {}
    config_type = field_match.group("type")
    bool_getters = _unique_preserve_order(re.findall(
        rf"this\.{re.escape(field)}\.(get[A-Za-z_$][\w$]*)\s*\(\s*\)",
        clean_body,
    ))
    missing_getter = next(
        (
            getter for getter in bool_getters
            if getter != array_getter
            and re.search(
                rf"!\s*this\.{re.escape(field)}\.{re.escape(getter)}\s*\(\s*\)",
                clean_body,
            )
        ),
        "",
    )
    skip_getter = next(
        (
            getter for getter in bool_getters
            if getter not in {array_getter, missing_getter}
            and re.search(
                rf"this\.{re.escape(field)}\.{re.escape(getter)}\s*\(\s*\)",
                clean_body,
            )
        ),
        "",
    )
    enum_assignment = re.search(
        rf"\b(?P<enum>[A-Za-z_$][\w$]*)\s+(?P<var>[A-Za-z_$][\w$]*)\s*=\s*"
        rf"this\.{re.escape(field)}\.(?P<getter>get[A-Za-z_$][\w$]*)\s*\(\s*\)\s*;",
        clean_body,
    )
    if not missing_getter or not skip_getter or not enum_assignment:
        return {}
    enum_type = enum_assignment.group("enum")
    enum_var = enum_assignment.group("var")
    duplicate_getter = enum_assignment.group("getter")
    allowed_constants = _unique_preserve_order(re.findall(
        rf"\b{re.escape(enum_var)}\s*==\s*{re.escape(enum_type)}\.([A-Za-z_$][\w$]*)",
        clean_body,
    ))
    exception_types = _unique_preserve_order(re.findall(
        r"\bthrow\s+new\s+([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*)\s*\(",
        clean_body,
    ))
    if len(allowed_constants) < 2 or len(exception_types) != 1:
        return {}

    config_file = source_file.with_name(f"{config_type}.java")
    enum_file = source_file.with_name(f"{enum_type}.java")
    try:
        config_source = _strip_comments_preserve_literals(
            config_file.read_text(encoding="utf-8", errors="ignore")
        )
        enum_source = _strip_comments_preserve_literals(
            enum_file.read_text(encoding="utf-8", errors="ignore")
        )
    except OSError:
        return {}
    array_suffix = array_getter[3:]
    missing_suffix = missing_getter[3:]
    skip_suffix = skip_getter[3:]
    duplicate_suffix = duplicate_getter[3:]
    array_setter = f"set{array_suffix}"
    missing_setter = f"set{missing_suffix}"
    skip_setter = f"set{skip_suffix}"
    duplicate_setter = f"set{duplicate_suffix}"
    required_builder_patterns = (
        rf"\b{re.escape(array_setter)}\s*\(\s*(?:final\s+)?String\s*\.\.\.",
        rf"\b{re.escape(missing_setter)}\s*\(\s*(?:final\s+)?boolean\b",
        rf"\b{re.escape(skip_setter)}\s*\(\s*(?:final\s+)?boolean\b",
        rf"\b{re.escape(duplicate_setter)}\s*\(\s*(?:final\s+)?{re.escape(enum_type)}\b",
        r"\bbuild\s*\(\s*\)",
    )
    if not all(re.search(pattern, config_source) for pattern in required_builder_patterns):
        return {}
    enum_decl = re.search(
        rf"\benum\s+{re.escape(enum_type)}\s*\{{(?P<body>[^;}}]+)",
        enum_source,
        re.DOTALL,
    )
    if not enum_decl:
        return {}
    enum_constants = _unique_preserve_order(re.findall(
        r"\b([A-Z][A-Z0-9_]*)\b", enum_decl.group("body")
    ))
    reject_constants = [value for value in enum_constants if value not in allowed_constants]
    if not reject_constants:
        return {}

    # The constructor is the exact source-visible entry and must assign the
    # private target's result.  This avoids ever emitting a direct private call.
    try:
        from tatg.engines.tatg_adapter import TATGEngineAdapter

        constructor_blocks = [
            block for block in TATGEngineAdapter()._collect_method_blocks(source_text)
            if str(block.get("name") or "") == class_name
            and not bool(block.get("is_private"))
        ]
    except Exception:
        constructor_blocks = []
    direct_constructor_params: list[list[str]] = []
    for constructor in constructor_blocks:
        params = _java_signature_parameter_types(
            str(constructor.get("signature") or ""), class_name
        )
        if config_type in params and re.search(
            rf"\b{re.escape(method_name)}\s*\(\s*\)",
            _strip_comments_preserve_literals(str(constructor.get("body") or "")),
        ):
            direct_constructor_params.append(params)
    constructor_params: list[str] = []
    for constructor in constructor_blocks:
        params = _java_signature_parameter_types(
            str(constructor.get("signature") or ""), class_name
        )
        if len(params) != 2 or config_type not in params:
            continue
        constructor_body = _strip_comments_preserve_literals(
            str(constructor.get("body") or "")
        )
        delegates = bool(re.search(r"\bthis\s*\(", constructor_body))
        if params in direct_constructor_params or any(
            delegates and target_params[:2] == params
            for target_params in direct_constructor_params
        ):
            constructor_params = params
            break
    if len(constructor_params) != 2 or config_type not in constructor_params:
        return {}
    other_param = next(value for value in constructor_params if value != config_type)
    if other_param not in {"Reader", "StringReader"}:
        return {}

    result_field_match = re.search(
        rf"this\.(?P<field>[A-Za-z_$][\w$]*)\s*=\s*{re.escape(method_name)}\s*\(\s*\)\s*;",
        clean_source,
    )
    result_field = str(result_field_match.group("field") if result_field_match else "")
    observer = ""
    if result_field:
        for method in re.finditer(
            r"\bpublic\s+(?:java\.util\.)?Map(?:\s*<[^>{}]+>)?\s+"
            r"(?P<name>[A-Za-z_$][\w$]*)\s*\(\s*\)\s*\{(?P<body>.*?)\n\s*\}",
            clean_source,
            re.DOTALL,
        ):
            if re.search(rf"\b{re.escape(result_field)}\b", method.group("body")):
                observer = method.group("name")
                break
    if not observer:
        return {}
    package_match = re.search(r"(?m)^\s*package\s+([A-Za-z_$][\w$.]*)\s*;", source_text)
    package_name = str(package_match.group(1) if package_match else "")
    return {
        "owner": class_name,
        "owner_fqn": f"{package_name}.{class_name}" if package_name else class_name,
        "config_type": config_type,
        "config_fqn": f"{package_name}.{config_type}" if package_name else config_type,
        "array_setter": array_setter,
        "missing_setter": missing_setter,
        "skip_setter": skip_setter,
        "duplicate_setter": duplicate_setter,
        "enum_fqn": f"{package_name}.{enum_type}" if package_name else enum_type,
        "allow_all_constant": allowed_constants[0],
        "reject_constant": reject_constants[0],
        "exception_type": exception_types[0],
        "observer": observer,
        "target_descriptor": target_descriptor,
        "proof_status": "source_verified_array_configuration_tree",
    }


def _deterministic_array_config_variant_sources(
    *,
    candidate_code: str,
    replay_spec: dict[str, Any],
    max_variants: int = 8,
) -> list[dict[str, Any]]:
    """Build normal and exception rows from a proven green config scaffold."""
    code = str(candidate_code or "")
    blocks = _junit_test_method_blocks(code)
    if len(blocks) != 1 or max_variants <= 0:
        return []
    _, test_block = blocks[0]
    owner = str(replay_spec.get("owner") or "")
    owner_fqn = str(replay_spec.get("owner_fqn") or "")
    config_type = str(replay_spec.get("config_type") or "")
    config_fqn = str(replay_spec.get("config_fqn") or "")
    array_setter = str(replay_spec.get("array_setter") or "")
    missing_setter = str(replay_spec.get("missing_setter") or "")
    skip_setter = str(replay_spec.get("skip_setter") or "")
    duplicate_setter = str(replay_spec.get("duplicate_setter") or "")
    enum_fqn = str(replay_spec.get("enum_fqn") or "")
    allow_all = str(replay_spec.get("allow_all_constant") or "")
    reject = str(replay_spec.get("reject_constant") or "")
    exception_type = str(replay_spec.get("exception_type") or "")
    observer = str(replay_spec.get("observer") or "")
    required = (
        owner, owner_fqn, config_type, config_fqn, array_setter,
        missing_setter, skip_setter, duplicate_setter, enum_fqn, allow_all, reject,
        exception_type, observer,
    )
    if not all(required):
        return []
    config_assignment = re.search(
        rf"\b(?:final\s+)?{re.escape(config_type)}\s+[A-Za-z_$][\w$]*\s*=\s*"
        rf"(?P<base>{re.escape(config_type)}\.[A-Z][A-Z0-9_]*)[^;]*;",
        test_block,
    )
    if not config_assignment:
        return []
    base = config_assignment.group("base")
    content_assignment = re.search(
        r"\b(?:final\s+)?String\s+[A-Za-z_$][\w$]*\s*=\s*(?P<expr>[^;]+);",
        test_block,
    )
    if not content_assignment:
        return []
    literals = re.findall(r'"((?:\\.|[^"\\])*)"', content_assignment.group("expr"))
    if not literals:
        return []
    try:
        decoded_literals = [json.loads(f'"{literal}"') for literal in literals]
    except (TypeError, ValueError, json.JSONDecodeError):
        return []
    if len(decoded_literals) >= 2:
        first_row = decoded_literals[0]
        data_row = decoded_literals[-1]
    else:
        physical_rows = [row for row in decoded_literals[0].splitlines() if row]
        if len(physical_rows) >= 2:
            first_row = physical_rows[0]
            data_row = physical_rows[-1]
        elif len(physical_rows) == 1:
            configured_header = re.search(
                rf"\b{re.escape(array_setter)}\s*\((?P<args>[^()]*)\)",
                config_assignment.group(0),
            )
            if not configured_header:
                return []
            header_literals = re.findall(
                r'"((?:\\.|[^"\\])*)"', configured_header.group("args")
            )
            try:
                configured_columns = [
                    json.loads(f'"{literal}"') for literal in header_literals
                ]
            except (TypeError, ValueError, json.JSONDecodeError):
                return []
            if len(configured_columns) < 2 or any(
                not value for value in configured_columns
            ):
                return []
            data_row = physical_rows[0]
            delimiter_candidates = [
                ch for ch in data_row if not ch.isalnum() and not ch.isspace()
            ]
            delimiter = next(
                (
                    ch
                    for ch in delimiter_candidates
                    if len(data_row.split(ch)) == len(configured_columns)
                ),
                "",
            )
            if not delimiter:
                return []
            first_row = delimiter.join(configured_columns)
        else:
            return []
    delimiters = [ch for ch in first_row if not ch.isalnum() and not ch.isspace()]
    delimiter = next((ch for ch in delimiters if ch in data_row), "")
    if not delimiter:
        return []
    columns = first_row.split(delimiter)
    values = data_row.split(delimiter)
    if len(columns) < 2 or len(values) != len(columns) or any(not value for value in columns):
        return []
    quoted_columns = ", ".join(json.dumps(value) for value in columns)
    blank_columns = ", ".join([json.dumps("")] + [json.dumps(value) for value in columns[1:]])
    duplicate_columns = ", ".join(json.dumps(columns[0]) for _ in columns)
    full_input = json.dumps(first_row + "\n" + data_row)
    data_input = json.dumps(data_row)
    duplicate_input = json.dumps(delimiter.join([columns[0]] * len(columns)) + "\n" + data_row)
    builder = f"{base}.builder()"
    rows = [
        ("config_absent", base, data_input, "null", False),
        ("array_empty_from_input", f"{builder}.{array_setter}().build()", full_input, columns[0], False),
        ("array_explicit_skip", f"{builder}.{array_setter}({quoted_columns}).{skip_setter}(true).build()", full_input, columns[0], False),
        ("blank_allowed", f"{builder}.{array_setter}({blank_columns}).{missing_setter}(true).build()", data_input, "", False),
        ("duplicate_allowed", f"{builder}.{array_setter}({duplicate_columns}).{duplicate_setter}({enum_fqn}.{allow_all}).build()", data_input, columns[0], False),
        ("blank_rejected", f"{builder}.{array_setter}({blank_columns}).{missing_setter}(false).build()", data_input, "", True),
        ("duplicate_input_rejected", f"{builder}.{array_setter}().{duplicate_setter}({enum_fqn}.{reject}).build()", duplicate_input, columns[0], True),
    ]
    junit5 = "org.junit.jupiter" in code
    annotation = "@org.junit.jupiter.api.Test" if junit5 else "@org.junit.Test"
    assertions = "org.junit.jupiter.api.Assertions" if junit5 else "org.junit.Assert"
    class_match = re.search(
        r"\b(?:public\s+)?(?:final\s+)?class\s+[A-Za-z_$][\w$]*[^\{]*\{",
        code,
    )
    if not class_match:
        return []
    class_open = code.find("{", class_match.start())
    if class_open < 0:
        return []
    scaffold = code[: class_open + 1].rstrip() + "\n}\n"
    variants: list[dict[str, Any]] = []
    for row_id, config_expression, input_expression, expected_key, expect_exception in rows[:max_variants]:
        test_name = f"testDeterministicArrayConfigReplay_{row_id}"
        lines = [annotation, f"public void {test_name}() throws Exception {{", f"    {config_fqn} config = {config_expression};"]
        constructor = f"new {owner_fqn}(new java.io.StringReader({input_expression}), config)"
        if expect_exception:
            if junit5:
                lines.append(f"    {assertions}.assertThrows({exception_type}.class, () -> {constructor});")
            else:
                lines.extend([
                    f"    try {{ {constructor}; {assertions}.fail(\"expected {exception_type}\"); }}",
                    f"    catch ({exception_type} expected) {{ {assertions}.assertNotNull(expected.getMessage()); }}",
                ])
        else:
            lines.append(f"    try ({owner_fqn} subject = {constructor}) {{")
            if expected_key == "null":
                lines.append(f"        {assertions}.assertNull(subject.{observer}());")
            else:
                lines.append(f"        {assertions}.assertTrue(subject.{observer}().containsKey({json.dumps(expected_key)}));")
            lines.append("    }")
        lines.append("}")
        method_block = "\n".join(lines)
        source = _insert_test_method_into_candidate_class(scaffold, method_block)
        if source:
            variants.append({
                "row_id": row_id,
                "source": source,
                "test_method_name": test_name,
                "proof_status": "source_proven_unvalidated_array_config_variant",
            })
    return variants


def _source_verified_sax_callback_replay_spec(
    *,
    source_text: str,
    source_file: Path,
    class_name: str,
    method_name: str,
    target_descriptor: str = "",
) -> dict[str, Any]:
    """Prove a standard SAX element callback decision tree from source."""
    signature, body = _source_backed_exact_target_method_source(
        source_text=source_text,
        class_name=class_name,
        method_name=method_name,
        target_descriptor=target_descriptor,
    )
    if not signature or not body or not re.search(r"\bpublic\b", signature):
        return {}
    params = [
        re.sub(r"\s+", "", str(type_name or "")).split("<", 1)[0]
        for type_name, _name in _method_parameter_bindings(
            f"{signature} {{{body}}}", target_descriptor
        )
    ]
    if not params or any(
        not re.fullmatch(r"[A-Za-z_$][\w$]*(?:\[\])?", value)
        for value in params
    ):
        try:
            from tatg.engines.tatg_adapter import TATGEngineAdapter

            params = _java_signature_parameter_types(
                TATGEngineAdapter._strip_balanced_java_annotations(signature),
                method_name,
            )
        except Exception:
            params = []
    simple_params = [value.rsplit(".", 1)[-1] for value in params]
    if simple_params != ["String", "String", "String", "Attributes"]:
        return {}
    clean_body = _strip_comments_preserve_literals(body)
    required_body_evidence = (
        r"\.indexOf\s*\(\s*['\"]:['\"]\s*\)",
        r"\bgetLength\s*\(\s*\)",
        r"\binstanceof\s+Attributes2\b",
        r"\bXMLConstants\.XMLNS_ATTRIBUTE_NS_URI\b",
        r"\bcurrentLocator\b",
        r"\batRoot\b",
        r"\bsuppress\b",
    )
    if not all(re.search(pattern, clean_body) for pattern in required_body_evidence):
        return {}
    declared_match = re.search(
        r"\bif\s*\(\s*(?P<field>[A-Za-z_$][\w$]*)\.size\s*\(\s*\)\s*>\s*0",
        clean_body,
    )
    if not declared_match:
        return {}
    namespace_field = declared_match.group("field")

    try:
        from tatg.engines.tatg_adapter import TATGEngineAdapter

        blocks = TATGEngineAdapter()._collect_method_blocks(source_text)
    except Exception:
        return {}

    def public_blocks() -> list[dict[str, Any]]:
        return [
            block
            for block in blocks
            if re.search(r"\bpublic\b", str(block.get("signature") or ""))
        ]

    visible = public_blocks()
    constructor_ok = any(
        str(block.get("name") or "") == class_name
        and not _java_signature_parameter_types(
            str(block.get("signature") or ""), class_name
        )
        for block in visible
    )
    if not constructor_ok:
        return {}

    def method_params(block: dict[str, Any]) -> list[str]:
        name = str(block.get("name") or "")
        return [
            value.rsplit(".", 1)[-1]
            for value in _java_signature_parameter_types(
                str(block.get("signature") or ""), name
            )
        ]

    prefix_block = next(
        (
            block for block in visible
            if method_params(block) == ["String", "String"]
            and re.search(
                rf"\b{re.escape(namespace_field)}\.add\s*\(",
                _strip_comments_preserve_literals(str(block.get("body") or "")),
            )
        ),
        None,
    )
    locator_block = next(
        (
            block for block in visible
            if method_params(block) == ["Locator"]
            and "currentLocator" in str(block.get("body") or "")
        ),
        None,
    )
    document_block = next(
        (
            block for block in visible
            if not method_params(block)
            and re.search(r"\bDocument\b", str(block.get("signature") or ""))
            and re.search(
                r"\breturn\s+currentDocument\s*;",
                _strip_comments_preserve_literals(str(block.get("body") or "")),
            )
        ),
        None,
    )
    suppress_true_block = next(
        (
            block for block in visible
            if method_params(block) == ["String"]
            and re.search(
                r"\bsuppress\s*=\s*true\s*;",
                _strip_comments_preserve_literals(str(block.get("body") or "")),
            )
        ),
        None,
    )
    suppress_false_block = next(
        (
            block for block in visible
            if method_params(block) == ["String"]
            and re.search(
                r"\bsuppress\s*=\s*false\s*;",
                _strip_comments_preserve_literals(str(block.get("body") or "")),
            )
        ),
        None,
    )
    if not all(
        (prefix_block, locator_block, document_block, suppress_true_block, suppress_false_block)
    ):
        return {}
    true_body = _strip_comments_preserve_literals(
        str(suppress_true_block.get("body") or "")
    )
    negated_fields = list(
        dict.fromkeys(
            re.findall(r"!\s*([A-Za-z_$][\w$]*)", true_body)
        )
    )
    expand_setter = None
    expand_field = ""
    for candidate_field in negated_fields:
        candidate_setter = next(
            (
                block for block in visible
                if method_params(block) == ["boolean"]
                and re.search(
                    rf"\b(?:this\.)?{re.escape(candidate_field)}\s*=\s*[A-Za-z_$][\w$]*\s*;",
                    _strip_comments_preserve_literals(str(block.get("body") or "")),
                )
            ),
            None,
        )
        if candidate_setter:
            expand_field = candidate_field
            expand_setter = candidate_setter
            break
    if not expand_setter:
        return {}

    package_match = re.search(r"(?m)^\s*package\s+([A-Za-z_$][\w$.]*)\s*;", source_text)
    package_name = str(package_match.group(1) if package_match else "")
    imports = {
        fqn.rsplit(".", 1)[-1]: fqn
        for fqn in re.findall(
            r"(?m)^\s*import\s+([A-Za-z_$][\w$.]*)\s*;",
            source_text,
        )
    }
    document_fqn = str(imports.get("Document") or "")
    if not package_name or not document_fqn:
        return {}
    source_root = source_file.parent
    for part in reversed(package_name.split(".")):
        if source_root.name != part:
            return {}
        source_root = source_root.parent
    document_file = source_root / Path(*document_fqn.split(".")).with_suffix(".java")
    element_fqn = f"{document_fqn.rsplit('.', 1)[0]}.Element"
    element_file = source_root / Path(*element_fqn.split(".")).with_suffix(".java")
    try:
        document_source = _strip_comments_preserve_literals(
            document_file.read_text(encoding="utf-8", errors="ignore")
        )
        element_source = _strip_comments_preserve_literals(
            element_file.read_text(encoding="utf-8", errors="ignore")
        )
    except OSError:
        return {}
    if not re.search(r"\bpublic\s+Element\s+getRootElement\s*\(\s*\)", document_source):
        return {}
    required_observers = (
        "getName", "getNamespacePrefix", "getNamespace", "getChild",
        "getAttributes", "getAttributeValue", "getAttribute",
    )
    if not all(
        re.search(rf"\bpublic\b[^;{{}}]*\b{re.escape(name)}\s*\(", element_source)
        for name in required_observers
    ):
        return {}
    return {
        "owner_fqn": f"{package_name}.{class_name}",
        "target_method": method_name,
        "prefix_method": str(prefix_block.get("name") or ""),
        "locator_method": str(locator_block.get("name") or ""),
        "document_method": str(document_block.get("name") or ""),
        "expand_setter": str(expand_setter.get("name") or ""),
        "suppress_start_method": str(suppress_true_block.get("name") or ""),
        "suppress_end_method": str(suppress_false_block.get("name") or ""),
        "target_descriptor": target_descriptor,
        "proof_status": "source_verified_sax_callback_state_tree",
    }


def _deterministic_sax_callback_matrix_source(
    *,
    candidate_code: str,
    replay_spec: dict[str, Any],
) -> dict[str, Any]:
    """Build one isolated matrix covering a source-proven SAX callback tree."""
    code = str(candidate_code or "")
    class_match = re.search(
        r"\b(?:public\s+)?(?:final\s+)?class\s+[A-Za-z_$][\w$]*[^\{]*\{",
        code,
    )
    required = (
        "owner_fqn", "target_method", "prefix_method", "locator_method",
        "document_method", "expand_setter", "suppress_start_method",
        "suppress_end_method",
    )
    if not class_match or not all(str(replay_spec.get(key) or "") for key in required):
        return {}
    class_open = code.find("{", class_match.start())
    if class_open < 0:
        return {}
    scaffold = code[: class_open + 1].rstrip() + "\n}\n"
    owner = str(replay_spec["owner_fqn"])
    target = str(replay_spec["target_method"])
    prefix = str(replay_spec["prefix_method"])
    locator = str(replay_spec["locator_method"])
    document = str(replay_spec["document_method"])
    expand = str(replay_spec["expand_setter"])
    suppress_start = str(replay_spec["suppress_start_method"])
    suppress_end = str(replay_spec["suppress_end_method"])
    junit5 = "org.junit.jupiter" in code
    annotation = "@org.junit.jupiter.api.Test" if junit5 else "@org.junit.Test"
    assertions = "org.junit.jupiter.api.Assertions" if junit5 else "org.junit.Assert"
    name = "testDeterministicSaxCallbackMatrix"
    lines = [annotation, f"public void {name}() throws Exception {{"]
    lines.extend([
        f"    {owner} h1 = new {owner}();",
        "    org.xml.sax.helpers.AttributesImpl a1 = new org.xml.sax.helpers.AttributesImpl();",
        '    a1.addAttribute("", "", "id", "CDATA", "7");',
        f'    h1.{target}("", "", "root", a1);',
        f'    {assertions}.assertEquals("root", h1.{document}().getRootElement().getName());',
        f'    {assertions}.assertEquals("7", h1.{document}().getRootElement().getAttributeValue("id"));',
        f"    {owner} h2 = new {owner}();",
        f'    h2.{prefix}("p", "urn:root");',
        f'    h2.{prefix}("extra", "urn:extra");',
        f'    h2.{target}("urn:root", "node", "p:node", new org.xml.sax.helpers.AttributesImpl());',
        f'    {assertions}.assertEquals("p", h2.{document}().getRootElement().getNamespacePrefix());',
        f'    {assertions}.assertEquals("urn:extra", h2.{document}().getRootElement().getNamespace("extra").getURI());',
        f"    {owner} h3 = new {owner}();",
        f'    h3.{target}("", "root", "root", new org.xml.sax.helpers.AttributesImpl());',
        f'    h3.{target}("", "child", "child", new org.xml.sax.helpers.AttributesImpl());',
        f'    {assertions}.assertEquals("child", h3.{document}().getRootElement().getChild("child").getName());',
        f"    {owner} h4 = new {owner}();",
        "    org.xml.sax.helpers.AttributesImpl a4 = new org.xml.sax.helpers.AttributesImpl();",
        '    a4.addAttribute("http://www.w3.org/2000/xmlns/", "p", "xmlns:p", "CDATA", "urn:p");',
        f'    h4.{target}("", "root", "root", a4);',
        f'    {assertions}.assertTrue(h4.{document}().getRootElement().getAttributes().isEmpty());',
        f"    {owner} h5 = new {owner}();",
        f'    h5.{prefix}("a", "urn:attribute");',
        "    org.xml.sax.helpers.AttributesImpl a5 = new org.xml.sax.helpers.AttributesImpl();",
        '    a5.addAttribute("urn:attribute", "flag", "", "CDATA", "yes");',
        f'    h5.{target}("", "root", "root", a5);',
        f'    {assertions}.assertEquals("a", h5.{document}().getRootElement().getAttributes().get(0).getNamespacePrefix());',
        f"    {owner} h6 = new {owner}();",
        "    org.xml.sax.ext.Attributes2Impl a6 = new org.xml.sax.ext.Attributes2Impl();",
        '    a6.addAttribute("", "mode", "mode", "CDATA", "default");',
        "    a6.setSpecified(0, false);",
        f'    h6.{target}("", "root", "root", a6);',
        f'    {assertions}.assertFalse(h6.{document}().getRootElement().getAttribute("mode").isSpecified());',
        f"    {owner} h7 = new {owner}();",
        f"    h7.{expand}(false);",
        f'    h7.{suppress_start}("custom");',
        f'    h7.{target}("", "hidden", "hidden", new org.xml.sax.helpers.AttributesImpl());',
        f'    {assertions}.assertThrows(IllegalStateException.class, () -> h7.{document}().getRootElement());',
        f'    h7.{suppress_end}("custom");',
        f"    {owner} h8 = new {owner}();",
        "    org.xml.sax.helpers.LocatorImpl l8 = new org.xml.sax.helpers.LocatorImpl();",
        "    l8.setLineNumber(12); l8.setColumnNumber(7);",
        f"    h8.{locator}(l8);",
        f'    h8.{target}("urn:root", "root", "", new org.xml.sax.helpers.AttributesImpl());',
        f'    {assertions}.assertEquals("urn:root", h8.{document}().getRootElement().getNamespaceURI());',
        f"    {owner} h9 = new {owner}();",
        "    org.xml.sax.helpers.AttributesImpl a9 = new org.xml.sax.helpers.AttributesImpl();",
        '    a9.addAttribute("urn:a", "", "a:flag", "CDATA", "yes");',
        f'    h9.{target}("", "root", "root", a9);',
        f'    {assertions}.assertEquals("flag", h9.{document}().getRootElement().getAttributes().get(0).getName());',
        f"    {owner} h10 = new {owner}();",
        f'    h10.{prefix}("attns0", "urn:occupied");',
        "    org.xml.sax.helpers.AttributesImpl a10 = new org.xml.sax.helpers.AttributesImpl();",
        '    a10.addAttribute("urn:target", "flag", "", "CDATA", "yes");',
        f'    h10.{target}("", "root", "root", a10);',
        f'    {assertions}.assertEquals("attns1", h10.{document}().getRootElement().getAttributes().get(0).getNamespacePrefix());',
        f"    {owner} h11 = new {owner}();",
        "    org.xml.sax.helpers.AttributesImpl a11 = new org.xml.sax.helpers.AttributesImpl();",
        '    a11.addAttribute("http://www.w3.org/2000/xmlns/", "p", "", "CDATA", "urn:p");',
        f'    h11.{target}("", "root", "root", a11);',
        f'    {assertions}.assertTrue(h11.{document}().getRootElement().getAttributes().isEmpty());',
        "}",
    ])
    source = _insert_test_method_into_candidate_class(scaffold, "\n".join(lines))
    if not source:
        return {}
    return {
        "row_id": "sax_callback_state_matrix",
        "source": source,
        "test_method_name": name,
        "proof_status": "source_proven_unvalidated_sax_callback_matrix",
    }


def _source_verified_order_singularity_replay_spec(
    *,
    source_text: str,
    source_file: Path,
    class_name: str,
    method_name: str,
    target_descriptor: str = "",
) -> dict[str, Any]:
    """Prove an enum-like order dispatch with source-visible singular bounds."""
    signature, body = _source_backed_exact_target_method_source(
        source_text=source_text,
        class_name=class_name,
        method_name=method_name,
        target_descriptor=target_descriptor,
    )
    if not signature or not body or not re.search(r"\bpublic\b", signature):
        return {}
    params = [
        re.sub(r"\s+", "", str(type_name or "")).split("<", 1)[0]
        for type_name, _name in _method_parameter_bindings(
            f"{signature} {{{body}}}", target_descriptor
        )
    ]
    if len(params) != 1 or not re.search(r"\bdouble\s*\[\s*\]", signature):
        return {}
    order_type = params[0].rsplit(".", 1)[-1]
    clean_body = _strip_comments_preserve_literals(body)
    if not all(
        evidence in clean_body
        for evidence in ("0.9999999999", "applyTo", "applyInverseTo")
    ):
        return {}
    if not re.search(r"<\s*-\s*0\.9999999999", clean_body) or not re.search(
        r">\s*0\.9999999999", clean_body
    ):
        return {}

    package_match = re.search(
        r"(?m)^\s*package\s+([A-Za-z_$][\w$.]*)\s*;", source_text
    )
    package_name = str(package_match.group(1) if package_match else "")
    if not package_name:
        return {}
    imports = {
        fqn.rsplit(".", 1)[-1]: fqn
        for fqn in re.findall(
            r"(?m)^\s*import\s+([A-Za-z_$][\w$.]*)\s*;", source_text
        )
    }
    order_fqn = str(imports.get(order_type) or f"{package_name}.{order_type}")
    source_root = source_file.parent
    for part in reversed(package_name.split(".")):
        if source_root.name != part:
            return {}
        source_root = source_root.parent
    order_file = source_root / Path(*order_fqn.split(".")).with_suffix(".java")
    try:
        order_source = _strip_comments_preserve_literals(
            order_file.read_text(encoding="utf-8", errors="ignore")
        )
    except OSError:
        return {}
    constants = list(
        dict.fromkeys(
            re.findall(
                rf"\bpublic\s+static\s+final\s+{re.escape(order_type)}\s+([A-Za-z_$][\w$]*)\s*=",
                order_source,
            )
        )
    )
    if len(constants) < 12:
        return {}

    constructor_pattern = re.compile(
        rf"\bpublic\s+{re.escape(class_name)}\s*\(\s*"
        rf"{re.escape(order_type)}\s+[A-Za-z_$][\w$]*\s*,\s*"
        r"(?:final\s+)?double\s+[A-Za-z_$][\w$]*\s*,\s*"
        r"(?:final\s+)?double\s+[A-Za-z_$][\w$]*\s*,\s*"
        r"(?:final\s+)?double\s+[A-Za-z_$][\w$]*\s*\)",
        re.S,
    )
    if not constructor_pattern.search(_strip_comments_preserve_literals(source_text)):
        return {}

    dispatch_matches = list(
        re.finditer(
            rf"\border\s*==\s*{re.escape(order_type)}\.([A-Za-z_$][\w$]*)",
            clean_body,
        )
    )
    if len(dispatch_matches) < 11:
        return {}
    categories: dict[str, bool] = {}
    exception_type = ""
    for index, match in enumerate(dispatch_matches):
        end = (
            dispatch_matches[index + 1].start()
            if index + 1 < len(dispatch_matches)
            else len(clean_body)
        )
        segment = clean_body[match.end():end]
        throw_match = re.search(
            r"throw\s+new\s+([A-Za-z_$][\w$]*)\s*\(\s*(true|false)\s*\)",
            segment,
        )
        if not throw_match:
            return {}
        current_exception = throw_match.group(1)
        if exception_type and current_exception != exception_type:
            return {}
        exception_type = current_exception
        categories[match.group(1)] = throw_match.group(2) == "true"
    remaining = [constant for constant in constants if constant not in categories]
    if len(remaining) != 1:
        return {}
    tail = clean_body[dispatch_matches[-1].end():]
    tail_throws = re.findall(
        rf"throw\s+new\s+{re.escape(exception_type)}\s*\(\s*(true|false)\s*\)",
        tail,
    )
    if not tail_throws:
        return {}
    categories[remaining[0]] = tail_throws[-1] == "true"
    true_constants = [name for name in constants if categories.get(name) is True]
    false_constants = [name for name in constants if categories.get(name) is False]
    if len(true_constants) < 2 or len(false_constants) < 2:
        return {}
    exception_fqn = str(
        imports.get(exception_type) or f"{package_name}.{exception_type}"
    )
    exception_file = source_root / Path(*exception_fqn.split(".")).with_suffix(
        ".java"
    )
    try:
        exception_source = _strip_comments_preserve_literals(
            exception_file.read_text(encoding="utf-8", errors="ignore")
        )
    except OSError:
        return {}
    if not re.search(
        rf"\bpublic\s+class\s+{re.escape(exception_type)}\b", exception_source
    ):
        return {}
    return {
        "owner_fqn": f"{package_name}.{class_name}",
        "target_method": method_name,
        "order_fqn": order_fqn,
        "exception_fqn": exception_fqn,
        "positive_half_pi_constants": true_constants,
        "zero_pi_constants": false_constants,
        "target_descriptor": target_descriptor,
        "proof_status": "source_verified_order_singularity_tree",
    }


def _deterministic_order_singularity_matrix_source(
    *,
    candidate_code: str,
    replay_spec: dict[str, Any],
) -> dict[str, Any]:
    """Build one test matrix for a source-proven order singularity tree."""
    code = str(candidate_code or "")
    class_match = re.search(
        r"\b(?:public\s+)?(?:final\s+)?class\s+[A-Za-z_$][\w$]*[^\{]*\{",
        code,
    )
    required = ("owner_fqn", "target_method", "order_fqn", "exception_fqn")
    positive = list(replay_spec.get("positive_half_pi_constants") or [])
    zero_pi = list(replay_spec.get("zero_pi_constants") or [])
    if (
        not class_match
        or not all(str(replay_spec.get(key) or "") for key in required)
        or not positive
        or not zero_pi
    ):
        return {}
    class_open = code.find("{", class_match.start())
    if class_open < 0:
        return {}
    scaffold = code[: class_open + 1].rstrip() + "\n}\n"
    owner = str(replay_spec["owner_fqn"])
    target = str(replay_spec["target_method"])
    order = str(replay_spec["order_fqn"])
    exception = str(replay_spec["exception_fqn"])
    junit5 = "org.junit.jupiter" in code
    annotation = "@org.junit.jupiter.api.Test" if junit5 else "@org.junit.Test"
    assertions = "org.junit.jupiter.api.Assertions" if junit5 else "org.junit.Assert"
    name = "testDeterministicOrderSingularityMatrix"
    lines = [
        annotation,
        f"public void {name}() throws Exception {{",
        f"    {order}[] positiveHalfPiOrders = new {order}[] {{",
        "        " + ", ".join(f"{order}.{value}" for value in positive),
        "    };",
        "    double[] halfPiBounds = new double[] { Math.PI / 2.0, -Math.PI / 2.0 };",
        f"    for ({order} currentOrder : positiveHalfPiOrders) {{",
        "        for (double middle : halfPiBounds) {",
        "            try {",
        f"                new {owner}(currentOrder, 0.1, middle, 0.2).{target}(currentOrder);",
        f'                {assertions}.fail("expected singularity for " + currentOrder + " at " + middle);',
        f"            }} catch ({exception} expected) {{",
        "                // The target source declares this exceptional boundary.",
        "            }",
        "        }",
        "    }",
        f"    {order}[] zeroPiOrders = new {order}[] {{",
        "        " + ", ".join(f"{order}.{value}" for value in zero_pi),
        "    };",
        "    double[] zeroPiBounds = new double[] { 0.0, Math.PI };",
        f"    for ({order} currentOrder : zeroPiOrders) {{",
        "        for (double middle : zeroPiBounds) {",
        "            try {",
        f"                new {owner}(currentOrder, 0.1, middle, 0.2).{target}(currentOrder);",
        f'                {assertions}.fail("expected singularity for " + currentOrder + " at " + middle);',
        f"            }} catch ({exception} expected) {{",
        "                // The target source declares this exceptional boundary.",
        "            }",
        "        }",
        "    }",
    ]
    lines.append("}")
    source = _insert_test_method_into_candidate_class(scaffold, "\n".join(lines))
    if not source:
        return {}
    return {
        "row_id": "order_singularity_boundary_matrix",
        "source": source,
        "test_method_name": name,
        "proof_status": "source_proven_unvalidated_order_singularity_matrix",
    }


def _source_verified_class_mapping_replay_spec(
    *,
    source_text: str,
    class_name: str,
    method_name: str,
    target_descriptor: str = "",
) -> dict[str, Any]:
    """Prove a finite Class-literal mapping chain with identity fallback."""
    signature, body = _source_backed_exact_target_method_source(
        source_text=source_text,
        class_name=class_name,
        method_name=method_name,
        target_descriptor=target_descriptor,
    )
    clean_body = _strip_comments_preserve_literals(body)
    if not signature or not clean_body:
        return {}
    if not re.search(r"\bpublic\s+static\b", signature):
        return {}
    if not re.search(r"\bClass\s*<[^>]+>\s+" + re.escape(method_name) + r"\s*\(", signature):
        return {}
    parameter_match = re.search(
        r"\(\s*(?:final\s+)?Class\s*<[^>]+>\s+([A-Za-z_$][\w$]*)\s*\)",
        signature,
    )
    if not parameter_match:
        return {}
    parameter = parameter_match.group(1)
    literal = r"(?:boolean|byte|short|int|long|char|float|double|void|[A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*)"
    mapping_pattern = re.compile(
        rf"if\s*\(\s*{re.escape(parameter)}\s*==\s*({literal})\.class\s*\)\s*"
        rf"return\s+(?:\(\s*Class\s*<[^>]+>\s*\)\s*)?({literal})\.class\s*;"
    )
    mappings = [
        {"input": match.group(1), "expected": match.group(2)}
        for match in mapping_pattern.finditer(clean_body)
    ]
    if len(mappings) < 4:
        return {}
    if len(re.findall(r"\bif\s*\(", clean_body)) != len(mappings):
        return {}
    if len({row["input"] for row in mappings}) != len(mappings):
        return {}
    if not re.search(rf"return\s+{re.escape(parameter)}\s*;\s*\}}?\s*$", clean_body):
        return {}
    package_match = re.search(
        r"(?m)^\s*package\s+([A-Za-z_$][\w$.]*)\s*;", source_text
    )
    package_name = str(package_match.group(1) if package_match else "")
    if not package_name or not re.search(
        rf"\bpublic\s+(?:final\s+)?class\s+{re.escape(class_name)}\b",
        _strip_comments_preserve_literals(source_text),
    ):
        return {}
    return {
        "owner_fqn": f"{package_name}.{class_name}",
        "target_method": method_name,
        "mappings": mappings,
        "identity_input": "String",
        "target_descriptor": target_descriptor,
        "proof_status": "source_verified_class_literal_mapping_chain",
    }


def _deterministic_class_mapping_matrix_source(
    *,
    candidate_code: str,
    replay_spec: dict[str, Any],
) -> dict[str, Any]:
    """Build one self-contained test for a source-proven Class mapping chain."""
    code = str(candidate_code or "")
    class_match = re.search(
        r"\b(?:public\s+)?(?:final\s+)?class\s+[A-Za-z_$][\w$]*[^\{]*\{",
        code,
    )
    mappings = list(replay_spec.get("mappings") or [])
    owner = str(replay_spec.get("owner_fqn") or "")
    target = str(replay_spec.get("target_method") or "")
    identity_input = str(replay_spec.get("identity_input") or "")
    if not class_match or not owner or not target or not identity_input or not mappings:
        return {}
    class_open = code.find("{", class_match.start())
    if class_open < 0:
        return {}
    scaffold = code[: class_open + 1].rstrip() + "\n}\n"
    junit5 = "org.junit.jupiter" in code
    annotation = "@org.junit.jupiter.api.Test" if junit5 else "@org.junit.Test"
    assertions = "org.junit.jupiter.api.Assertions" if junit5 else "org.junit.Assert"
    name = "testDeterministicClassMappingMatrix"
    inputs = [f'{row["input"]}.class' for row in mappings] + [f"{identity_input}.class"]
    expected = [f'{row["expected"]}.class' for row in mappings] + [f"{identity_input}.class"]
    method = "\n".join([
        annotation,
        f"public void {name}() {{",
        "    Class<?>[] inputs = new Class<?>[] { " + ", ".join(inputs) + " };",
        "    Class<?>[] expected = new Class<?>[] { " + ", ".join(expected) + " };",
        "    for (int i = 0; i < inputs.length; i++) {",
        f"        {assertions}.assertSame(expected[i], {owner}.{target}(inputs[i]));",
        "    }",
        "}",
    ])
    source = _insert_test_method_into_candidate_class(scaffold, method)
    if not source:
        return {}
    return {
        "row_id": "class_literal_mapping_matrix",
        "source": source,
        "test_method_name": name,
        "proof_status": "source_proven_unvalidated_class_mapping_matrix",
    }


def _source_verified_string_collision_search_replay_spec(
    *,
    source_text: str,
    class_name: str,
    method_name: str,
    target_descriptor: str = "",
) -> dict[str, Any]:
    """Prove a public string entry into a two-key collision-bucket search."""
    signature, body = _source_backed_exact_target_method_source(
        source_text=source_text,
        class_name=class_name,
        method_name=method_name,
        target_descriptor=target_descriptor,
    )
    if not signature or not body or not re.search(r"\bprivate\b", signature):
        return {}
    params = _java_signature_parameter_types(signature, method_name)
    normalized = [re.sub(r"\s+", "", value).rsplit(".", 1)[-1] for value in params]
    if normalized != ["int", "String", "String[]", "int"]:
        return {}
    clean_body = _strip_comments_preserve_literals(body)
    required_patterns = (
        r"\.hashCode\s*\(\s*\)\s*>\s*[A-Za-z_$][\w$]*",
        r"\.hashCode\s*\(\s*\)\s*<\s*[A-Za-z_$][\w$]*",
        r"\.compareTo\s*\(",
        r"while\s*\(\s*--[A-Za-z_$][\w$]*",
        r"while\s*\(\s*\+\+[A-Za-z_$][\w$]*",
    )
    if not all(re.search(pattern, clean_body) for pattern in required_patterns):
        return {}
    clean_source = _strip_comments_preserve_literals(source_text)
    constructor_match = re.search(
        rf"\bpublic\s+{re.escape(class_name)}\s*\(\s*(?:\)|int\s+[A-Za-z_$][\w$]*\s*\))",
        clean_source,
    )
    if not constructor_match:
        return {}
    entry_pattern = re.compile(
        rf"\bpublic\s+(?:final\s+)?String\s+([A-Za-z_$][\w$]*)\s*"
        r"\(\s*(?:final\s+)?String\s+([A-Za-z_$][\w$]*)\s*\)\s*\{",
    )
    entry_name = ""
    for match in entry_pattern.finditer(clean_source):
        entry_open = clean_source.find("{", match.start())
        entry_close = _find_matching_brace(clean_source, entry_open)
        if entry_close < 0:
            continue
        entry_body = clean_source[entry_open : entry_close + 1]
        if re.search(rf"\b{re.escape(method_name)}\s*\(", entry_body):
            entry_name = match.group(1)
            break
    if not entry_name:
        return {}
    package_match = re.search(
        r"(?m)^\s*package\s+([A-Za-z_$][\w$.]*)\s*;", source_text
    )
    package_name = str(package_match.group(1) if package_match else "")
    if not package_name:
        return {}
    return {
        "owner_fqn": f"{package_name}.{class_name}",
        "entry_method": entry_name,
        "target_method": method_name,
        "target_descriptor": target_descriptor,
        "proof_status": "source_verified_string_collision_bucket_search",
    }


def _deterministic_string_collision_matrix_source(
    *,
    candidate_code: str,
    replay_spec: dict[str, Any],
) -> dict[str, Any]:
    """Build an insertion/lookup matrix for a proven collision-bucket search."""
    code = str(candidate_code or "")
    class_match = re.search(
        r"\b(?:public\s+)?(?:final\s+)?class\s+[A-Za-z_$][\w$]*[^\{]*\{",
        code,
    )
    owner = str(replay_spec.get("owner_fqn") or "")
    entry = str(replay_spec.get("entry_method") or "")
    if not class_match or not owner or not entry:
        return {}
    class_open = code.find("{", class_match.start())
    if class_open < 0:
        return {}
    scaffold = code[: class_open + 1].rstrip() + "\n}\n"
    junit5 = "org.junit.jupiter" in code
    annotation = "@org.junit.jupiter.api.Test" if junit5 else "@org.junit.Test"
    assertions = "org.junit.jupiter.api.Assertions" if junit5 else "org.junit.Assert"
    name = "testDeterministicStringCollisionSearchMatrix"
    method = "\n".join([
        annotation,
        f"public void {name}() {{",
        "    String[] collisions = new String[] {",
        '        "AaAaAa", "AaAaBB", "AaBBAa", "AaBBBB",',
        '        "BBAaAa", "BBAaBB", "BBBBAa", "BBBBBB"',
        "    };",
        "    int expectedHash = collisions[0].hashCode();",
        "    for (String value : collisions) {",
        f"        {assertions}.assertEquals(expectedHash, value.hashCode());",
        "    }",
        "    int[] order = new int[] { 4, 1, 6, 0, 7, 2, 5, 3 };",
        f"    {owner} mixed = new {owner}();",
        "    String[] canonical = new String[collisions.length];",
        "    for (int index : order) {",
        f"        canonical[index] = mixed.{entry}(new String(collisions[index]));",
        "    }",
        "    for (int i = collisions.length - 1; i >= 0; i--) {",
        f"        {assertions}.assertSame(canonical[i], mixed.{entry}(new String(collisions[i])));",
        "    }",
        f"    {owner} reverse = new {owner}();",
        "    for (int i = collisions.length - 1; i >= 0; i--) {",
        f"        reverse.{entry}(new String(collisions[i]));",
        "    }",
        "    for (String value : collisions) {",
        f"        {assertions}.assertEquals(value, reverse.{entry}(new String(value)));",
        "    }",
        "}",
    ])
    source = _insert_test_method_into_candidate_class(scaffold, method)
    if not source:
        return {}
    return {
        "row_id": "string_collision_search_matrix",
        "source": source,
        "test_method_name": name,
        "proof_status": "source_proven_unvalidated_string_collision_matrix",
    }


def _source_verified_runtime_type_dispatch_replay_spec(
    *,
    source_text: str,
    class_name: str,
    method_name: str,
    target_descriptor: str = "",
) -> dict[str, Any]:
    """Prove a public Object-to-Iterator dispatch over standard runtime types."""
    signature, body = _source_backed_exact_target_method_source(
        source_text=source_text,
        class_name=class_name,
        method_name=method_name,
        target_descriptor=target_descriptor,
    )
    if not signature or not body or not re.search(r"\bpublic\s+static\b", signature):
        return {}
    params = _java_signature_parameter_types(signature, method_name)
    if len(params) != 1 or params[0].rsplit(".", 1)[-1] != "Object":
        return {}
    if not re.search(r"\bIterator\s*<[^>]*>\s+" + re.escape(method_name), signature):
        return {}
    clean_body = _strip_comments_preserve_literals(body)
    required = (
        r"==\s*null",
        r"instanceof\s+(?:[A-Za-z_$][\w$]*\.)*Iterator\b",
        r"instanceof\s+(?:[A-Za-z_$][\w$]*\.)*Iterable\b",
        r"instanceof\s+Object\s*\[\s*\]",
        r"instanceof\s+(?:[A-Za-z_$][\w$]*\.)*Enumeration\b",
        r"instanceof\s+(?:[A-Za-z_$][\w$]*\.)*Map\b",
        r"instanceof\s+(?:[A-Za-z_$][\w$]*\.)*NodeList\b",
        r"instanceof\s+(?:[A-Za-z_$][\w$]*\.)*Node\b",
        r"instanceof\s+(?:[A-Za-z_$][\w$]*\.)*Dictionary\b",
        r"\.getClass\s*\(\s*\)\s*\.isArray\s*\(",
        r"\.getMethod\s*\(\s*\"iterator\"",
        r"singletonIterator\s*\(",
    )
    if not all(re.search(pattern, clean_body) for pattern in required):
        return {}
    package_match = re.search(
        r"(?m)^\s*package\s+([A-Za-z_$][\w$.]*)\s*;", source_text
    )
    package_name = str(package_match.group(1) if package_match else "")
    if not package_name:
        return {}
    return {
        "owner_fqn": f"{package_name}.{class_name}",
        "target_method": method_name,
        "target_descriptor": target_descriptor,
        "proof_status": "source_verified_standard_runtime_type_dispatch",
    }


def _deterministic_runtime_type_dispatch_matrix_source(
    *,
    candidate_code: str,
    replay_spec: dict[str, Any],
) -> dict[str, Any]:
    """Build one standard-library input matrix for a proven type dispatch."""
    code = str(candidate_code or "")
    class_match = re.search(
        r"\b(?:public\s+)?(?:final\s+)?class\s+[A-Za-z_$][\w$]*[^\{]*\{",
        code,
    )
    owner = str(replay_spec.get("owner_fqn") or "")
    target = str(replay_spec.get("target_method") or "")
    if not class_match or not owner or not target:
        return {}
    class_open = code.find("{", class_match.start())
    if class_open < 0:
        return {}
    scaffold = code[: class_open + 1].rstrip() + "\n}\n"
    junit5 = "org.junit.jupiter" in code
    annotation = "@org.junit.jupiter.api.Test" if junit5 else "@org.junit.Test"
    assertions = "org.junit.jupiter.api.Assertions" if junit5 else "org.junit.Assert"
    name = "testDeterministicRuntimeTypeDispatchMatrix"
    call = f"{owner}.{target}"
    method = "\n".join([
        annotation,
        f"public void {name}() throws Exception {{",
        f"    {assertions}.assertFalse({call}(null).hasNext());",
        '    java.util.Iterator<String> existing = java.util.Collections.singletonList("iterator").iterator();',
        f"    {assertions}.assertSame(existing, {call}(existing));",
        f'    {assertions}.assertEquals("iterable", {call}(java.util.Collections.singletonList("iterable")).next());',
        f'    {assertions}.assertEquals("array", {call}(new Object[] {{ "array" }}).next());',
        "    java.util.Vector<String> vector = new java.util.Vector<String>();",
        '    vector.add("enumeration");',
        f'    {assertions}.assertEquals("enumeration", {call}(vector.elements()).next());',
        "    java.util.Map<String, String> map = new java.util.HashMap<String, String>();",
        '    map.put("key", "map");',
        f'    {assertions}.assertEquals("map", {call}(map).next());',
        "    org.w3c.dom.Document document = javax.xml.parsers.DocumentBuilderFactory.newInstance().newDocumentBuilder().newDocument();",
        '    document.appendChild(document.createElement("root"));',
        '    document.getDocumentElement().appendChild(document.createElement("child"));',
        f'    {assertions}.assertEquals("root", ((org.w3c.dom.Node) {call}(document.getChildNodes()).next()).getNodeName());',
        f'    {assertions}.assertEquals("child", ((org.w3c.dom.Node) {call}(document.getDocumentElement()).next()).getNodeName());',
        "    java.util.Dictionary<String, String> dictionary = new java.util.Dictionary<String, String>() {",
        "        public int size() { return 1; }",
        "        public boolean isEmpty() { return false; }",
        '        public java.util.Enumeration<String> keys() { return java.util.Collections.enumeration(java.util.Collections.singleton("k")); }',
        '        public java.util.Enumeration<String> elements() { return java.util.Collections.enumeration(java.util.Collections.singleton("dictionary")); }',
        '        public String get(Object key) { return "dictionary"; }',
        "        public String put(String key, String value) { return null; }",
        "        public String remove(Object key) { return null; }",
        "    };",
        f'    {assertions}.assertEquals("dictionary", {call}(dictionary).next());',
        f"    {assertions}.assertEquals(7, {call}(new int[] {{ 7, 8 }}).next());",
        "    Object singleton = new Object();",
        f"    {assertions}.assertSame(singleton, {call}(singleton).next());",
        "}",
    ])
    source = _insert_test_method_into_candidate_class(scaffold, method)
    if not source:
        return {}
    return {
        "row_id": "runtime_type_dispatch_matrix",
        "source": source,
        "test_method_name": name,
        "proof_status": "source_proven_unvalidated_runtime_type_matrix",
    }


def _source_verified_formatted_walker_replay_spec(
    *,
    source_text: str,
    source_file: Path,
    class_name: str,
    method_name: str,
    target_descriptor: str = "",
) -> dict[str, Any]:
    """Resolve a concrete walker plus content/format fixtures from source."""
    signature, body = _source_backed_exact_target_method_source(
        source_text=source_text,
        class_name=class_name,
        method_name=method_name,
        target_descriptor=target_descriptor,
    )
    if not signature or not body or not re.search(r"\bpublic\s+final\b", signature):
        return {}
    if _java_signature_parameter_types(signature, method_name):
        return {}
    clean_body = _strip_comments_preserve_literals(body)
    required = (
        r"NoSuchElementException",
        r"\bmultitext\s*!=\s*null",
        r"\bpendingmt\s*!=\s*null",
        r"\bisTextLike\s*\(",
        r"\bbuildMultiText\s*\(",
    )
    if not all(re.search(pattern, clean_body) for pattern in required):
        return {}
    clean_source = _strip_comments_preserve_literals(source_text)
    if not re.search(
        rf"\bpublic\s+{re.escape(class_name)}\s*\([^)]*\bList\s*<\s*\?\s+extends\s+Content\s*>[^)]*\bFormatStack\b[^)]*\bboolean\b[^)]*\)",
        clean_source,
        re.S,
    ):
        return {}
    package_match = re.search(
        r"(?m)^\s*package\s+([A-Za-z_$][\w$.]*)\s*;", source_text
    )
    package_name = str(package_match.group(1) if package_match else "")
    if not package_name:
        return {}
    imports = {
        fqn.rsplit(".", 1)[-1]: fqn
        for fqn in re.findall(
            r"(?m)^\s*import\s+([A-Za-z_$][\w$.]*)\s*;", source_text
        )
    }
    content_fqn = str(imports.get("Content") or f"{package_name}.Content")
    format_fqn = str(imports.get("Format") or f"{package_name}.Format")
    format_stack_fqn = str(imports.get("FormatStack") or f"{package_name}.FormatStack")

    source_root = source_file.parent
    for part in reversed(package_name.split(".")):
        if source_root.name != part:
            return {}
        source_root = source_root.parent

    def _source_for_fqn(fqn: str) -> tuple[Path, str]:
        path = source_root / Path(*fqn.split(".")).with_suffix(".java")
        try:
            return path, _strip_comments_preserve_literals(
                path.read_text(encoding="utf-8", errors="ignore")
            )
        except OSError:
            return path, ""

    _stack_path, stack_source = _source_for_fqn(format_stack_fqn)
    _format_path, format_source = _source_for_fqn(format_fqn)
    content_path, _content_source = _source_for_fqn(content_fqn)
    if not stack_source or not format_source or not content_path.exists():
        return {}
    if not re.search(
        rf"\bpublic\s+{re.escape(format_stack_fqn.rsplit('.', 1)[-1])}\s*\(\s*{re.escape(format_fqn.rsplit('.', 1)[-1])}\s+[A-Za-z_$][\w$]*\s*\)",
        stack_source,
    ):
        return {}

    factories: list[tuple[str, bool]] = []
    for match in re.finditer(
        rf"\bpublic\s+static\s+{re.escape(format_fqn.rsplit('.', 1)[-1])}\s+([A-Za-z_$][\w$]*)\s*\(\s*\)\s*\{{",
        format_source,
    ):
        open_brace = format_source.find("{", match.start())
        close_brace = _find_matching_brace(format_source, open_brace)
        if close_brace >= 0:
            factory_body = format_source[open_brace : close_brace + 1]
            factories.append((match.group(1), ".setIndent(" in factory_body))
    padded = next((name for name, has_indent in factories if has_indent), "")
    plain = next((name for name, has_indent in factories if not has_indent), "")
    if not padded or not plain:
        return {}

    getter_match = re.search(r"\.([A-Za-z_$][\w$]*)\s*\(\s*\)", clean_body)
    getter_name = next(
        (
            name
            for name in re.findall(r"\.([A-Za-z_$][\w$]*)\s*\(\s*\)", clean_body)
            if re.search(
                rf"\bpublic\s+boolean\s+{re.escape(name)}\s*\(\s*\)",
                stack_source,
            )
        ),
        "",
    )
    if not getter_match or not getter_name:
        return {}
    getter_signature, getter_body = _source_backed_exact_target_method_source(
        source_text=stack_source,
        class_name=format_stack_fqn.rsplit(".", 1)[-1],
        method_name=getter_name,
    )
    field_match = re.search(r"return\s+([A-Za-z_$][\w$]*)\s*\[", getter_body)
    if not getter_signature or not field_match:
        return {}
    state_field = field_match.group(1)
    setter_name = ""
    for match in re.finditer(
        r"\bpublic\s+void\s+([A-Za-z_$][\w$]*)\s*\(\s*boolean\s+([A-Za-z_$][\w$]*)\s*\)\s*\{",
        stack_source,
    ):
        open_brace = stack_source.find("{", match.start())
        close_brace = _find_matching_brace(stack_source, open_brace)
        setter_body = stack_source[open_brace : close_brace + 1]
        if re.search(rf"\b{re.escape(state_field)}\s*\[", setter_body):
            setter_name = match.group(1)
            break
    if not setter_name:
        return {}

    concrete_candidates: list[tuple[int, str]] = []
    for sibling in source_file.parent.glob("*.java"):
        try:
            sibling_source = _strip_comments_preserve_literals(
                sibling.read_text(encoding="utf-8", errors="ignore")
            )
        except OSError:
            continue
        class_match = re.search(
            rf"\bpublic\s+class\s+([A-Za-z_$][\w$]*)\s+extends\s+{re.escape(class_name)}\b",
            sibling_source,
        )
        if not class_match:
            continue
        concrete = class_match.group(1)
        if not re.search(
            rf"\bpublic\s+{re.escape(concrete)}\s*\([^)]*\bList\s*<\s*\?\s+extends\s+Content\s*>[^)]*\bFormatStack\b[^)]*\bboolean\b[^)]*\)",
            sibling_source,
            re.S,
        ):
            continue
        if not all(token in sibling_source for token in ("appendText", "appendCDATA", "appendRaw")):
            continue
        concrete_candidates.append((len(sibling_source), f"{package_name}.{concrete}"))
    if not concrete_candidates:
        return {}
    concrete_fqn = min(concrete_candidates)[1]

    _helper_sig, helper_body = _source_backed_exact_target_method_source(
        source_text=source_text,
        class_name=class_name,
        method_name="isTextLike",
    )
    text_labels = set(re.findall(r"\bcase\s+([A-Za-z_$][\w$]*)\s*:", helper_body))
    if len(text_labels) < 2:
        return {}
    fixture_dir = content_path.parent
    declarations: dict[str, tuple[str, str]] = {}
    for fixture_file in fixture_dir.glob("*.java"):
        try:
            fixture_source = _strip_comments_preserve_literals(
                fixture_file.read_text(encoding="utf-8", errors="ignore")
            )
        except OSError:
            continue
        declaration = re.search(
            r"\bpublic\s+(?:abstract\s+)?class\s+([A-Za-z_$][\w$]*)\s+extends\s+([A-Za-z_$][\w$]*)",
            fixture_source,
        )
        if not declaration:
            continue
        fixture_name, parent_name = declaration.groups()
        if not re.search(
            rf"\bpublic\s+{re.escape(fixture_name)}\s*\(\s*(?:final\s+)?String\s+[A-Za-z_$][\w$]*\s*\)",
            fixture_source,
        ):
            continue
        ctype_match = re.search(r"(?:super|this)\s*\(\s*CType\.([A-Za-z_$][\w$]*)", fixture_source)
        if ctype_match:
            declarations[fixture_name] = (parent_name, ctype_match.group(1))

    def _is_content_subclass(name: str) -> bool:
        seen: set[str] = set()
        current = name
        content_simple = content_fqn.rsplit(".", 1)[-1]
        while current in declarations and current not in seen:
            seen.add(current)
            parent = declarations[current][0]
            if parent == content_simple:
                return True
            current = parent
        return False

    text_fixtures = [
        f"{content_fqn.rsplit('.', 1)[0]}.{name}"
        for name, (_parent, label) in sorted(declarations.items())
        if label in text_labels and _is_content_subclass(name)
    ]
    nontext_fixtures = [
        f"{content_fqn.rsplit('.', 1)[0]}.{name}"
        for name, (_parent, label) in sorted(declarations.items())
        if label not in text_labels and _is_content_subclass(name)
    ]
    if len(text_fixtures) < 2 or not nontext_fixtures:
        return {}
    return {
        "owner_fqn": f"{package_name}.{class_name}",
        "concrete_walker_fqn": concrete_fqn,
        "content_fqn": content_fqn,
        "format_fqn": format_fqn,
        "format_stack_fqn": format_stack_fqn,
        "plain_format_factory": plain,
        "padded_format_factory": padded,
        "escape_setter": setter_name,
        "text_fixture_fqns": text_fixtures[:3],
        "nontext_fixture_fqn": nontext_fixtures[0],
        "target_descriptor": target_descriptor,
        "proof_status": "source_verified_formatted_walker_state_machine",
    }


def _deterministic_formatted_walker_matrix_source(
    *,
    candidate_code: str,
    replay_spec: dict[str, Any],
) -> dict[str, Any]:
    """Build one self-contained consumer sequence for a proven walker."""
    code = str(candidate_code or "")
    class_match = re.search(
        r"\b(?:public\s+)?(?:final\s+)?class\s+[A-Za-z_$][\w$]*[^\{]*\{",
        code,
    )
    required = (
        "concrete_walker_fqn", "content_fqn", "format_fqn",
        "format_stack_fqn", "plain_format_factory", "padded_format_factory",
        "escape_setter", "nontext_fixture_fqn",
    )
    text_types = list(replay_spec.get("text_fixture_fqns") or [])
    if not class_match or not all(str(replay_spec.get(key) or "") for key in required) or len(text_types) < 2:
        return {}
    class_open = code.find("{", class_match.start())
    if class_open < 0:
        return {}
    scaffold = code[: class_open + 1].rstrip() + "\n}\n"
    junit5 = "org.junit.jupiter" in code
    annotation = "@org.junit.jupiter.api.Test" if junit5 else "@org.junit.Test"
    assertions = "org.junit.jupiter.api.Assertions" if junit5 else "org.junit.Assert"
    walker = str(replay_spec["concrete_walker_fqn"])
    content = str(replay_spec["content_fqn"])
    format_type = str(replay_spec["format_fqn"])
    stack_type = str(replay_spec["format_stack_fqn"])
    plain = str(replay_spec["plain_format_factory"])
    padded = str(replay_spec["padded_format_factory"])
    setter = str(replay_spec["escape_setter"])
    nontext = str(replay_spec["nontext_fixture_fqn"])
    text_a, text_b = text_types[:2]
    text_c = text_types[2] if len(text_types) > 2 else text_b
    name = "testDeterministicFormattedWalkerStateMatrix"
    method = "\n".join([
        annotation,
        f"public void {name}() {{",
        f"    {stack_type} plainStack = new {stack_type}({format_type}.{plain}());",
        f"    {walker} empty = new {walker}(java.util.Collections.<{content}>emptyList(), plainStack, true);",
        f"    {assertions}.assertFalse(empty.hasNext());",
        f"    {assertions}.assertThrows(java.util.NoSuchElementException.class, empty::next);",
        f'    {content} one = new {nontext}("one");',
        f"    {walker} single = new {walker}(java.util.Collections.<{content}>singletonList(one), plainStack, true);",
        f"    {assertions}.assertSame(one, single.next());",
        f"    {assertions}.assertFalse(single.hasNext());",
        f"    {stack_type} paddedStack = new {stack_type}({format_type}.{padded}());",
        f'    {content} first = new {nontext}("first");',
        f'    {content} second = new {nontext}("second");',
        f"    {walker} separated = new {walker}(java.util.Arrays.<{content}>asList(first, second), paddedStack, true);",
        f"    {assertions}.assertSame(first, separated.next());",
        f"    {assertions}.assertNull(separated.next());",
        f"    {assertions}.assertNotNull(separated.text());",
        f"    {assertions}.assertSame(second, separated.next());",
        f'    {content} before = new {nontext}("before");',
        f'    {content} after = new {nontext}("after");',
        f"    {walker} mixed = new {walker}(java.util.Arrays.<{content}>asList(before, new {text_a}(\" alpha \"), new {text_b}(\"beta\"), new {text_c}(\"amp\"), after), paddedStack, true);",
        f"    {assertions}.assertSame(before, mixed.next());",
        f"    paddedStack.{setter}(false);",
        "    while (mixed.hasNext()) { mixed.next(); mixed.text(); mixed.isCDATA(); }",
        f"    {walker} textOnly = new {walker}(java.util.Arrays.<{content}>asList(new {text_a}(\"x\"), new {text_b}(\"y\"), new {text_c}(\"amp\")), plainStack, false);",
        "    while (textOnly.hasNext()) { textOnly.next(); textOnly.text(); textOnly.isCDATA(); }",
        "}",
    ])
    source = _insert_test_method_into_candidate_class(scaffold, method)
    if not source:
        return {}
    return {
        "row_id": "formatted_walker_state_matrix",
        "source": source,
        "test_method_name": name,
        "proof_status": "source_proven_unvalidated_formatted_walker_matrix",
    }


def _source_verified_pattern_alphabet_replay_spec(
    *,
    source_text: str,
    class_name: str,
    method_name: str,
    target_descriptor: str = "",
) -> dict[str, Any]:
    """Resolve a finite pattern-letter parser and its public entry path.

    This gate deliberately requires the complete source shape: an exact static
    ``void(builder, String)`` target, token-first-character dispatch, and a
    bounded source-visible call chain from a public static String entry.  A
    switch that merely happens to use character constants is not sufficient.
    """

    signature, body = _source_backed_exact_target_method_source(
        source_text=source_text,
        class_name=class_name,
        method_name=method_name,
        target_descriptor=target_descriptor,
    )
    if not signature or not body or not re.search(r"\bstatic\b", signature):
        return {}
    bindings = _method_parameter_bindings(f"{signature} {{{body}}}", target_descriptor)
    if len(bindings) != 2:
        return {}
    parameter_types = [re.sub(r"\s+", "", value[0]) for value in bindings]
    if parameter_types[-1] not in {"String", "java.lang.String"}:
        return {}
    signature_head = signature.split(method_name, 1)[0].strip()
    if not re.search(r"\bvoid\s*$", signature_head):
        return {}
    clean_body = _strip_comments_preserve_literals(body)
    if not (
        re.search(r"\b(?:parse|next)[A-Za-z_$][\w$]*\s*\(", clean_body)
        and re.search(r"\.charAt\s*\(\s*0\s*\)", clean_body)
        and re.search(r"\bswitch\s*\(", clean_body)
    ):
        return {}
    raw_case_chars = _unique_preserve_order(
        re.findall(r"\bcase\s+'((?:\\.|[^'\\]))'\s*:", clean_body)
    )
    case_chars = [
        "'" if value == r"\'" else "\\" if value == r"\\" else value
        for value in raw_case_chars
    ]
    if len(case_chars) < 8:
        return {}

    try:
        from tatg.engines.tatg_adapter import TATGEngineAdapter

        blocks = TATGEngineAdapter()._collect_method_blocks(source_text)
    except Exception:
        blocks = []
    method_bodies: dict[str, list[str]] = {}
    public_entries: list[tuple[str, str]] = []
    for block in blocks:
        name = str(block.get("name") or "")
        block_signature = str(block.get("signature") or "")
        block_body = _strip_comments_preserve_literals(str(block.get("body") or ""))
        if not name or not block_body:
            continue
        method_bodies.setdefault(name, []).append(block_body)
        params = _java_signature_parameter_types(block_signature, name)
        prefix = block_signature.split(name, 1)[0]
        if (
            name != method_name
            and re.search(r"\bpublic\b", block_signature)
            and re.search(r"\bstatic\b", block_signature)
            and params == ["String"]
            and not re.search(r"\bvoid\s*$", prefix.strip())
        ):
            public_entries.append((name, prefix.strip().split()[-1]))

    def reaches_target(entry: str) -> bool:
        frontier = [(entry, 0)]
        seen: set[str] = set()
        while frontier:
            current, depth = frontier.pop(0)
            if current in seen or depth > 3:
                continue
            seen.add(current)
            for current_body in method_bodies.get(current, []):
                if re.search(rf"\b{re.escape(method_name)}\s*\(", current_body):
                    return True
                for called in re.findall(r"\b([A-Za-z_$][\w$]*)\s*\(", current_body):
                    if called in method_bodies and called not in seen:
                        frontier.append((called, depth + 1))
        return False

    entry = next(((name, result) for name, result in public_entries if reaches_target(name)), None)
    if entry is None:
        return {}

    token_length_name = ""
    token_length_matches = list(re.finditer(
        r"\bint\s+([A-Za-z_$][\w$]*)\s*=\s*[A-Za-z_$][\w$]*\.length\s*\(\s*\)\s*;",
        clean_body,
    ))
    token_length_name = next(
        (
            match.group(1)
            for match in token_length_matches
            if re.search(
                rf"\b{re.escape(match.group(1))}\s*(?:==|>=|<=|>|<)\s*\d+\b",
                clean_body,
            )
        ),
        "",
    )
    rows: list[dict[str, Any]] = []

    def add(row_id: str, pattern: str, evidence: str) -> None:
        if any(row["pattern"] == pattern for row in rows):
            return
        rows.append({"row_id": row_id, "pattern": pattern, "source_evidence": evidence})

    def case_block_for(char: str) -> str:
        encoded = r"\'" if char == "'" else r"\\" if char == "\\" else char
        start = clean_body.find(f"case '{encoded}':")
        if start < 0:
            return ""
        cursor = start
        while True:
            colon = clean_body.find(":", cursor)
            next_case = clean_body.find("case '", colon + 1)
            default = clean_body.find("default:", colon + 1)
            boundary_candidates = [value for value in (next_case, default) if value >= 0]
            boundary = min(boundary_candidates) if boundary_candidates else len(clean_body)
            if next_case == boundary and not clean_body[colon + 1:next_case].strip():
                cursor = next_case
                continue
            return clean_body[start:boundary]

    for char in case_chars:
        if char == "'":
            add("literal_single", "'x'", "source switch contains quoted-literal case")
            add("literal_multi", "'xy'", "source literal branch distinguishes one and multiple characters")
            continue
        safe = re.sub(r"\W+", "_", char) or "char"
        add(f"case_{safe}_len1", char, f"source switch case '{char}'")
        case_block = case_block_for(char)
        if token_length_name and re.search(
            rf"\b{re.escape(token_length_name)}\s*(?:>=|==)\s*3\b", case_block
        ):
            add(f"case_{safe}_len3", char * 3, "source token-length branch at three")
        if token_length_name and re.search(
            rf"\b{re.escape(token_length_name)}\s*(?:>=|==)\s*4\b", case_block
        ):
            add(f"case_{safe}_len4", char * 4, "source token-length branch at four")
        if token_length_name and re.search(
            rf"\b{re.escape(token_length_name)}\s*==\s*2\b", case_block
        ):
            add(f"case_{safe}_len2", char * 2, "source token-length equality at two")
            add(f"case_{safe}_len3", char * 3, "source alternate token-length path")

    numeric_chars: list[str] = []
    numeric_body = next(
        (candidate for name, bodies in method_bodies.items() if "Numeric" in name for candidate in bodies),
        "",
    )
    if numeric_body:
        numeric_chars = [
            "'" if value == r"\'" else "\\" if value == r"\\" else value
            for value in _unique_preserve_order(
                re.findall(r"\bcase\s+'((?:\\.|[^'\\]))'\s*:", numeric_body)
            )
        ]
    if token_length_name and "isNumeric" in clean_body and numeric_chars:
        non_numeric = next((char for char in case_chars if char not in numeric_chars and char != "'"), "")
        numeric = next((char for char in numeric_chars if char in case_chars and char != "'"), "")
        if not numeric:
            return {}
        for char in case_chars:
            case_block = case_block_for(char)
            if "isNumeric" in case_block and re.search(
                rf"\b{re.escape(token_length_name)}\s*==\s*2\b", case_block
            ):
                add(f"case_{char}_len2_numeric_next", char * 2 + numeric, "source numeric lookahead path")
                if non_numeric:
                    add(f"case_{char}_len2_nonnumeric_next", char * 2 + non_numeric, "source non-numeric lookahead path")
                add(f"case_{char}_len3_numeric_next", char * 3 + numeric, "source long-token numeric lookahead path")

    invalid_char = next(
        (char for char in "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz" if char not in case_chars),
        "",
    )
    if not invalid_char or len(rows) < len(case_chars):
        return {}
    return {
        "owner": class_name,
        "entry_method": entry[0],
        "entry_return_type": entry[1],
        "rows": rows[:48],
        "invalid_pattern": invalid_char,
        "target_descriptor": target_descriptor,
        "proof_status": "source_verified_pattern_alphabet_dispatch",
    }


def _deterministic_pattern_alphabet_matrix_source(
    *, candidate_code: str, replay_spec: dict[str, Any]
) -> dict[str, Any]:
    """Build one bounded matrix test from a verified pattern alphabet."""

    code = str(candidate_code or "")
    class_match = re.search(r"\b(?:public\s+)?(?:final\s+)?class\s+[A-Za-z_$][\w$]*[^\{]*\{", code)
    owner = str(replay_spec.get("owner") or "")
    entry = str(replay_spec.get("entry_method") or "")
    rows = list(replay_spec.get("rows") or [])
    invalid = str(replay_spec.get("invalid_pattern") or "")
    if not class_match or not owner or not entry or len(rows) < 8 or not invalid:
        return {}
    class_open = code.find("{", class_match.start())
    if class_open < 0:
        return {}
    scaffold = code[: class_open + 1].rstrip() + "\n}\n"
    junit5 = "org.junit.jupiter" in code
    annotation = "@org.junit.jupiter.api.Test" if junit5 else "@org.junit.Test"
    assertions = "org.junit.jupiter.api.Assertions" if junit5 else "org.junit.Assert"
    name = "testDeterministicPatternAlphabetMatrix"
    pattern_values = ", ".join(json.dumps(str(row.get("pattern") or "")) for row in rows)
    lines = [
        annotation,
        f"public void {name}() throws Exception {{",
        f"    String[] patterns = new String[] {{{pattern_values}}};",
        "    for (String pattern : patterns) {",
        f"        {assertions}.assertNotNull({owner}.{entry}(pattern));",
        "    }",
        f"    try {{ {owner}.{entry}({json.dumps(invalid)}); {assertions}.fail(\"expected invalid pattern\"); }}",
        "    catch (IllegalArgumentException expected) { "
        f"{assertions}.assertNotNull(expected.getMessage()); }}",
        "}",
    ]
    source = _insert_test_method_into_candidate_class(scaffold, "\n".join(lines))
    if not source:
        return {}
    return {
        "row_id": "pattern_alphabet_matrix",
        "source": source,
        "test_method_name": name,
        "proof_status": "source_proven_unvalidated_pattern_alphabet_matrix",
    }


def _source_verified_windowed_string_dispatch_replay_spec(
    *,
    source_text: str,
    class_name: str,
    method_name: str,
    target_descriptor: str = "",
) -> dict[str, Any]:
    """Resolve a bounded local-window String dispatch algorithm from source."""

    signature, body = _source_backed_exact_target_method_source(
        source_text=source_text,
        class_name=class_name,
        method_name=method_name,
        target_descriptor=target_descriptor,
    )
    if not signature or not body or not re.search(r"\bpublic\b", signature):
        return {}
    bindings = _method_parameter_bindings(f"{signature} {{{body}}}", target_descriptor)
    if len(bindings) != 1 or re.sub(r"\s+", "", bindings[0][0]) not in {
        "String", "java.lang.String"
    }:
        return {}
    prefix = signature.split(method_name, 1)[0].strip()
    if not re.search(r"(?:java\.lang\.)?String\s*$", prefix):
        return {}
    clean = _strip_comments_preserve_literals(source_text)
    clean_body = _strip_comments_preserve_literals(body)
    if not (
        re.search(r"\b(?:while|for)\s*\(", clean_body)
        and re.search(r"\bswitch\s*\(", clean_body)
        and re.search(r"\.charAt\s*\(", clean_body)
        and re.search(r"\.toUpperCase\s*\(", clean_body)
    ):
        return {}
    called_names = _unique_preserve_order(re.findall(
        r"\b([A-Za-z_$][\w$]*)\s*\(", clean_body
    ))
    helper_signals = {
        keyword: any(keyword in name.lower() for name in called_names)
        for keyword in ("previous", "next", "last", "region", "vowel")
    }
    if sum(helper_signals.values()) < 4:
        return {}
    raw_chars = _unique_preserve_order(
        re.findall(r"\bcase\s+'((?:\\.|[^'\\]))'\s*:", clean_body)
    )
    alphabet = [
        "'" if value == r"\'" else "\\" if value == r"\\" else value
        for value in raw_chars
    ]
    alphabet = [char for char in alphabet if len(char) == 1 and char.isalpha()]
    if len(set(alphabet)) < 15:
        return {}
    motifs: list[str] = []
    for call in re.finditer(
        r"\b(?P<name>[A-Za-z_$][\w$]*)\s*\((?P<args>[^;\n()]*)\)",
        clean_body,
    ):
        if "region" not in call.group("name").lower():
            continue
        for value in re.findall(r'\"([A-Za-z]+)\"', call.group("args")):
            if value not in motifs:
                motifs.append(value)
    if len(motifs) < 3:
        return {}
    string_constants = {
        name: value
        for name, value in re.findall(
            r"\bstatic\s+final\s+String\s+([A-Za-z_$][\w$]*)\s*=\s*\"([A-Za-z]+)\"\s*;",
            clean,
        )
    }
    vowel_chars = next(
        (
            value for name, value in string_constants.items()
            if re.search(rf"\b{re.escape(name)}\.indexOf\s*\(", clean)
            and len(value) >= 3
            and all(char in "AEIOUaeiou" for char in value)
        ),
        "",
    )
    if not vowel_chars:
        return {}
    vowel = vowel_chars[0].upper()
    first_switch = clean_body.find("switch")
    first_switch_open = clean_body.find("{", first_switch)
    first_switch_close = (
        _find_matching_brace(clean_body, first_switch_open)
        if first_switch_open >= 0
        else -1
    )
    initial_case_chars = set(re.findall(
        r"\bcase\s+'([A-Za-z])'\s*:",
        clean_body[first_switch_open:first_switch_close + 1]
        if first_switch_close >= 0
        else "",
    ))
    consonant = next(
        (
            char for char in alphabet
            if char.upper() not in vowel_chars.upper()
            and char.upper() not in {value.upper() for value in initial_case_chars}
        ),
        "",
    )
    if not consonant:
        return {}
    context_chars: list[str] = []
    for name, value in string_constants.items():
        if re.search(rf"\b{re.escape(name)}\b", clean_body):
            for char in value.upper():
                if char in alphabet and char not in context_chars:
                    context_chars.append(char)
    for call in re.finditer(
        r"\b(?P<name>[A-Za-z_$][\w$]*)\s*\((?P<args>[^;\n()]*)\)",
        clean_body,
    ):
        if not any(key in call.group("name").lower() for key in ("previous", "next")):
            continue
        for char in re.findall(r"'([A-Za-z])'", call.group("args")):
            char = char.upper()
            if char in alphabet and char not in context_chars:
                context_chars.append(char)
    for char in (vowel, consonant):
        if char not in context_chars:
            context_chars.append(char)
    if len(context_chars) < 3:
        return {}
    initial_pairs: list[str] = []
    overlapping_pair_pattern = re.compile(
        r"(?=(case\s+'([A-Za-z])'\s*:[\s\S]{0,600}?"
        r"\b[A-Za-z_$][\w$]*\s*\[\s*1\s*\]\s*==\s*'([A-Za-z])'))"
    )
    for match in overlapping_pair_pattern.finditer(clean_body):
        pair = (match.group(2) + match.group(3)).upper()
        if pair not in initial_pairs:
            initial_pairs.append(pair)
    for condition in re.finditer(
        r"\b[A-Za-z_$][\w$]*\s*\[\s*1\s*\]\s*==\s*'([A-Za-z])'",
        clean_body,
    ):
        preceding = clean_body[max(0, condition.start() - 900):condition.start()]
        cases = re.findall(r"case\s+'([A-Za-z])'\s*:", preceding)
        if cases:
            pair = (cases[-1] + condition.group(1)).upper()
            if pair not in initial_pairs:
                initial_pairs.append(pair)
    has_constructor = bool(re.search(
        rf"\bpublic\s+{re.escape(class_name)}\s*\(\s*\)", clean
    ))
    setter_match = re.search(
        r"\bpublic\s+void\s+([A-Za-z_$][\w$]*)\s*\(\s*(?:final\s+)?int\s+[A-Za-z_$][\w$]*\s*\)",
        clean,
    )
    if not has_constructor or not setter_match:
        return {}
    return {
        "owner": class_name,
        "target_method": method_name,
        "alphabet": "".join(_unique_preserve_order(alphabet)),
        "motifs": motifs[:32],
        "initial_pairs": initial_pairs[:16],
        "vowel": vowel,
        "consonant": consonant,
        "context_chars": "".join(context_chars[:20]),
        "length_setter": setter_match.group(1),
        "target_descriptor": target_descriptor,
        "proof_status": "source_verified_windowed_string_dispatch",
    }


def _deterministic_windowed_string_matrix_source(
    *, candidate_code: str, replay_spec: dict[str, Any]
) -> dict[str, Any]:
    """Build one source-derived n-gram matrix for a local-window encoder."""

    code = str(candidate_code or "")
    class_match = re.search(r"\b(?:public\s+)?(?:final\s+)?class\s+[A-Za-z_$][\w$]*[^\{]*\{", code)
    owner = str(replay_spec.get("owner") or "")
    alphabet = str(replay_spec.get("alphabet") or "")
    motifs = [str(value) for value in list(replay_spec.get("motifs") or [])]
    initial_pairs = [str(value) for value in list(replay_spec.get("initial_pairs") or [])]
    vowel = str(replay_spec.get("vowel") or "")
    consonant = str(replay_spec.get("consonant") or "")
    context_chars = str(replay_spec.get("context_chars") or "")
    setter = str(replay_spec.get("length_setter") or "")
    if (
        not class_match or not owner or len(alphabet) < 15 or len(motifs) < 3
        or len(vowel) != 1 or len(consonant) != 1 or len(context_chars) < 3
        or not setter
    ):
        return {}
    class_open = code.find("{", class_match.start())
    if class_open < 0:
        return {}
    scaffold = code[:class_open + 1].rstrip() + "\n}\n"
    junit5 = "org.junit.jupiter" in code
    annotation = "@org.junit.jupiter.api.Test" if junit5 else "@org.junit.Test"
    assertions = "org.junit.jupiter.api.Assertions" if junit5 else "org.junit.Assert"
    name = "testDeterministicWindowedStringMatrix"
    motifs_literal = ", ".join(json.dumps(value) for value in motifs)
    pairs_literal = ", ".join(json.dumps(value) for value in initial_pairs)
    lines = [
        annotation,
        f"public void {name}() {{",
        f"    {owner} subject = new {owner}();",
        f"    subject.{setter}(32);",
        "    java.util.Set<String> inputs = new java.util.LinkedHashSet<String>();",
        "    inputs.add(null);",
        '    inputs.add("");',
        f"    String alphabet = {json.dumps(alphabet)};",
        f"    String contexts = {json.dumps(context_chars)};",
        "    for (int i = 0; i < alphabet.length(); i++) {",
        "        char c = alphabet.charAt(i);",
        "        inputs.add(String.valueOf(c));",
        f"        inputs.add({json.dumps(vowel)} + c + {json.dumps(vowel)});",
        f"        inputs.add({json.dumps(consonant)} + c + {json.dumps(consonant)});",
        f"        inputs.add({json.dumps(vowel)} + c + {json.dumps(consonant)});",
        f"        inputs.add({json.dumps(consonant)} + c + {json.dumps(vowel)});",
        f"        inputs.add({json.dumps(vowel)} + c + c + {json.dumps(vowel)});",
        "        for (int j = 0; j < contexts.length(); j++) {",
        "            char x = contexts.charAt(j);",
        f"            inputs.add(x + String.valueOf(c) + {json.dumps(vowel)});",
        f"            inputs.add({json.dumps(vowel)} + c + String.valueOf(x));",
        f"            inputs.add(x + String.valueOf(c) + {json.dumps(consonant)});",
        f"            inputs.add({json.dumps(consonant)} + c + String.valueOf(x));",
        "        }",
        "    }",
        f"    for (String pair : new String[] {{{pairs_literal}}}) inputs.add(pair);",
        f"    for (String motif : new String[] {{{motifs_literal}}}) {{",
        "        inputs.add(motif);",
        f"        inputs.add({json.dumps(vowel)} + motif);",
        f"        inputs.add({json.dumps(consonant)} + motif);",
        f"        inputs.add(motif + {json.dumps(vowel)});",
        f"        inputs.add(motif + {json.dumps(consonant)});",
        f"        inputs.add({json.dumps(vowel)} + motif + {json.dumps(vowel)});",
        f"        inputs.add({json.dumps(consonant)} + motif + {json.dumps(consonant)});",
        "    }",
        "    for (String input : inputs) {",
        "        // assertion inserted after exact target identity is checked",
        "    }",
        "}",
    ]
    # The method name is part of the exact target identity, never inferred
    # from a domain label.
    target_method = str(replay_spec.get("target_method") or "")
    if not target_method:
        return {}
    lines[-3] = (
        f"        {assertions}.assertNotNull(subject.{target_method}(input), input);"
        if junit5
        else f"        {assertions}.assertNotNull(input, subject.{target_method}(input));"
    )
    source = _insert_test_method_into_candidate_class(scaffold, "\n".join(lines))
    if not source:
        return {}
    return {
        "row_id": "windowed_string_matrix",
        "source": source,
        "test_method_name": name,
        "proof_status": "source_proven_unvalidated_windowed_string_matrix",
    }


def _source_verified_mutable_dto_graph_replay_spec(
    *,
    source_text: str,
    source_file: Path,
    class_name: str,
    method_name: str,
    target_descriptor: str = "",
) -> dict[str, Any]:
    """Resolve a mutable DTO graph whose null/value axes govern the target.

    This intentionally recognizes a complete source shape, not names from a
    benchmark.  Every object in the graph must have a visible no-arg
    constructor and the exact setters consumed by the target.
    """

    signature, body = _source_backed_exact_target_method_source(
        source_text=source_text,
        class_name=class_name,
        method_name=method_name,
        target_descriptor=target_descriptor,
    )
    if not signature or not body:
        return {}
    bindings = _method_parameter_bindings(f"{signature} {{{body}}}", target_descriptor)
    if len(bindings) != 2:
        return {}
    root_type, root_var = bindings[0]
    time_type, _time_var = bindings[1]
    if re.sub(r"\s+", "", time_type) not in {"Instant", "java.time.Instant"}:
        return {}
    root_simple = re.sub(r"<.*>|\[\]", "", root_type).split(".")[-1].strip()
    clean_body = _strip_comments_preserve_literals(body)
    required_root_calls = ("isError", "getUsage", "getFirstChoice")
    if not all(
        re.search(rf"\b{re.escape(root_var)}\.{name}\s*\(", clean_body)
        for name in required_root_calls
    ):
        return {}

    source_path_text = str(source_file.resolve())
    marker = f"{os.sep}src{os.sep}main{os.sep}java{os.sep}"
    if marker not in source_path_text:
        return {}
    java_root = Path(source_path_text.split(marker, 1)[0]) / "src" / "main" / "java"
    package_match = re.search(r"\bpackage\s+([\w.]+)\s*;", source_text)
    package_name = package_match.group(1) if package_match else ""
    import_map = {
        fqn.rsplit(".", 1)[-1]: fqn
        for fqn in re.findall(r"\bimport\s+([\w.]+)\s*;", source_text)
    }

    cache: dict[str, tuple[str, str]] = {}

    def resolve_type(simple: str) -> tuple[str, str]:
        simple = re.sub(r"<.*>|\[\]", "", simple).split(".")[-1].strip()
        if simple in cache:
            return cache[simple]
        fqn = import_map.get(simple) or (f"{package_name}.{simple}" if package_name else simple)
        path = java_root / Path(*fqn.split(".")).with_suffix(".java")
        if not path.is_file():
            candidates = list(java_root.rglob(f"{simple}.java"))
            if len(candidates) != 1:
                cache[simple] = ("", "")
                return cache[simple]
            path = candidates[0]
            relative = path.relative_to(java_root).with_suffix("")
            fqn = ".".join(relative.parts)
        text = path.read_text(encoding="utf-8", errors="ignore")
        cache[simple] = (fqn, text)
        return cache[simple]

    def getter_type(owner_text: str, getter: str) -> str:
        match = re.search(
            rf"\bpublic\s+([\w$.,<> ?\[\]]+)\s+{re.escape(getter)}\s*\(\s*\)",
            owner_text,
        )
        return re.sub(r"\s+", " ", match.group(1)).strip() if match else ""

    def list_element(type_text: str) -> str:
        match = re.search(r"(?:List|java\.util\.List)\s*<\s*([\w.$]+)\s*>", type_text)
        return match.group(1).split(".")[-1] if match else ""

    def has_noarg(owner_text: str, simple: str) -> bool:
        if re.search(rf"\bpublic\s+{re.escape(simple)}\s*\(\s*\)", owner_text):
            return True
        constructor_declared = bool(
            re.search(
                rf"\b(?:public|protected|private)?\s*{re.escape(simple)}\s*\(",
                owner_text,
            )
        )
        return bool(
            not constructor_declared
            and re.search(rf"\bpublic\s+(?:final\s+)?class\s+{re.escape(simple)}\b", owner_text)
        )

    def has_setters(owner_text: str, names: tuple[str, ...]) -> bool:
        return all(
            re.search(rf"\bpublic\s+void\s+{re.escape(name)}\s*\(", owner_text)
            for name in names
        )

    root_fqn, root_source = resolve_type(root_simple)
    if not root_source or not has_noarg(root_source, root_simple):
        return {}
    choice_simple = getter_type(root_source, "getFirstChoice").split(".")[-1]
    usage_simple = getter_type(root_source, "getUsage").split(".")[-1]
    error_simple = getter_type(root_source, "getError").split(".")[-1]
    choice_fqn, choice_source = resolve_type(choice_simple)
    usage_fqn, usage_source = resolve_type(usage_simple)
    error_fqn, error_source = resolve_type(error_simple)
    if not all((choice_source, usage_source, error_source)):
        return {}
    delta_simple = getter_type(choice_source, "getDelta").split(".")[-1]
    delta_fqn, delta_source = resolve_type(delta_simple)
    if not delta_source:
        return {}
    detail_simple = list_element(getter_type(delta_source, "getReasoningDetails"))
    tool_simple = list_element(getter_type(delta_source, "getToolCalls"))
    detail_fqn, detail_source = resolve_type(detail_simple)
    tool_fqn, tool_source = resolve_type(tool_simple)
    if not detail_source or not tool_source:
        return {}
    function_simple = getter_type(tool_source, "getFunction").split(".")[-1]
    function_fqn, function_source = resolve_type(function_simple)
    if not function_source:
        return {}

    required_shapes = (
        (root_source, root_simple, ("setObject", "setChoices", "setUsage", "setError")),
        (choice_source, choice_simple, ("setDelta", "setFinishReason")),
        (
            delta_source,
            delta_simple,
            ("setReasoningContent", "setContent", "setReasoningDetails", "setToolCalls"),
        ),
        (detail_source, detail_simple, ("setType", "setId", "setIndex", "setData", "setText")),
        (tool_source, tool_simple, ("setId", "setIndex", "setThoughtSignature", "setFunction")),
        (function_source, function_simple, ("setName", "setArguments")),
        (usage_source, usage_simple, ("setPromptTokens", "setCompletionTokens")),
        (error_source, error_simple, ("setMessage", "setCode")),
    )
    if not all(
        has_noarg(owner_text, simple) and has_setters(owner_text, setters)
        for owner_text, simple, setters in required_shapes
    ):
        return {}
    if '"chat.completion.chunk"' not in root_source:
        return {}
    detail_literals = set(re.findall(r'"([\w.]+)"', clean_body))
    required_detail_literals = {"reasoning.encrypted", "reasoning.text", "reasoning.summary"}
    if not required_detail_literals.issubset(detail_literals):
        return {}
    if not all(token in clean_body for token in ("startsWith(\"{\")", "endsWith(\"}\")")):
        return {}

    entry_method = ""
    for match in re.finditer(
        rf"\bpublic\s+[\w$.,<> ?\[\]]+\s+([A-Za-z_$][\w$]*)\s*\(\s*"
        rf"{re.escape(root_simple)}\s+[A-Za-z_$][\w$]*\s*,\s*(?:java\.time\.)?Instant\s+"
        rf"[A-Za-z_$][\w$]*\s*\)\s*\{{",
        source_text,
    ):
        open_brace = source_text.find("{", match.start())
        close_brace = _find_matching_brace(source_text, open_brace)
        entry_body = source_text[open_brace + 1:close_brace] if close_brace >= 0 else ""
        if re.search(rf"\b{re.escape(method_name)}\s*\(", entry_body):
            entry_method = match.group(1)
            break
    if not entry_method:
        return {}
    owner_clean = _strip_comments_preserve_literals(source_text)
    if not re.search(rf"\bpublic\s+{re.escape(class_name)}\s*\(\s*\)", owner_clean):
        return {}
    owner_fqn = f"{package_name}.{class_name}" if package_name else class_name
    return {
        "owner_fqn": owner_fqn,
        "entry_method": entry_method,
        "target_method": method_name,
        "root_fqn": root_fqn,
        "choice_fqn": choice_fqn,
        "delta_fqn": delta_fqn,
        "detail_fqn": detail_fqn,
        "tool_fqn": tool_fqn,
        "function_fqn": function_fqn,
        "usage_fqn": usage_fqn,
        "error_fqn": error_fqn,
        "target_descriptor": target_descriptor,
        "proof_status": "source_verified_mutable_dto_graph",
    }


def _deterministic_mutable_dto_graph_matrix_source(
    *, candidate_code: str, replay_spec: dict[str, Any]
) -> dict[str, Any]:
    """Build one bounded matrix over a fully source-verified mutable DTO graph."""

    code = str(candidate_code or "")
    class_match = re.search(r"\b(?:public\s+)?(?:final\s+)?class\s+[A-Za-z_$][\w$]*[^\{]*\{", code)
    required = (
        "owner_fqn", "entry_method", "root_fqn", "choice_fqn", "delta_fqn",
        "detail_fqn", "tool_fqn", "function_fqn", "usage_fqn", "error_fqn",
    )
    if not class_match or any(not str(replay_spec.get(key) or "") for key in required):
        return {}
    class_open = code.find("{", class_match.start())
    if class_open < 0:
        return {}
    scaffold = code[:class_open + 1].rstrip() + "\n}\n"
    annotation = "@org.junit.jupiter.api.Test" if "org.junit.jupiter" in code else "@org.junit.Test"
    assertions = "org.junit.jupiter.api.Assertions" if "org.junit.jupiter" in code else "org.junit.Assert"
