def _source_verified_character_context_classifier_replay_spec(
    *,
    source_text: str,
    class_name: str,
    method_name: str,
    target_descriptor: str = "",
) -> dict[str, Any]:
    """Resolve a finite character classifier with previous/next context."""

    signature, body = _source_backed_exact_target_method_source(
        source_text=source_text,
        class_name=class_name,
        method_name=method_name,
        target_descriptor=target_descriptor,
    )
    if not signature or not body or not re.search(r"\bpublic\b", signature):
        return {}
    bindings = _method_parameter_bindings(f"{signature} {{{body}}}", target_descriptor)
    if len(bindings) != 1 or re.sub(r"\s+", "", bindings[0][0]) not in {
        "String", "java.lang.String"
    }:
        return {}
    prefix = signature.split(method_name, 1)[0].strip()
    if not re.search(r"(?:java\.lang\.)?String\s*$", prefix):
        return {}
    clean = _strip_comments_preserve_literals(source_text)
    clean_body = _strip_comments_preserve_literals(body)
    if not (
        re.search(r"\bwhile\s*\(", clean_body)
        and re.search(r"\b(?:last|previous)[A-Za-z_$]*\b", clean_body, re.IGNORECASE)
        and re.search(r"\bnext[A-Za-z_$]*\b", clean_body, re.IGNORECASE)
        and re.search(r"\barrayContains\s*\(", clean_body)
        and re.search(r"\.put\s*\(", clean_body)
        and re.search(r"<\s*'A'|>\s*'Z'", clean_body)
    ):
        return {}
    arrays = re.findall(
        r"\bstatic\s+final\s+char\s*\[\s*\]\s+[A-Za-z_$][\w$]*\s*=\s*\{([^}]*)\}",
        clean,
    )
    if len(arrays) < 5:
        return {}
    alphabet: list[str] = []
    for array_body in arrays:
        for char in re.findall(r"'([A-Za-z])'", array_body):
            char = char.upper()
            if char not in alphabet:
                alphabet.append(char)
    for char in re.findall(r"'([A-Za-z])'", clean_body):
        char = char.upper()
        if char not in alphabet:
            alphabet.append(char)
    if len(alphabet) < 15:
        return {}
    unicode_escapes = _unique_preserve_order(
        re.findall(r"case\s+'(\\u[0-9A-Fa-f]{4})'\s*:", clean)
    )
    unicode_inputs = [chr(int(value[2:], 16)) for value in unicode_escapes]
    explicit_public_noarg = re.search(
        rf"\bpublic\s+{re.escape(class_name)}\s*\(\s*\)", clean
    )
    any_declared_constructor = re.search(
        rf"(?:^|[;{{}}])\s*(?:public\s+|protected\s+|private\s+)?"
        rf"{re.escape(class_name)}\s*\(",
        clean,
        re.MULTILINE,
    )
    implicit_public_noarg = bool(
        re.search(rf"\bpublic\s+(?:final\s+)?class\s+{re.escape(class_name)}\b", clean)
        and not any_declared_constructor
    )
    if not explicit_public_noarg and not implicit_public_noarg:
        return {}
    return {
        "owner": class_name,
        "target_method": method_name,
        "alphabet": "".join(alphabet),
        "unicode_inputs": unicode_inputs[:12],
        "target_descriptor": target_descriptor,
        "proof_status": "source_verified_character_context_classifier",
    }


def _deterministic_character_context_classifier_matrix_source(
    *, candidate_code: str, replay_spec: dict[str, Any]
) -> dict[str, Any]:
    """Build one bounded single/adjacent-character matrix."""

    code = str(candidate_code or "")
    class_match = re.search(r"\b(?:public\s+)?(?:final\s+)?class\s+[A-Za-z_$][\w$]*[^\{]*\{", code)
    owner = str(replay_spec.get("owner") or "")
    target_method = str(replay_spec.get("target_method") or "")
    alphabet = str(replay_spec.get("alphabet") or "")
    unicode_inputs = [str(value) for value in list(replay_spec.get("unicode_inputs") or [])]
    if not class_match or not owner or not target_method or len(alphabet) < 15:
        return {}
    class_open = code.find("{", class_match.start())
    if class_open < 0:
        return {}
    scaffold = code[:class_open + 1].rstrip() + "\n}\n"
    junit5 = "org.junit.jupiter" in code
    annotation = "@org.junit.jupiter.api.Test" if junit5 else "@org.junit.Test"
    assertions = "org.junit.jupiter.api.Assertions" if junit5 else "org.junit.Assert"
    unicode_literals = ", ".join(json.dumps(value) for value in unicode_inputs)
    name = "testDeterministicCharacterContextClassifierMatrix"
    method = f"""
{annotation}
public void {name}() {{
    {owner} subject = new {owner}();
    {assertions}.assertNull(subject.{target_method}(null));
    {assertions}.assertNotNull(subject.{target_method}(""));
    String alphabet = {json.dumps(alphabet)};
    for (int i = 0; i < alphabet.length(); i++) {{
        char current = alphabet.charAt(i);
        {assertions}.assertNotNull(subject.{target_method}(String.valueOf(current)));
        {assertions}.assertNotNull(subject.{target_method}(String.valueOf(Character.toLowerCase(current))));
        {assertions}.assertNotNull(subject.{target_method}("1" + current + "!"));
        {assertions}.assertNotNull(subject.{target_method}("A" + current + current + "A"));
        for (int j = 0; j < alphabet.length(); j++) {{
            char context = alphabet.charAt(j);
            {assertions}.assertNotNull(subject.{target_method}("" + current + context));
            {assertions}.assertNotNull(subject.{target_method}("" + context + current));
        }}
    }}
    for (String input : new String[] {{{unicode_literals}}}) {{
        {assertions}.assertNotNull(subject.{target_method}(input));
    }}
}}
"""
    source = _insert_test_method_into_candidate_class(scaffold, method)
    if not source:
        return {}
    return {
        "row_id": "character_context_classifier_matrix",
        "source": source,
        "test_method_name": name,
        "proof_status": "source_proven_unvalidated_character_context_classifier_matrix",
    }


def _source_verified_stax_pruning_replay_spec(
    *,
    source_text: str,
    source_file: Path,
    class_name: str,
    method_name: str,
    target_descriptor: str = "",
) -> dict[str, Any]:
    """Prove a public StAX entry and its finite pruning callback surface."""

    signature, body = _source_backed_exact_target_method_source(
        source_text=source_text,
        class_name=class_name,
        method_name=method_name,
        target_descriptor=target_descriptor,
    )
    params = [
        value.rsplit(".", 1)[-1]
        for value in _java_signature_parameter_types(signature, method_name)
    ]
    if not signature or params != ["JDOMFactory", "XMLStreamReader", "int", "StAXFilter"]:
        return {}
    clean_body = _strip_comments_preserve_literals(body)
    callbacks = (
        "pruneElement", "pruneCDATA", "pruneText", "pruneComment",
        "pruneEntityRef", "pruneProcessingInstruction",
    )
    if not (
        re.search(r"\bswitch\s*\(\s*[A-Za-z_$][\w$]*\.next\s*\(\s*\)\s*\)", clean_body)
        and all(re.search(rf"\.{name}\s*\(", clean_body) for name in callbacks)
        and re.search(r"\bSTART_ELEMENT\b", clean_body)
        and re.search(r"\bENTITY_REFERENCE\b", clean_body)
        and re.search(r"\bPROCESSING_INSTRUCTION\b", clean_body)
    ):
        return {}
    try:
        from tatg.engines.tatg_adapter import TATGEngineAdapter

        blocks = TATGEngineAdapter()._collect_method_blocks(source_text)
    except Exception:
        return {}
    intermediate = next(
        (
            block for block in blocks
            if str(block.get("name") or "") != method_name
            and re.search(
                rf"\b{re.escape(method_name)}\s*\(",
                _strip_comments_preserve_literals(str(block.get("body") or "")),
            )
        ),
        None,
    )
    if not intermediate:
        return {}
    intermediate_name = str(intermediate.get("name") or "")
    public_entry = next(
        (
            block for block in blocks
            if re.search(r"\bpublic\b", str(block.get("signature") or ""))
            and re.search(
                rf"\b{re.escape(intermediate_name)}\s*\(",
                _strip_comments_preserve_literals(str(block.get("body") or "")),
            )
            and [
                value.rsplit(".", 1)[-1]
                for value in _java_signature_parameter_types(
                    str(block.get("signature") or ""), str(block.get("name") or "")
                )
            ] == ["XMLStreamReader", "StAXFilter"]
        ),
        None,
    )
    if not public_entry:
        return {}
    package_match = re.search(r"(?m)^\s*package\s+([A-Za-z_$][\w$.]*)\s*;", source_text)
    imports = {
        fqn.rsplit(".", 1)[-1]: fqn
        for fqn in re.findall(r"(?m)^\s*import\s+([A-Za-z_$][\w$.]*)\s*;", source_text)
    }
    package_name = str(package_match.group(1) if package_match else "")
    filter_fqn = str(imports.get("StAXFilter") or "")
    namespace_fqn = str(imports.get("Namespace") or "")
    if not package_name or not filter_fqn or not namespace_fqn:
        return {}
    source_root = source_file.parent
    for part in reversed(package_name.split(".")):
        if source_root.name != part:
            return {}
        source_root = source_root.parent
    filter_file = source_root / Path(*filter_fqn.split(".")).with_suffix(".java")
    implementation: tuple[str, str] | None = None
    try:
        filter_dir = filter_file.parent
        for candidate_file in sorted(filter_dir.glob("*.java")):
            candidate_source = _strip_comments_preserve_literals(
                candidate_file.read_text(encoding="utf-8", errors="ignore")
            )
            class_match = re.search(
                rf"\bpublic\s+class\s+([A-Za-z_$][\w$]*)\s+implements\s+"
                rf"(?:[A-Za-z_$][\w$.]*\.)?{re.escape(filter_fqn.rsplit('.', 1)[-1])}\b",
                candidate_source,
            )
            if not class_match or not all(
                re.search(rf"\bpublic\b[^;{{}}]*\b{name}\s*\(", candidate_source)
                for name in callbacks
            ):
                continue
            impl_name = class_match.group(1)
            constructors = re.findall(rf"\b{re.escape(impl_name)}\s*\(", candidate_source)
            if constructors and not re.search(
                rf"\bpublic\s+{re.escape(impl_name)}\s*\(\s*\)", candidate_source
            ):
                continue
            impl_package = re.search(
                r"(?m)^\s*package\s+([A-Za-z_$][\w$.]*)\s*;", candidate_source
            )
            if impl_package:
                implementation = (f"{impl_package.group(1)}.{impl_name}", impl_name)
                break
    except OSError:
        return {}
    if not implementation:
        return {}
    return {
        "owner_fqn": f"{package_name}.{class_name}",
        "entry_method": str(public_entry.get("name") or ""),
        "filter_impl_fqn": implementation[0],
        "namespace_fqn": namespace_fqn,
        "target_descriptor": target_descriptor,
        "proof_status": "source_verified_stax_pruning_event_tree",
    }


def _deterministic_stax_pruning_matrix_source(
    *, candidate_code: str, replay_spec: dict[str, Any]
) -> dict[str, Any]:
    """Build one bounded XML-event and callback-decision matrix."""

    code = str(candidate_code or "")
    class_match = re.search(
        r"\b(?:public\s+)?(?:final\s+)?class\s+[A-Za-z_$][\w$]*[^\{]*\{", code
    )
    required = ("owner_fqn", "entry_method", "filter_impl_fqn", "namespace_fqn")
    if not class_match or not all(str(replay_spec.get(key) or "") for key in required):
        return {}
    class_open = code.find("{", class_match.start())
    if class_open < 0:
        return {}
    scaffold = code[:class_open + 1].rstrip() + "\n}\n"
    owner = str(replay_spec["owner_fqn"])
    entry = str(replay_spec["entry_method"])
    filter_impl = str(replay_spec["filter_impl_fqn"])
    namespace = str(replay_spec["namespace_fqn"])
    junit5 = "org.junit.jupiter" in code
    annotation = "@org.junit.jupiter.api.Test" if junit5 else "@org.junit.Test"
    assertions = "org.junit.jupiter.api.Assertions" if junit5 else "org.junit.Assert"
    name = "testDeterministicStaxPruningEventMatrix"
    method = f'''
{annotation}
public void {name}() throws Exception {{
    {owner} subject = new {owner}();
    String rich = "<?xml version='1.0'?><root>text<![CDATA[cdata]]><!--comment-->"
        + "<?pi data?><child attr='v'>nested</child></root>";
    javax.xml.stream.XMLInputFactory inputFactory = javax.xml.stream.XMLInputFactory.newFactory();
    java.util.List<?> included = subject.{entry}(
        inputFactory.createXMLStreamReader(new java.io.StringReader(rich)), new {filter_impl}());
    {assertions}.assertFalse(included.isEmpty());

    String nested = "<?xml version='1.0'?><root><drop><nested>ignored</nested></drop>"
        + "<keep>visible</keep></root>";
    {filter_impl} pruning = new {filter_impl}() {{
        @Override public boolean pruneElement(int depth, String local, {namespace} ns) {{
            return "drop".equals(local);
        }}
        @Override public String pruneText(int depth, String text) {{ return null; }}
        @Override public String pruneCDATA(int depth, String text) {{ return null; }}
        @Override public String pruneComment(int depth, String text) {{ return null; }}
        @Override public boolean pruneProcessingInstruction(int depth, String target) {{ return true; }}
    }};
    java.util.List<?> pruned = subject.{entry}(
        inputFactory.createXMLStreamReader(new java.io.StringReader(nested)), pruning);
    {assertions}.assertFalse(pruned.isEmpty());
    java.util.List<?> droppedEvents = subject.{entry}(
        inputFactory.createXMLStreamReader(new java.io.StringReader(rich)), pruning);
    {assertions}.assertFalse(droppedEvents.isEmpty());

    javax.xml.stream.XMLInputFactory entityFactory = javax.xml.stream.XMLInputFactory.newFactory();
    entityFactory.setProperty(javax.xml.stream.XMLInputFactory.IS_REPLACING_ENTITY_REFERENCES, false);
    entityFactory.setProperty(javax.xml.stream.XMLInputFactory.SUPPORT_DTD, true);
    String entity = "<?xml version='1.0'?><!DOCTYPE root [<!ENTITY e 'value'>]><root>&e;</root>";
    java.util.List<?> keptEntity = subject.{entry}(
        entityFactory.createXMLStreamReader(new java.io.StringReader(entity)), new {filter_impl}());
    {assertions}.assertFalse(keptEntity.isEmpty());
    {filter_impl} entityPruning = new {filter_impl}() {{
        @Override public boolean pruneEntityRef(int depth, String local) {{ return true; }}
    }};
    java.util.List<?> prunedEntity = subject.{entry}(
        entityFactory.createXMLStreamReader(new java.io.StringReader(entity)), entityPruning);
    {assertions}.assertFalse(prunedEntity.isEmpty());
}}
'''
    source = _insert_test_method_into_candidate_class(scaffold, method)
    if not source:
        return {}
    return {
        "row_id": "stax_pruning_event_matrix",
        "source": source,
        "test_method_name": name,
        "proof_status": "source_proven_unvalidated_stax_pruning_event_matrix",
    }


def _source_verified_configurable_field_policy_replay_spec(
    *, source_text: str, class_name: str, method_name: str, target_descriptor: str = ""
) -> dict[str, Any]:
    """Prove a configurable reflection-field exclusion decision tree."""

    signature, body = _source_backed_exact_target_method_source(
        source_text=source_text,
        class_name=class_name,
        method_name=method_name,
        target_descriptor=target_descriptor,
    )
    params = [
        value.rsplit(".", 1)[-1]
        for value in _java_signature_parameter_types(signature, method_name)
    ]
    if not signature or not re.search(r"\bpublic\b", signature) or params != ["Field", "boolean"]:
        return {}
    clean = _strip_comments_preserve_literals(source_text)
    clean_body = _strip_comments_preserve_literals(body)
    required = (
        r"getModifiers\s*\(", r"getAnnotation\s*\(", r"isSynthetic\s*\(",
        r"\brequire[A-Za-z_$]*\b", r"\bserialize[A-Za-z_$]*Inner[A-Za-z_$]*\b",
        r"isAnonymousOrNonStaticLocal\s*\(", r"shouldSkipField\s*\(",
    )
    if not all(re.search(pattern, clean_body) for pattern in required):
        return {}
    default_match = re.search(
        rf"\bpublic\s+static\s+final\s+{re.escape(class_name)}\s+"
        rf"([A-Za-z_$][\w$]*)\s*=\s*new\s+{re.escape(class_name)}\s*\(\s*\)",
        clean,
    )
    if not default_match:
        return {}
    try:
        from tatg.engines.tatg_adapter import TATGEngineAdapter

        blocks = TATGEngineAdapter()._collect_method_blocks(source_text)
    except Exception:
        return {}
    public_owner_blocks = [
        block for block in blocks
        if re.search(r"\bpublic\b", str(block.get("signature") or ""))
        and re.search(
            rf"\b{re.escape(class_name)}\b",
            str(block.get("signature") or "").split(str(block.get("name") or ""), 1)[0],
        )
    ]

    def simple_params(block: dict[str, Any]) -> list[str]:
        name = str(block.get("name") or "")
        return [
            value.rsplit(".", 1)[-1].replace("...", "[]")
            for value in _java_signature_parameter_types(str(block.get("signature") or ""), name)
        ]

    version_block = next((b for b in public_owner_blocks if simple_params(b) == ["double"]), None)
    modifiers_block = next((b for b in public_owner_blocks if simple_params(b) == ["int[]"]), None)
    expose_block = next(
        (b for b in public_owner_blocks if not simple_params(b) and re.search(r"\brequire[A-Za-z_$]*\s*=\s*true", str(b.get("body") or ""))),
        None,
    )
    inner_block = next(
        (b for b in public_owner_blocks if not simple_params(b) and re.search(r"\bserialize[A-Za-z_$]*Inner[A-Za-z_$]*\s*=\s*false", str(b.get("body") or ""))),
        None,
    )
    strategy_block = next(
        (b for b in public_owner_blocks if simple_params(b) == ["ExclusionStrategy", "boolean", "boolean"]),
        None,
    )
    if not all((version_block, modifiers_block, expose_block, inner_block, strategy_block)):
        return {}
    imports = {
        fqn.rsplit(".", 1)[-1]: fqn
        for fqn in re.findall(r"(?m)^\s*import\s+([A-Za-z_$][\w$.]*)\s*;", source_text)
    }
    required_types = ("Since", "Until", "Expose", "ExclusionStrategy", "FieldAttributes")
    if not all(imports.get(name) for name in required_types):
        return {}
    package_match = re.search(r"(?m)^\s*package\s+([A-Za-z_$][\w$.]*)\s*;", source_text)
    if not package_match:
        return {}
    return {
        "owner_fqn": f"{package_match.group(1)}.{class_name}",
        "target_method": method_name,
        "default_field": default_match.group(1),
        "version_method": str(version_block.get("name") or ""),
        "modifiers_method": str(modifiers_block.get("name") or ""),
        "expose_method": str(expose_block.get("name") or ""),
        "inner_method": str(inner_block.get("name") or ""),
        "strategy_method": str(strategy_block.get("name") or ""),
        "types": {name: imports[name] for name in required_types},
        "target_descriptor": target_descriptor,
        "proof_status": "source_verified_configurable_field_policy",
    }


def _deterministic_configurable_field_policy_matrix_source(
    *, candidate_code: str, replay_spec: dict[str, Any]
) -> dict[str, Any]:
    """Build one reflection-field/configuration matrix from visible APIs."""

    code = str(candidate_code or "")
    class_match = re.search(r"\b(?:public\s+)?(?:final\s+)?class\s+[A-Za-z_$][\w$]*[^\{]*\{", code)
    required = (
        "owner_fqn", "target_method", "default_field", "version_method",
        "modifiers_method", "expose_method", "inner_method", "strategy_method",
    )
    types = dict(replay_spec.get("types") or {})
    if not class_match or not all(str(replay_spec.get(key) or "") for key in required) or len(types) != 5:
        return {}
    class_open = code.find("{", class_match.start())
    if class_open < 0:
        return {}
    scaffold = code[:class_open + 1].rstrip() + "\n}\n"
    owner = str(replay_spec["owner_fqn"])
    target = str(replay_spec["target_method"])
    default = f"{owner}.{replay_spec['default_field']}"
    junit5 = "org.junit.jupiter" in code
    annotation = "@org.junit.jupiter.api.Test" if junit5 else "@org.junit.Test"
    assertions = "org.junit.jupiter.api.Assertions" if junit5 else "org.junit.Assert"
    name = "testDeterministicConfigurableFieldPolicyMatrix"
    since, until, expose = (types["Since"], types["Until"], types["Expose"])
    strategy, attributes = types["ExclusionStrategy"], types["FieldAttributes"]
    method = f'''
private static class DeterministicFieldPolicyFixture {{
    transient String transientValue;
    static String staticValue;
    private String privateValue;
    String ordinary;
    @{since}(2.0) String sinceTwo;
    @{until}(1.0) String untilOne;
    @{expose} String exposed;
    @{expose}(serialize = false, deserialize = true) String deserializeOnly;
    @{expose}(serialize = true, deserialize = false) String serializeOnly;
    Inner inner;
    class Inner {{}}
}}

{annotation}
public void {name}() throws Exception {{
    java.lang.Class<?> fixture = DeterministicFieldPolicyFixture.class;
    {owner} base = {default};
    {assertions}.assertTrue(base.{target}(fixture.getDeclaredField("transientValue"), true));
    {assertions}.assertTrue(base.{target}(fixture.getDeclaredField("staticValue"), false));
    {assertions}.assertFalse(base.{target}(fixture.getDeclaredField("ordinary"), true));
    {owner} modifiers = base.{replay_spec['modifiers_method']}(java.lang.reflect.Modifier.PRIVATE);
    {assertions}.assertTrue(modifiers.{target}(fixture.getDeclaredField("privateValue"), true));
    {assertions}.assertFalse(modifiers.{target}(fixture.getDeclaredField("ordinary"), false));
    {owner} versioned = base.{replay_spec['version_method']}(1.5);
    {assertions}.assertTrue(versioned.{target}(fixture.getDeclaredField("sinceTwo"), true));
    {assertions}.assertTrue(versioned.{target}(fixture.getDeclaredField("untilOne"), false));
    {owner} exposedPolicy = base.{replay_spec['expose_method']}();
    {assertions}.assertTrue(exposedPolicy.{target}(fixture.getDeclaredField("ordinary"), true));
    {assertions}.assertFalse(exposedPolicy.{target}(fixture.getDeclaredField("exposed"), true));
    {assertions}.assertTrue(exposedPolicy.{target}(fixture.getDeclaredField("deserializeOnly"), true));
    {assertions}.assertFalse(exposedPolicy.{target}(fixture.getDeclaredField("deserializeOnly"), false));
    {assertions}.assertFalse(exposedPolicy.{target}(fixture.getDeclaredField("serializeOnly"), true));
    {assertions}.assertTrue(exposedPolicy.{target}(fixture.getDeclaredField("serializeOnly"), false));
    {owner} noInner = base.{replay_spec['inner_method']}();
    {assertions}.assertTrue(noInner.{target}(fixture.getDeclaredField("inner"), true));
    {strategy} skipOrdinary = new {strategy}() {{
        @Override public boolean shouldSkipField({attributes} field) {{ return "ordinary".equals(field.getName()); }}
        @Override public boolean shouldSkipClass(Class<?> type) {{ return false; }}
    }};
    {owner} serialization = base.{replay_spec['strategy_method']}(skipOrdinary, true, false);
    {assertions}.assertTrue(serialization.{target}(fixture.getDeclaredField("ordinary"), true));
    {assertions}.assertFalse(serialization.{target}(fixture.getDeclaredField("ordinary"), false));
    {owner} deserialization = base.{replay_spec['strategy_method']}(skipOrdinary, false, true);
    {assertions}.assertFalse(deserialization.{target}(fixture.getDeclaredField("ordinary"), true));
    {assertions}.assertTrue(deserialization.{target}(fixture.getDeclaredField("ordinary"), false));
}}
'''
    source = _insert_test_method_into_candidate_class(scaffold, method)
    if not source:
        return {}
    return {
        "row_id": "configurable_field_policy_matrix",
        "source": source,
        "test_method_name": name,
        "proof_status": "source_proven_unvalidated_configurable_field_policy_matrix",
    }


def _source_verified_transition_graph_evaluator_replay_spec(
    *,
    source_text: str,
    source_file: Path,
    class_name: str,
    method_name: str,
    target_descriptor: str = "",
) -> dict[str, Any]:
    """Resolve a package-visible transition graph setup from source only.

    The gate is deliberately structural.  It requires the target traversal,
    the mutable state API, the terminal transition constructor, and two
    source-declared pattern factories before a deterministic probe is built.
    """

    signature, body = _source_backed_exact_target_method_source(
        source_text=source_text,
        class_name=class_name,
        method_name=method_name,
        target_descriptor=target_descriptor,
    )
    params = _java_signature_parameter_types(signature, method_name)
    clean_body = _strip_comments_preserve_literals(body)
    if not signature or len(params) != 1:
        return {}
    required_target_calls = (
        "getTransitions",
        "expand",
        "getNextByteState",
        "getTransitionForAllBytes",
        "getTransitionForNextByteStates",
    )
    if not all(
        re.search(rf"\.{name}\s*\(", clean_body) for name in required_target_calls
    ):
        return {}
    clean_source = _strip_comments_preserve_literals(source_text)
    if not all(
        re.search(rf"\.{name}\s*\(", clean_source)
        for name in ("getMatches", "getPattern")
    ):
        return {}
    if not re.search(r"\bQueue\s*<", clean_body) or not re.search(r"\bvisited\b", clean_body):
        return {}

    package_match = re.search(
        r"(?m)^\s*package\s+([A-Za-z_$][\w$.]*)\s*;", source_text
    )
    ctor_match = re.search(
        rf"\b(?:public\s+|protected\s+)?{re.escape(class_name)}\s*\(\s*int\s+"
        r"[A-Za-z_$][\w$]*\s*\)",
        source_text,
    )
    if not package_match or not ctor_match:
        return {}

    state_type = params[0]
    state_file = source_file.parent / f"{state_type}.java"
    if not state_file.is_file():
        return {}
    try:
        state_source = state_file.read_text(encoding="utf-8", errors="ignore")
    except OSError:
        return {}
    state_clean = _strip_comments_preserve_literals(state_source)
    if not re.search(rf"\bclass\s+{re.escape(state_type)}\b", state_clean):
        return {}
    put_match = re.search(
        r"\bvoid\s+([A-Za-z_$][\w$]*)\s*\(\s*byte\s+[A-Za-z_$][\w$]*\s*,"
        r"\s*(?:@[A-Za-z_$][\w$.]*(?:\([^)]*\))?\s*)*"
        r"([A-Za-z_$][\w$]*)\s+[A-Za-z_$][\w$]*\s*\)",
        state_clean,
    )
    put_all_match = re.search(
        r"\bvoid\s+([A-Za-z_$][\w$]*ForAllBytes)\s*\(\s*"
        r"(?:@[A-Za-z_$][\w$.]*(?:\([^)]*\))?\s*)*"
        r"([A-Za-z_$][\w$]*)\s+[A-Za-z_$][\w$]*\s*\)",
        state_clean,
    )
    if not put_match or not put_all_match or put_match.group(2) != put_all_match.group(2):
        return {}

    match_type = ""
    match_ctor: re.Match[str] | None = None
    for candidate_type in dict.fromkeys(
        re.findall(r"\bSet\s*<\s*([A-Za-z_$][\w$]*)\s*>", clean_source)
    ):
        candidate_file = source_file.parent / f"{candidate_type}.java"
        if not candidate_file.is_file():
            continue
        try:
            candidate_source = candidate_file.read_text(
                encoding="utf-8", errors="ignore"
            )
        except OSError:
            continue
        candidate_clean = _strip_comments_preserve_literals(candidate_source)
        candidate_ctor = re.search(
            rf"\b{re.escape(candidate_type)}\s*\(\s*([A-Za-z_$][\w$]*)\s+"
            r"[A-Za-z_$][\w$]*\s*,\s*([A-Za-z_$][\w$]*)\s+"
            r"[A-Za-z_$][\w$]*\s*\)",
            candidate_clean,
        )
        if candidate_ctor and re.search(
            rf"\bSet\s*<\s*{re.escape(candidate_type)}\s*>[^;{{}}]*\bmatches\b",
            clean_source,
        ):
            match_type = candidate_type
            match_ctor = candidate_ctor
            break
    if not match_type or match_ctor is None:
        return {}
    pattern_type = match_ctor.group(1)
    pattern_file = source_file.parent / f"{pattern_type}.java"
    if not pattern_file.is_file():
        return {}
    try:
        pattern_source = pattern_file.read_text(encoding="utf-8", errors="ignore")
    except OSError:
        return {}
    pattern_clean = _strip_comments_preserve_literals(pattern_source)

    def factory_for(enum_name: str) -> str:
        match = re.search(
            rf"\bpublic\s+static\s+[A-Za-z_$][\w$]*\s+([A-Za-z_$][\w$]*)\s*"
            rf"\(\s*(?:final\s+)?String\s+[A-Za-z_$][\w$]*\s*\)\s*\{{[^}}]*\b{enum_name}\b",
            pattern_clean,
            re.DOTALL,
        )
        return str(match.group(1) if match else "")

    wildcard_factory = factory_for("WILDCARD")
    exact_factory = factory_for("EXACT")
    if not wildcard_factory or not exact_factory:
        return {}
    return {
        "owner_fqn": f"{package_match.group(1)}.{class_name}",
        "target_method": method_name,
        "state_type": state_type,
        "put_transition": put_match.group(1),
        "put_all_bytes": put_all_match.group(1),
        "transition_type": put_match.group(2),
        "match_type": match_type,
        "pattern_type": pattern_type,
        "wildcard_factory": wildcard_factory,
        "exact_factory": exact_factory,
        "target_descriptor": target_descriptor,
        "proof_status": "source_verified_transition_graph_evaluator",
    }


def _deterministic_transition_graph_evaluator_matrix_source(
    *, candidate_code: str, replay_spec: dict[str, Any]
) -> dict[str, Any]:
    """Build a bounded state/transition matrix for an exact source shape."""

    code = str(candidate_code or "")
    class_match = re.search(
        r"\b(?:public\s+)?(?:final\s+)?class\s+[A-Za-z_$][\w$]*[^\{]*\{", code
    )
    required = (
        "owner_fqn", "target_method", "state_type", "put_transition",
        "put_all_bytes", "match_type", "pattern_type", "wildcard_factory",
        "exact_factory",
    )
    if not class_match or not all(str(replay_spec.get(key) or "") for key in required):
        return {}
    class_open = code.find("{", class_match.start())
    if class_open < 0:
        return {}
    scaffold = code[: class_open + 1].rstrip() + "\n}\n"
    owner = str(replay_spec["owner_fqn"])
    target = str(replay_spec["target_method"])
    state = str(replay_spec["state_type"])
    match = str(replay_spec["match_type"])
    pattern = str(replay_spec["pattern_type"])
    put = str(replay_spec["put_transition"])
    put_all = str(replay_spec["put_all_bytes"])
    wildcard = str(replay_spec["wildcard_factory"])
    exact = str(replay_spec["exact_factory"])
    junit5 = "org.junit.jupiter" in code
    annotation = "@org.junit.jupiter.api.Test" if junit5 else "@org.junit.Test"
    assertions = "org.junit.jupiter.api.Assertions" if junit5 else "org.junit.Assert"
    name = "testDeterministicTransitionGraphEvaluatorMatrix"
    method = f'''
{annotation}
public void {name}() throws Exception {{
    {state} empty = new {state}();
    {assertions}.assertEquals(0, new {owner}(10).{target}(empty));

    {state} directWildcard = new {state}();
    directWildcard.{put}((byte) 'a', new {match}({pattern}.{wildcard}("a*"), null));
    {assertions}.assertEquals(1, new {owner}(10).{target}(directWildcard));
    {assertions}.assertEquals(1, new {owner}(1).{target}(directWildcard));

    {state} wildcardChild = new {state}();
    wildcardChild.{put_all}(new {match}({pattern}.{wildcard}("b*"), null));
    {state} parent = new {state}();
    parent.{put}((byte) 'b', wildcardChild);
    {assertions}.assertEquals(2, new {owner}(10).{target}(parent));

    {state} nextByteChild = new {state}();
    nextByteChild.{put}((byte) 'c', new {match}({pattern}.{exact}("c"), null));
    {state} nextByteParent = new {state}();
    nextByteParent.{put}((byte) 'b', nextByteChild);
    {assertions}.assertEquals(0, new {owner}(10).{target}(nextByteParent));
}}
'''
    source = _insert_test_method_into_candidate_class(scaffold, method)
    if not source:
        return {}
    return {
        "row_id": "transition_graph_evaluator_matrix",
        "source": source,
        "test_method_name": name,
        "proof_status": "source_proven_unvalidated_transition_graph_matrix",
    }


def _source_verified_stax_content_dispatch_replay_spec(
    *,
    source_text: str,
    source_file: Path,
    class_name: str,
    method_name: str,
    target_descriptor: str = "",
) -> dict[str, Any]:
    """Prove a public StAX list entry for a complete Content-type dispatch."""

    signature, body = _source_backed_exact_target_method_source(
        source_text=source_text,
        class_name=class_name,
        method_name=method_name,
        target_descriptor=target_descriptor,
    )
    params = _java_signature_parameter_types(signature, method_name)
    clean_body = _strip_comments_preserve_literals(body)
    if (
        not signature
        or not re.search(r"\bprotected\b", signature)
        or not params
        or params[-1] != "Walker"
    ):
        return {}
    required_cases = (
        "CDATA", "Comment", "Element", "EntityRef",
        "ProcessingInstruction", "Text", "DocType",
    )
    required_flow = (
        r"while\s*\([^)]*\.hasNext\s*\(",
        r"=\s*[A-Za-z_$][\w$]*\.next\s*\(",
        r"==\s*null",
        r"\.isCDATA\s*\(",
        r"switch\s*\([^)]*\.getCType\s*\(",
    )
    if not all(re.search(pattern, clean_body) for pattern in required_flow):
        return {}
    if not all(re.search(rf"\bcase\s+{case}\s*:", clean_body) for case in required_cases):
        return {}
    clean_source = _strip_comments_preserve_literals(source_text)
    if re.search(r"\babstract\s+[^{;]+;", clean_source):
        return {}

    try:
        from tatg.engines.tatg_adapter import TATGEngineAdapter

        blocks = TATGEngineAdapter()._collect_method_blocks(
            source_text, class_name=class_name
        )
    except Exception:
        return {}
    entry_block: dict[str, Any] | None = None
    entry_params: list[str] = []
    for block in blocks:
        name = str(block.get("name") or "")
        block_signature = str(block.get("signature") or "")
        block_body = _strip_comments_preserve_literals(str(block.get("body") or ""))
        candidate_params = _java_signature_parameter_types(block_signature, name)
        if (
            name != method_name
            and re.search(r"\bpublic\b", block_signature)
            and candidate_params
            and candidate_params[-1] == "List"
            and re.search(rf"\b{re.escape(method_name)}\s*\(", block_body)
        ):
            entry_block = block
            entry_params = candidate_params
            break
    if entry_block is None:
        return {}
    event_mode = entry_params == ["XMLEventConsumer", "Format", "XMLEventFactory", "List"]
    stream_mode = entry_params == ["XMLStreamWriter", "Format", "List"]
    if not event_mode and not stream_mode:
        return {}

    package_match = re.search(
        r"(?m)^\s*package\s+([A-Za-z_$][\w$.]*)\s*;", source_text
    )
    if not package_match:
        return {}
    package_parts = package_match.group(1).split(".")
    source_root = source_file.parent
    for _ in package_parts:
        source_root = source_root.parent
    imports = {
        fqn.rsplit(".", 1)[-1]: fqn
        for fqn in re.findall(
            r"(?m)^\s*import\s+([A-Za-z_$][\w$.]*)\s*;", source_text
        )
    }
    ctor_arity = {
        "CDATA": 1,
        "Comment": 1,
        "Element": 1,
        "EntityRef": 1,
        "ProcessingInstruction": 2,
        "Text": 1,
        "DocType": 1,
    }
    content_types: dict[str, str] = {}
    for type_name, arity in ctor_arity.items():
        fqn = imports.get(type_name, "")
        type_file = source_root / (fqn.replace(".", "/") + ".java")
        if not fqn or not type_file.is_file():
            return {}
        try:
            type_source = _strip_comments_preserve_literals(
                type_file.read_text(encoding="utf-8", errors="ignore")
            )
        except OSError:
            return {}
        ctor_candidates = re.findall(
            rf"\b(?:public\s+|protected\s+)?{re.escape(type_name)}\s*\(([^)]*)\)",
            type_source,
            re.DOTALL,
        )
        if not any(len(_split_top_level_java_args(args)) == arity for args in ctor_candidates):
            return {}
        content_types[type_name] = fqn
    format_fqn = imports.get("Format", "")
    format_file = source_root / (format_fqn.replace(".", "/") + ".java")
    if not format_fqn or not format_file.is_file():
        return {}
    try:
        format_source = _strip_comments_preserve_literals(
            format_file.read_text(encoding="utf-8", errors="ignore")
        )
    except OSError:
        return {}
    if not all(
        re.search(rf"\bpublic\s+static\s+Format\s+{factory}\s*\(", format_source)
        for factory in ("getRawFormat", "getPrettyFormat")
    ):
        return {}
    return {
        "owner_fqn": f"{package_match.group(1)}.{class_name}",
        "target_method": method_name,
        "entry_method": str(entry_block.get("name") or ""),
        "mode": "event" if event_mode else "stream",
        "format_fqn": format_fqn,
        "content_types": content_types,
        "target_descriptor": target_descriptor,
        "proof_status": "source_verified_stax_content_dispatch",
    }


def _deterministic_stax_content_dispatch_matrix_source(
    *, candidate_code: str, replay_spec: dict[str, Any]
) -> dict[str, Any]:
    """Build raw and formatted rows for a source-verified Content switch."""

    code = str(candidate_code or "")
    class_match = re.search(
        r"\b(?:public\s+)?(?:final\s+)?class\s+[A-Za-z_$][\w$]*[^\{]*\{", code
    )
    owner = str(replay_spec.get("owner_fqn") or "")
    entry = str(replay_spec.get("entry_method") or "")
    mode = str(replay_spec.get("mode") or "")
    fmt = str(replay_spec.get("format_fqn") or "")
    types = dict(replay_spec.get("content_types") or {})
    required_types = (
        "CDATA", "Comment", "Element", "EntityRef",
        "ProcessingInstruction", "Text", "DocType",
    )
    if (
        not class_match
        or not owner
        or not entry
        or mode not in {"event", "stream"}
        or not fmt
        or not all(types.get(name) for name in required_types)
    ):
        return {}
    class_open = code.find("{", class_match.start())
    if class_open < 0:
        return {}
    scaffold = code[: class_open + 1].rstrip() + "\n}\n"
    junit5 = "org.junit.jupiter" in code
    annotation = "@org.junit.jupiter.api.Test" if junit5 else "@org.junit.Test"
    assertions = "org.junit.jupiter.api.Assertions" if junit5 else "org.junit.Assert"
    name = "testDeterministicStAXContentDispatchMatrix"
    values = ", ".join((
        f'new {types["CDATA"]}("cdata")',
        f'new {types["Comment"]}("comment")',
        f'new {types["Element"]}("child").setText("nested")',
        f'new {types["EntityRef"]}("entity")',
        f'new {types["ProcessingInstruction"]}("target", "data")',
        f'new {types["Text"]}("text")',
        f'new {types["DocType"]}("root")',
    ))
    lines = [
        annotation,
        f"public void {name}() throws Exception {{",
        f"    {owner} processor = new {owner}() {{}};",
        f"    org.jdom2.Content[] values = new org.jdom2.Content[] {{{values}}};",
    ]
    if mode == "event":
        lines.extend([
            "    javax.xml.stream.XMLEventFactory factory = javax.xml.stream.XMLEventFactory.newFactory();",
            "    for (org.jdom2.Content value : values) {",
            "        java.util.List<javax.xml.stream.events.XMLEvent> events = new java.util.ArrayList<>();",
            f"        processor.{entry}(events::add, {fmt}.getRawFormat(), factory, java.util.Collections.singletonList(value));",
            f"        {assertions}.assertFalse(events.isEmpty());",
            "    }",
            f"    for (org.jdom2.Content value : new org.jdom2.Content[] {{new {types['Text']}(\" a  b \"), new {types['CDATA']}(\" cdata \")}}) {{",
            "        java.util.List<javax.xml.stream.events.XMLEvent> events = new java.util.ArrayList<>();",
            f"        processor.{entry}(events::add, {fmt}.getPrettyFormat(), factory, java.util.Collections.singletonList(value));",
            f"        {assertions}.assertFalse(events.isEmpty());",
            "    }",
        ])
    else:
        lines.extend([
            "    for (org.jdom2.Content value : values) {",
            "        java.io.StringWriter sink = new java.io.StringWriter();",
            "        javax.xml.stream.XMLStreamWriter writer = javax.xml.stream.XMLOutputFactory.newFactory().createXMLStreamWriter(sink);",
            f"        processor.{entry}(writer, {fmt}.getRawFormat(), java.util.Collections.singletonList(value));",
            "        writer.close();",
            f"        {assertions}.assertFalse(sink.toString().isEmpty());",
            "    }",
            f"    for (org.jdom2.Content value : new org.jdom2.Content[] {{new {types['Text']}(\" a  b \"), new {types['CDATA']}(\" cdata \")}}) {{",
            "        java.io.StringWriter sink = new java.io.StringWriter();",
            "        javax.xml.stream.XMLStreamWriter writer = javax.xml.stream.XMLOutputFactory.newFactory().createXMLStreamWriter(sink);",
            f"        processor.{entry}(writer, {fmt}.getPrettyFormat(), java.util.Collections.singletonList(value));",
            "        writer.close();",
            f"        {assertions}.assertFalse(sink.toString().isEmpty());",
            "    }",
        ])
    lines.append("}")
    source = _insert_test_method_into_candidate_class(scaffold, "\n".join(lines))
    if not source:
        return {}
    return {
        "row_id": f"stax_content_dispatch_{mode}_matrix",
        "source": source,
        "test_method_name": name,
        "proof_status": "source_proven_unvalidated_stax_content_dispatch_matrix",
    }


def _source_verified_reactive_state_command_replay_spec(
    *,
    source_text: str,
    class_name: str,
    method_name: str,
    target_descriptor: str = "",
) -> dict[str, Any]:
    """Prove a finite command/state matrix with a public state initializer."""

    signature, body = _source_backed_exact_target_method_source(
        source_text=source_text,
        class_name=class_name,
        method_name=method_name,
        target_descriptor=target_descriptor,
    )
    params = [
        re.sub(r"\s+", "", str(type_name or "")).split("<", 1)[0]
        for type_name, _name in _method_parameter_bindings(
            f"{signature} {{{body}}}", target_descriptor
        )
    ]
    if not params or any(
        not re.fullmatch(r"[A-Za-z_$][\w$]*(?:\[\])?", value)
        for value in params
    ):
        try:
            from tatg.engines.tatg_adapter import TATGEngineAdapter

            params = _java_signature_parameter_types(
                TATGEngineAdapter._strip_balanced_java_annotations(signature),
                method_name,
            )
        except Exception:
            params = []
    clean_body = _strip_comments_preserve_literals(body)
    if (
        not signature
        or not re.search(r"\bpublic\b", signature)
        or not re.search(r"\bMono\s*<\s*String\s*>", signature)
        or not re.search(r"\bvalidate[A-Za-z_$][\w$]*\s*\(\s*\)\s*;", clean_body)
    ):
        return {}
    mode = ""
    if params == ["int", "String", "Map"]:
        literals = set(re.findall(r'"(add|revise|delete)"', clean_body))
        if literals != {"add", "revise", "delete"} or not all(
            re.search(pattern, clean_body)
            for pattern in (
                r"switch\s*\(",
                r"<\s*0",
                r">=?\s*[A-Za-z_$][\w$]*\.size\s*\(\s*\)",
                r"\.add\s*\(",
                r"\.set\s*\(",
                r"\.remove\s*\(",
            )
        ):
            return {}
        mode = "command"
    elif params == ["int", "String"]:
        required_literals = {"todo", "in_progress", "abandoned"}
        signature_and_body = f"{signature}\n{body}".lower()
        if not all(value in signature_and_body for value in required_literals) or not all(
            re.search(pattern, clean_body)
            for pattern in (
                r"\.valueOf\s*\(",
                r"\bDONE\b",
                r"\bIN_PROGRESS\b",
                r"\bABANDONED\b",
                r"for\s*\(",
                r"\.setState\s*\(",
            )
        ):
            return {}
        mode = "state"
    else:
        return {}

    try:
        from tatg.engines.tatg_adapter import TATGEngineAdapter

        blocks = TATGEngineAdapter()._collect_method_blocks(
            source_text, class_name=class_name
        )
    except Exception:
        return {}
    setup_method = ""
    for block in blocks:
        name = str(block.get("name") or "")
        block_signature = str(block.get("signature") or "")
        block_body = _strip_comments_preserve_literals(str(block.get("body") or ""))
        block_params = _java_signature_parameter_types(
            TATGEngineAdapter._strip_balanced_java_annotations(block_signature),
            name,
        )
        if (
            name != method_name
            and re.search(r"\bpublic\b", block_signature)
            and re.search(r"\bMono\s*<\s*String\s*>", block_signature)
            and block_params == ["String", "String", "String", "List"]
            and re.search(r"\bnew\s+[A-Za-z_$][\w$]*\s*\(", block_body)
            and re.search(r"\bcurrent[A-Za-z_$][\w$]*\s*=\s*[A-Za-z_$][\w$]*\s*;", block_body)
        ):
            setup_method = name
            break
    builder_match = re.search(
        rf"\bpublic\s+static\s+[A-Za-z_$][\w$]*\s+([A-Za-z_$][\w$]*)\s*\(\s*\)\s*\{{"
        rf"[^}}]*\bnew\s+[A-Za-z_$][\w$]*\s*\(\s*\)",
        _strip_comments_preserve_literals(source_text),
        re.DOTALL,
    )
    package_match = re.search(r"(?m)^\s*package\s+([A-Za-z_$][\w$.]*)\s*;", source_text)
    if not setup_method or not builder_match or not package_match or '"name"' not in source_text:
        return {}
    return {
        "owner_fqn": f"{package_match.group(1)}.{class_name}",
        "target_method": method_name,
        "setup_method": setup_method,
        "builder_method": builder_match.group(1),
        "mode": mode,
        "target_descriptor": target_descriptor,
        "proof_status": "source_verified_reactive_state_command",
    }


def _deterministic_reactive_state_command_matrix_source(
    *, candidate_code: str, replay_spec: dict[str, Any]
) -> dict[str, Any]:
    """Build a bounded public-call matrix for a proven reactive state command."""

    code = str(candidate_code or "")
    class_match = re.search(
        r"\b(?:public\s+)?(?:final\s+)?class\s+[A-Za-z_$][\w$]*[^\{]*\{", code
    )
    required = ("owner_fqn", "target_method", "setup_method", "builder_method", "mode")
    if not class_match or not all(str(replay_spec.get(key) or "") for key in required):
        return {}
    class_open = code.find("{", class_match.start())
    if class_open < 0:
        return {}
    scaffold = code[: class_open + 1].rstrip() + "\n}\n"
    owner = str(replay_spec["owner_fqn"])
    target = str(replay_spec["target_method"])
    setup = str(replay_spec["setup_method"])
    builder = str(replay_spec["builder_method"])
    mode = str(replay_spec["mode"])
    junit5 = "org.junit.jupiter" in code
    annotation = "@org.junit.jupiter.api.Test" if junit5 else "@org.junit.Test"
    assertions = "org.junit.jupiter.api.Assertions" if junit5 else "org.junit.Assert"
    name = "testDeterministicReactiveStateCommandMatrix"
    helpers = f'''
private static java.util.Map<String, Object> tatgTask(String name) {{
    java.util.Map<String, Object> value = new java.util.HashMap<>();
    value.put("name", name);
    return value;
}}
private static {owner} tatgNotebook(int count) {{
    {owner} subject = {owner}.{builder}().build();
    java.util.List<java.util.Map<String, Object>> values = new java.util.ArrayList<>();
    for (int i = 0; i < count; i++) values.add(tatgTask("task-" + i));
    subject.{setup}("plan", "description", "outcome", values).block();
    return subject;
}}
'''
    if mode == "command":
        calls = f'''
    {assertions}.assertNotNull(tatgNotebook(1).{target}(0, "invalid", null).block());
    {assertions}.assertNotNull(tatgNotebook(1).{target}(-1, "add", tatgTask("x")).block());
    {assertions}.assertNotNull(tatgNotebook(1).{target}(2, "add", tatgTask("x")).block());
    {assertions}.assertNotNull(tatgNotebook(1).{target}(-1, "revise", tatgTask("x")).block());
    {assertions}.assertNotNull(tatgNotebook(1).{target}(1, "delete", null).block());
    {assertions}.assertNotNull(tatgNotebook(1).{target}(1, "add", null).block());
    {assertions}.assertNotNull(tatgNotebook(1).{target}(0, "revise", null).block());
    {assertions}.assertNotNull(tatgNotebook(1).{target}(1, "add", tatgTask("added")).block());
    {assertions}.assertNotNull(tatgNotebook(1).{target}(0, "revise", tatgTask("revised")).block());
    {assertions}.assertNotNull(tatgNotebook(1).{target}(0, "delete", null).block());
'''
    elif mode == "state":
        calls = f'''
    {assertions}.assertNotNull(tatgNotebook(1).{target}(-1, "todo").block());
    {assertions}.assertNotNull(tatgNotebook(1).{target}(1, "todo").block());
    {assertions}.assertNotNull(tatgNotebook(1).{target}(0, "unknown").block());
    {assertions}.assertNotNull(tatgNotebook(1).{target}(0, "done").block());
    {assertions}.assertNotNull(tatgNotebook(2).{target}(1, "in_progress").block());
    {owner} active = tatgNotebook(3);
    {assertions}.assertNotNull(active.{target}(0, "abandoned").block());
    {assertions}.assertNotNull(active.{target}(1, "abandoned").block());
    {assertions}.assertNotNull(active.{target}(2, "in_progress").block());
    {assertions}.assertNotNull(active.{target}(0, "in_progress").block());
    {owner} valid = tatgNotebook(2);
    {assertions}.assertNotNull(valid.{target}(0, "abandoned").block());
    {assertions}.assertNotNull(valid.{target}(1, "in_progress").block());
    {assertions}.assertNotNull(valid.{target}(1, "abandoned").block());
'''
    else:
        return {}
    method = f'''{helpers}
{annotation}
public void {name}() {{
{calls}}}
'''
    source = _insert_test_method_into_candidate_class(scaffold, method)
    if not source:
        return {}
    return {
        "row_id": f"reactive_state_command_{mode}_matrix",
        "source": source,
        "test_method_name": name,
        "proof_status": "source_proven_unvalidated_reactive_state_command_matrix",
    }


def _source_verified_schema_validation_replay_spec(
    *,
    source_text: str,
    source_file: Path,
    class_name: str,
    method_name: str,
    target_descriptor: str = "",
) -> dict[str, Any]:
    """Prove a schema type/required validator and its project-visible builder."""

    signature, body = _source_backed_exact_target_method_source(
        source_text=source_text,
        class_name=class_name,
        method_name=method_name,
        target_descriptor=target_descriptor,
    )
    if not signature or not re.search(r"\bpublic\s+static\b", signature):
        return {}
    try:
        from tatg.engines.tatg_adapter import TATGEngineAdapter

        blocks = TATGEngineAdapter()._collect_method_blocks(source_text, class_name=class_name)
    except Exception:
        return {}
    validator_name = ""
    validator_body = ""
    validator_signature = ""
    for block in blocks:
        name = str(block.get("name") or "")
        block_signature = str(block.get("signature") or "")
        block_body = _strip_comments_preserve_literals(str(block.get("body") or ""))
        params = _java_signature_parameter_types(block_signature, name)
        if params == ["Map", "Schema", "Boolean"] and all(
            re.search(pattern, block_body)
            for pattern in (
                r"\.properties\s*\(",
                r"\.entrySet\s*\(",
                r"\.containsKey\s*\(",
                r"\.required\s*\(",
            )
        ):
            validator_name = name
            validator_body = block_body
            validator_signature = block_signature
            break
    target_params = _java_signature_parameter_types(signature, method_name)
    mode = ""
    if method_name == validator_name and target_params == ["Map", "Schema", "Boolean"]:
        mode = "map"
    elif (
        target_params == ["String", "Schema"]
        and validator_name
        and re.search(rf"\b{re.escape(validator_name)}\s*\(", body)
        and re.search(r"\.readValue\s*\(", body)
    ):
        mode = "output"
    if not mode or not validator_signature or not validator_body:
        return {}
    helper_match = re.search(
        r"\b(?:private|public|protected)\s+static\s+Boolean\s+([A-Za-z_$][\w$]*)\s*\(",
        source_text,
    )
    helper_body = ""
    if helper_match:
        for block in blocks:
            if str(block.get("name") or "") == helper_match.group(1):
                helper_body = _strip_comments_preserve_literals(str(block.get("body") or ""))
                break
    required_types = {"STRING", "INTEGER", "BOOLEAN", "NUMBER", "ARRAY", "OBJECT", "TYPE_UNSPECIFIED"}
    if not helper_body or not required_types.issubset(set(re.findall(r"\bcase\s+([A-Z_]+)\s*:", helper_body))):
        return {}
    schema_import = re.search(r"(?m)^\s*import\s+([\w$.]+\.Schema)\s*;", source_text)
    package_match = re.search(r"(?m)^\s*package\s+([A-Za-z_$][\w$.]*)\s*;", source_text)
    source_path_text = str(source_file.resolve())
    marker = f"{os.sep}src{os.sep}main{os.sep}java{os.sep}"
    if not schema_import or not package_match or marker not in source_path_text:
        return {}
    java_root = Path(source_path_text.split(marker, 1)[0]) / "src" / "main" / "java"
    builder_evidence = ""
    required_builder_calls = ("type", "properties", "required", "items", "build")
    observed: set[str] = set()
    for candidate in java_root.rglob("*.java"):
        try:
            text = _strip_comments_preserve_literals(candidate.read_text(encoding="utf-8", errors="ignore"))
        except OSError:
            continue
        if "Schema.builder()" not in text:
            continue
        observed.update(
            call for call in required_builder_calls if re.search(rf"\.{call}\s*\(", text)
        )
        if set(required_builder_calls).issubset(observed):
            builder_evidence = str(candidate)
            break
    if not builder_evidence:
        return {}
    return {
        "owner_fqn": f"{package_match.group(1)}.{class_name}",
        "target_method": method_name,
        "validator_method": validator_name,
        "schema_fqn": schema_import.group(1),
        "mode": mode,
        "builder_evidence": builder_evidence,
        "target_descriptor": target_descriptor,
        "proof_status": "source_verified_schema_validation",
    }


def _deterministic_schema_validation_matrix_source(
    *, candidate_code: str, replay_spec: dict[str, Any]
) -> dict[str, Any]:
    """Build primitive, aggregate, required, and parse rows for a proven validator."""

    code = str(candidate_code or "")
    class_match = re.search(
        r"\b(?:public\s+)?(?:final\s+)?class\s+[A-Za-z_$][\w$]*[^\{]*\{", code
    )
    required = ("owner_fqn", "target_method", "validator_method", "schema_fqn", "mode")
    if not class_match or not all(str(replay_spec.get(key) or "") for key in required):
        return {}
    class_open = code.find("{", class_match.start())
    if class_open < 0:
        return {}
    scaffold = code[: class_open + 1].rstrip() + "\n}\n"
    owner = str(replay_spec["owner_fqn"])
    target = str(replay_spec["target_method"])
    validator = str(replay_spec["validator_method"])
    schema = str(replay_spec["schema_fqn"])
    mode = str(replay_spec["mode"])
    junit5 = "org.junit.jupiter" in code
    annotation = "@org.junit.jupiter.api.Test" if junit5 else "@org.junit.Test"
    assertions = "org.junit.jupiter.api.Assertions" if junit5 else "org.junit.Assert"
    name = "testDeterministicSchemaValidationMatrix"
    helper = f'''
private static {schema} tatgSchema(String key, {schema} value, boolean required) {{
    if (required) {{
        return {schema}.builder().type("OBJECT")
                .properties(java.util.Collections.singletonMap(key, value))
                .required(java.util.Collections.singletonList(key)).build();
    }}
    return {schema}.builder().type("OBJECT")
            .properties(java.util.Collections.singletonMap(key, value)).build();
}}
'''
    if mode == "map":
        rows = f'''
    {schema} strings = tatgSchema("v", {schema}.builder().type("STRING").build(), false);
    {owner}.{target}(java.util.Collections.singletonMap("v", "ok"), strings, true);
    {assertions}.assertThrows(IllegalArgumentException.class, () -> {owner}.{target}(java.util.Collections.singletonMap("v", 1), strings, true));
    {assertions}.assertThrows(IllegalArgumentException.class, () -> {owner}.{target}(java.util.Collections.singletonMap("v", 1), strings, false));
    {assertions}.assertThrows(IllegalArgumentException.class, () -> {owner}.{target}(java.util.Collections.singletonMap("missing", 1), strings, true));
    {assertions}.assertThrows(IllegalArgumentException.class, () -> {owner}.{target}(java.util.Collections.singletonMap("missing", 1), strings, false));
    {assertions}.assertThrows(NullPointerException.class, () -> {owner}.{target}(java.util.Collections.emptyMap(), strings, null));
    {owner}.{target}(java.util.Collections.singletonMap("v", 1), tatgSchema("v", {schema}.builder().type("INTEGER").build(), false), true);
    {owner}.{target}(java.util.Collections.singletonMap("v", true), tatgSchema("v", {schema}.builder().type("BOOLEAN").build(), false), true);
    {owner}.{target}(java.util.Collections.singletonMap("v", 1.5), tatgSchema("v", {schema}.builder().type("NUMBER").build(), false), true);
    {schema} array = {schema}.builder().type("ARRAY").items({schema}.builder().type("STRING").build()).build();
    {schema} arrayOwner = tatgSchema("v", array, false);
    {owner}.{target}(java.util.Collections.singletonMap("v", java.util.Arrays.asList("a", "b")), arrayOwner, true);
    {assertions}.assertThrows(IllegalArgumentException.class, () -> {owner}.{target}(java.util.Collections.singletonMap("v", java.util.Arrays.asList("a", 1)), arrayOwner, true));
    {assertions}.assertThrows(IllegalArgumentException.class, () -> {owner}.{target}(java.util.Collections.singletonMap("v", "not-list"), arrayOwner, true));
    {schema} nested = tatgSchema("child", {schema}.builder().type("STRING").build(), true);
    {owner}.{target}(java.util.Collections.singletonMap("v", java.util.Collections.singletonMap("child", "ok")), tatgSchema("v", nested, false), true);
    {assertions}.assertThrows(IllegalArgumentException.class, () -> {owner}.{target}(java.util.Collections.singletonMap("v", "not-map"), tatgSchema("v", nested, false), true));
    {schema} required = tatgSchema("v", {schema}.builder().type("STRING").build(), true);
    {assertions}.assertThrows(IllegalArgumentException.class, () -> {owner}.{target}(java.util.Collections.emptyMap(), required, true));
    {assertions}.assertThrows(IllegalArgumentException.class, () -> {owner}.{target}(java.util.Collections.emptyMap(), required, false));
    {schema} unspecified = tatgSchema("v", {schema}.builder().type("TYPE_UNSPECIFIED").build(), false);
    {assertions}.assertThrows(IllegalArgumentException.class, () -> {owner}.{target}(java.util.Collections.singletonMap("v", "x"), unspecified, true));
'''
    elif mode == "output":
        rows = f'''
    {schema} value = tatgSchema("name", {schema}.builder().type("STRING").build(), true);
    {assertions}.assertEquals("Ada", {owner}.{target}("{{\\\"name\\\":\\\"Ada\\\"}}", value).get("name"));
    {assertions}.assertThrows(Exception.class, () -> {owner}.{target}("not-json", value));
    {assertions}.assertThrows(IllegalArgumentException.class, () -> {owner}.{target}("{{}}", value));
'''
    else:
        return {}
    method = f'''{helper}
{annotation}
public void {name}() throws Exception {{
{rows}}}
'''
    source = _insert_test_method_into_candidate_class(scaffold, method)
    if not source:
        return {}
    source, _conflicting_imports = _prefer_exact_fqn_imports(
        source,
        exact_fqns=[schema],
    )
    return {
        "row_id": f"schema_validation_{mode}_matrix",
        "source": source,
        "test_method_name": name,
        "proof_status": "source_proven_unvalidated_schema_validation_matrix",
    }


def _source_verified_small_map_state_replay_spec(
    *,
    source_text: str,
    class_name: str,
    method_name: str,
    target_descriptor: str = "",
) -> dict[str, Any]:
    """Prove a three-slot Map implementation with a threshold delegate mode."""

    supported_methods = {
        "containsKey",
        "containsValue",
        "equals",
        "get",
        "put",
        "remove",
    }
    if method_name not in supported_methods:
        return {}
    signature, body = _source_backed_exact_target_method_source(
        source_text=source_text,
        class_name=class_name,
        method_name=method_name,
        target_descriptor=target_descriptor,
    )
    clean_source = _strip_comments_preserve_literals(source_text)
    clean_body = _strip_comments_preserve_literals(body)
    class_decl = re.search(
        rf"\bpublic\s+class\s+{re.escape(class_name)}\s*"
        r"<\s*[A-Za-z_$][\w$]*\s*,\s*[A-Za-z_$][\w$]*\s*>"
        r"[^\{]*\bimplements\b[^\{]*(?:Map|IterableMap)\s*<",
        clean_source,
        re.DOTALL,
    )
    package_match = re.search(
        r"(?m)^\s*package\s+([A-Za-z_$][\w$.]*)\s*;", source_text
    )
    no_arg_constructor = re.search(
        rf"\bpublic\s+{re.escape(class_name)}\s*\(\s*\)\s*\{{",
        clean_source,
    )
    required_source_patterns = (
        r"\bint\s+size\s*;",
        r"\bkey1\b",
        r"\bkey2\b",
        r"\bkey3\b",
        r"\bvalue1\b",
        r"\bvalue2\b",
        r"\bvalue3\b",
        r"\bdelegateMap\b",
        r"\bconvertToMap\s*\(",
        r"switch\s*\(\s*size\s*\)",
        r"case\s+3\s*:",
        r"case\s+2\s*:",
        r"case\s+1\s*:",
    )
    if (
        not signature
        or not body
        or not re.search(r"\bpublic\b", signature)
        or not class_decl
        or not package_match
        or not no_arg_constructor
        or not all(re.search(pattern, clean_source) for pattern in required_source_patterns)
    ):
        return {}
    # The selected method itself must dispatch on inline state or delegate mode;
    # this prevents a sibling helper from activating the matrix for an unrelated API.
    if not (
        re.search(r"\bdelegateMap\b", clean_body)
        or re.search(r"switch\s*\(\s*size\s*\)", clean_body)
        or re.search(r"\bconvertToMap\s*\(", clean_body)
    ):
        return {}
    return {
        "owner_fqn": f"{package_match.group(1)}.{class_name}",
        "target_method": method_name,
        "target_descriptor": target_descriptor,
        "inline_capacity": 3,
        "proof_status": "source_verified_small_map_state",
    }


def _deterministic_small_map_state_matrix_source(
    *, candidate_code: str, replay_spec: dict[str, Any]
) -> dict[str, Any]:
    """Build a bounded state/position/null/collision/delegate matrix for a proven Map."""

    code = str(candidate_code or "")
    class_match = re.search(
        r"\b(?:public\s+)?(?:final\s+)?class\s+[A-Za-z_$][\w$]*[^\{]*\{", code
    )
    owner = str(replay_spec.get("owner_fqn") or "")
    target = str(replay_spec.get("target_method") or "")
    if not class_match or not owner or not target:
        return {}
    class_open = code.find("{", class_match.start())
    if class_open < 0:
        return {}
    scaffold = code[: class_open + 1].rstrip() + "\n}\n"
    junit5 = "org.junit.jupiter" in code
    annotation = "@org.junit.jupiter.api.Test" if junit5 else "@org.junit.Test"
    assertions = "org.junit.jupiter.api.Assertions" if junit5 else "org.junit.Assert"
    name = "testDeterministicSmallMapStateMatrix"
    support = f'''
private static final class TatgCollisionKey {{
    private final String value;
    TatgCollisionKey(String value) {{ this.value = value; }}
    @Override public int hashCode() {{ return 7; }}
    @Override public boolean equals(Object other) {{
        return other instanceof TatgCollisionKey
                && value.equals(((TatgCollisionKey) other).value);
    }}
}}
private static {owner}<Object, Object> tatgSmallMap(Object... keys) {{
    {owner}<Object, Object> map = new {owner}<>();
    for (int i = 0; i < keys.length; i++) map.put(keys[i], "v" + i);
    return map;
}}
'''
    test = f'''
{annotation}
public void {name}() {{
    {owner}<Object, Object> empty = tatgSmallMap();
    {assertions}.assertNull(empty.get("missing"));
    {assertions}.assertFalse(empty.containsKey("missing"));
    {assertions}.assertFalse(empty.containsValue("missing"));
    {assertions}.assertNull(empty.remove("missing"));

    for (int size = 1; size <= 3; size++) {{
        Object[] keys = new Object[size];
        for (int i = 0; i < size; i++) keys[i] = "k" + i;
        {owner}<Object, Object> map = tatgSmallMap(keys);
        for (int i = 0; i < size; i++) {{
            {assertions}.assertEquals("v" + i, map.get(keys[i]));
            {assertions}.assertTrue(map.containsKey(keys[i]));
            {assertions}.assertTrue(map.containsValue("v" + i));
        }}
        {assertions}.assertNull(map.get("missing"));
        {assertions}.assertFalse(map.containsKey("missing"));
        {assertions}.assertFalse(map.containsValue("missing"));
        for (int position = 0; position < size; position++) {{
            {owner}<Object, Object> removable = tatgSmallMap(keys);
            {assertions}.assertEquals("v" + position, removable.remove(keys[position]));
            {assertions}.assertFalse(removable.containsKey(keys[position]));

            {owner}<Object, Object> nullKeyAtPosition = new {owner}<>();
            {owner}<Object, Object> nullValueAtPosition = new {owner}<>();
            for (int i = 0; i < size; i++) {{
                nullKeyAtPosition.put(i == position ? null : "nk" + i, "nkv" + i);
                nullValueAtPosition.put("nv" + i, i == position ? null : "value" + i);
            }}
            {assertions}.assertEquals("nkv" + position, nullKeyAtPosition.get(null));
            {assertions}.assertTrue(nullKeyAtPosition.containsKey(null));
            {assertions}.assertNull(nullValueAtPosition.get("nv" + position));
            {assertions}.assertTrue(nullValueAtPosition.containsValue(null));
            {assertions}.assertEquals("nkv" + position, nullKeyAtPosition.remove(null));
        }}
    }}

    {owner}<Object, Object> nulls = new {owner}<>();
    nulls.put(null, null);
    {assertions}.assertTrue(nulls.containsKey(null));
    {assertions}.assertTrue(nulls.containsValue(null));
    {assertions}.assertNull(nulls.get(null));
    {assertions}.assertNull(nulls.put(null, "changed"));
    {assertions}.assertEquals("changed", nulls.remove(null));

    TatgCollisionKey collisionA = new TatgCollisionKey("a");
    TatgCollisionKey collisionB = new TatgCollisionKey("b");
    {owner}<Object, Object> collisions = new {owner}<>();
    collisions.put(collisionA, "first");
    collisions.put(collisionB, "second");
    collisions.put(new TatgCollisionKey("c"), "third");
    {assertions}.assertEquals("first", collisions.get(new TatgCollisionKey("a")));
    {assertions}.assertEquals("second", collisions.get(new TatgCollisionKey("b")));
    {assertions}.assertEquals("third", collisions.get(new TatgCollisionKey("c")));
    {assertions}.assertNull(collisions.get(new TatgCollisionKey("missing")));
    {assertions}.assertEquals("second", collisions.remove(new TatgCollisionKey("b")));

    {owner}<Object, Object> replacements = tatgSmallMap("a", "b", "c");
    {assertions}.assertEquals("v0", replacements.put("a", "A"));
    {assertions}.assertEquals("v1", replacements.put("b", "B"));
    {assertions}.assertEquals("v2", replacements.put("c", "C"));
    {assertions}.assertNull(replacements.put("d", "D"));
    {assertions}.assertEquals(4, replacements.size());
    {assertions}.assertEquals("D", replacements.get("d"));
    {assertions}.assertNull(replacements.get("missing"));
    {assertions}.assertFalse(replacements.containsKey("missing"));
    {assertions}.assertEquals("B", replacements.remove("b"));

    {owner}<Object, Object> left = tatgSmallMap("a", "b", "c");
    java.util.Map<Object, Object> same = new java.util.HashMap<>();
    same.put("a", "v0"); same.put("b", "v1"); same.put("c", "v2");
    {assertions}.assertTrue(left.equals(left));
    {assertions}.assertTrue(left.equals(same));
    {assertions}.assertFalse(left.equals(null));
    {assertions}.assertFalse(left.equals("not-a-map"));
    {assertions}.assertFalse(left.equals(java.util.Collections.singletonMap("a", "v0")));
    same.put("c", "different");
    {assertions}.assertFalse(left.equals(same));
}}
'''
    source = _insert_test_method_into_candidate_class(scaffold, support + test)
    if not source:
        return {}
    return {
        "row_id": f"small_map_state_{target}_matrix",
        "source": source,
        "test_method_name": name,
        "proof_status": "source_proven_unvalidated_small_map_state_matrix",
    }


def _prefer_exact_fqn_imports(
    candidate_code: str,
    *,
    exact_fqns: Iterable[str],
) -> tuple[str, list[str]]:
    """Replace only same-simple-name imports contradicted by exact FQN evidence."""

    text = str(candidate_code or "")
    preferred: dict[str, str] = {}
    for raw_fqn in exact_fqns:
        fqn = str(raw_fqn or "").strip()
        if "." not in fqn or fqn.endswith(".*"):
            continue
        simple = fqn.rsplit(".", 1)[-1]
        if simple in preferred and preferred[simple] != fqn:
            preferred[simple] = ""
        else:
            preferred[simple] = fqn
    preferred = {simple: fqn for simple, fqn in preferred.items() if fqn}
    if not text.strip() or not preferred:
        return text, []

    changes: list[str] = []
    lines: list[str] = []
    seen_imports: set[str] = set()
    for line in text.splitlines():
        match = re.match(r"^(\s*import\s+)(?!static\b)([\w.]+)(\s*;\s*)$", line)
        if match:
            imported = str(match.group(2) or "")
            simple = imported.rsplit(".", 1)[-1]
            exact = preferred.get(simple)
            if exact and imported != exact:
                line = f"{match.group(1)}{exact}{match.group(3)}"
                changes.append(f"{simple}:{imported}->{exact}")
            normalized = line.strip()
            if normalized in seen_imports:
                continue
            seen_imports.add(normalized)
        lines.append(line)
    suffix = "\n" if text.endswith("\n") else ""
    return "\n".join(lines) + suffix, changes[:12]


def _insert_test_method_into_candidate_class(source: str, method_block: str) -> str:
    text = str(source or "")
    class_match = re.search(
        r"\b(?:public\s+)?(?:final\s+)?class\s+[A-Za-z_$][\w$]*[^\{]*\{",
        text,
    )
    if not class_match:
        return ""
    open_brace = text.find("{", class_match.start())
    close_brace = _find_matching_brace(text, open_brace)
    if close_brace < 0:
        return ""
    return text[:close_brace].rstrip() + "\n\n" + method_block.strip() + "\n" + text[close_brace:]


def _deterministic_json_row_variant_sources(
    *,
    candidate_code: str,
    replay_spec: dict[str, Any],
    max_variants: int = 8,
) -> list[dict[str, Any]]:
    """Add one source-verified public JSON row per isolated replay candidate."""

    code = str(candidate_code or "")
    owner = str(replay_spec.get("owner") or "").strip()
    rows = list(replay_spec.get("rows") or [])
    if not code or not owner or not rows or max_variants <= 0:
        return []
    if len(_junit_test_method_blocks(code)) != 1:
        return []
    if not re.search(rf"\b{re.escape(owner)}\s*\.\s*(?:compile|check)\s*\(", code):
        return []
    if "org.junit.jupiter" in code:
        annotation = "@org.junit.jupiter.api.Test"
        assertions = "org.junit.jupiter.api.Assertions"
    elif "org.junit.Test" in code:
        annotation = "@org.junit.Test"
        assertions = "org.junit.Assert"
    else:
        return []
    seed_test_names = [name for name, _block in _junit_test_method_blocks(code)]
    class_scaffold, removed_seed_tests = _drop_junit_test_methods_from_source(
        code,
        seed_test_names,
    )
    if removed_seed_tests != seed_test_names:
        return []
    candidate_rows: list[tuple[str, str, bool, list[str]]] = []
    for row in rows:
        base_row_id = re.sub(
            r"\W+",
            "_",
            str(row.get("row_id") or "row"),
        ).strip("_")
        evidence = list(row.get("source_evidence") or [])[:6]
        input_json = str(row.get("input_json") or "").strip()
        if base_row_id and input_json:
            candidate_rows.append((base_row_id, input_json, False, evidence))
        invalid_json = str(row.get("invalid_json") or "").strip()
        if base_row_id and invalid_json:
            candidate_rows.append(
                (f"{base_row_id}__invalid", invalid_json, True, evidence)
            )

    variants: list[dict[str, Any]] = []
    for row_id, input_json, invalid, evidence in candidate_rows:
        if len(variants) >= min(32, max_variants):
            break
        if input_json in code:
            continue
        java_string = json.dumps(input_json)
        method_name = f"testDeterministicJsonReplay_{row_id}"
        if invalid:
            method_block = f"""
{annotation}
public void {method_name}() throws Exception {{
    String invalidJson = {java_string};
    {assertions}.assertNotNull({owner}.check(invalidJson));
}}
"""
        else:
            method_block = f"""
{annotation}
public void {method_name}() throws Exception {{
    String validJson = {java_string};
    {assertions}.assertNull({owner}.check(validJson));
    {assertions}.assertNotNull({owner}.compile(validJson));
}}
"""
        # Streaming validation is method-isolated.  Keeping the green seed in
        # the same candidate causes the job builder to select that duplicate
        # method and never execute the new row.  Reuse only its package,
        # imports, helpers, and class shell.
        variant_source = _insert_test_method_into_candidate_class(
            class_scaffold,
            method_block,
        )
        if not variant_source:
            continue
        variants.append({
            "row_id": row_id,
            "input_json": input_json,
            "invalid": invalid,
            "source": variant_source,
            "test_method_name": method_name,
            "source_evidence": evidence,
        })
    return variants


def _unprocessed_dynamic_stream_futures(
    stream_futures: Iterable[Any],
    processed_stream_futures: set[Any],
) -> set[Any]:
    """Return every dynamically submitted future that still needs harvesting.

    A small replay validation can finish before the coordinator revisits the
    shared future list.  Completed futures are still results, so filtering on
    ``future.done()`` here would lose their lifecycle and coverage evidence.
    """
    return {
        future
        for future in stream_futures
        if future not in processed_stream_futures
    }


def _validated_single_candidate_code(
    passed_item: dict[str, Any],
    payload: dict[str, Any],
) -> str:
    """Prefer the exact method-isolated source that validation proved green."""
    for value in (
        passed_item.get("candidate_code_replay"),
        passed_item.get("candidate_code_excerpt"),
        _payload_candidate_code(payload),
    ):
        source = str(value or "").strip()
        if source:
            return source
    return ""


def _post_repair_replay_seed_payload(
    passed_item: dict[str, Any],
    *,
    method_name: str,
    class_name: str,
    target_descriptor: str,
    source_file: str = "",
) -> dict[str, Any]:
    """Build replay identity solely from one method-isolated green result."""
    test_file = str(passed_item.get("test_file") or "").strip()
    candidate_code = str(
        passed_item.get("candidate_code_replay")
        or passed_item.get("candidate_code_excerpt")
        or ""
    ).strip()
    if not test_file or not candidate_code:
        return {}
    return {
        "test_file": test_file,
        "generated_code": candidate_code,
        "final_code": candidate_code,
        "method_name": str(method_name or ""),
        "class_name": str(class_name or ""),
        # The source path is request-level target identity, not candidate
        # state.  Candidate-level JaCoCo needs it to recover the package FQN;
        # omitting it makes every packaged class look absent from the report.
        "source_file": str(source_file or ""),
        "target_descriptor": str(target_descriptor or ""),
        "target_label": str(passed_item.get("target_label") or ""),
    }


def _source_proven_array_config_scaffold_seed(
    stream_results: list[dict[str, Any]],
    *,
    replay_spec: dict[str, Any],
    method_name: str,
    class_name: str,
    target_descriptor: str,
    source_file: str = "",
) -> tuple[dict[str, Any] | None, dict[str, Any]]:
    """Recover only a class scaffold for independently proven config rows.

    A candidate can fail because its invocation or oracle is wrong while its
    package, imports, class shell, config constant, delimiter, and input shape
    remain usable.  Array/config replay replaces the test method and validates
    each replacement from scratch, so a failed outer scaffold is admissible
    only when the deterministic row builder closes every required field.
    Other replay families continue to require a target-positive green seed.
    """
    if not replay_spec:
        return None, {}
    for item in reversed(list(stream_results or [])):
        if not isinstance(item, dict):
            continue
        payload = _post_repair_replay_seed_payload(
            item,
            method_name=method_name,
            class_name=class_name,
            target_descriptor=target_descriptor,
            source_file=source_file,
        )
        if not payload:
            continue
        if _deterministic_array_config_variant_sources(
            candidate_code=str(payload.get("generated_code") or ""),
            replay_spec=replay_spec,
            max_variants=1,
        ):
            return item, payload
    return None, {}


