def _refresh_candidate_lifecycle_aliases(
    payload: dict[str, Any],
    validation_policy: dict[str, Any],
) -> None:
    """Keep top-level lifecycle aliases synchronized with validation policy.

    Report payloads are assembled in stages: streaming validation may add audit
    rows, repair/rescue can add coverage-positive details later, and rollback
    may rebuild the report summary.  Batch analysis should not have to know
    which nested block was freshest, so non-empty validation-policy details win
    over stale/empty top-level aliases right before writing the final JSON.
    """
    _finalize_pending_candidate_promotion_audit(validation_policy)
    alias_sources = {
        "streaming_candidate_coverage_audit_details": "streaming_candidate_coverage_audit_details",
        "candidate_coverage_audit_details": "streaming_candidate_coverage_audit_details",
        "candidate_audit": "streaming_candidate_coverage_audit_details",
        "coverage_positive_failed_details": "coverage_positive_failed_details",
        "coverage_positive_repair_submitted_details": "coverage_positive_repair_submitted_details",
        "coverage_positive_repair_passed_details": "coverage_positive_repair_passed_details",
        "coverage_positive_repair_regression_details": "coverage_positive_repair_regression_details",
        "passing_no_target_evidence": "streaming_validation_no_target_promotion_skipped_details",
    }
    for alias, source in alias_sources.items():
        value = validation_policy.get(source)
        if value not in (None, "", [], {}):
            payload[alias] = value
        elif alias not in payload:
            payload[alias] = value

    engine_generated = int(payload.get("generated_test_count", 0) or 0)
    streaming_submitted = int(
        validation_policy.get("streaming_validation_submitted", 0) or 0
    )
    streaming_passed = int(
        validation_policy.get("streaming_validation_passed", 0) or 0
    )
    streaming_retained_target_positive = int(
        validation_policy.get("streaming_validation_applied_candidates", 0) or 0
    )
    try:
        reported_retained_target_positive = int(
            payload.get("retained_target_positive_count", 0) or 0
        )
    except (TypeError, ValueError):
        reported_retained_target_positive = 0
    retained_target_positive = max(
        reported_retained_target_positive,
        streaming_retained_target_positive,
    )
    payload["engine_generated_test_count"] = engine_generated
    payload["extracted_candidate_count"] = streaming_submitted
    payload["streaming_validation_submitted"] = streaming_submitted
    payload["streaming_validation_passed"] = streaming_passed
    payload["streaming_retained_target_positive_count"] = (
        streaming_retained_target_positive
    )
    payload["retained_target_positive_count"] = retained_target_positive
    if engine_generated <= 0 and streaming_retained_target_positive > 0:
        # Legacy consumers expect generated_test_count to describe the usable
        # live-run output, not only adapter artifacts. Keep the engine count
        # separately so streaming/deferred generation remains auditable.
        payload["generated_test_count"] = streaming_retained_target_positive
        payload["generated_test_count_source"] = (
            "retained_streaming_target_positive_candidates"
        )
        report_summary = (
            payload.get("report_summary")
            if isinstance(payload.get("report_summary"), dict)
            else {}
        )
        counts = (
            report_summary.get("counts")
            if isinstance(report_summary.get("counts"), dict)
            else {}
        )
        if counts:
            counts["engine_generated_test_count"] = engine_generated
            counts["generated_test_count"] = retained_target_positive
            counts["generated_test_count_source"] = (
                "retained_streaming_target_positive_candidates"
            )
            counts["extracted_candidate_count"] = streaming_submitted


def _candidate_salvage_audit_payload(
    payload: dict[str, Any],
    validation_policy: dict[str, Any],
    *,
    audit_path: Path | None = None,
) -> dict[str, Any]:
    """Build a replay-only candidate lifecycle audit sidecar."""
    report_summary = payload.get("report_summary") if isinstance(payload.get("report_summary"), dict) else {}
    counts = report_summary.get("counts") if isinstance(report_summary.get("counts"), dict) else {}
    coverage = report_summary.get("coverage") if isinstance(report_summary.get("coverage"), dict) else {}
    details = list(validation_policy.get("streaming_candidate_coverage_audit_details") or [])
    coverage_positive_failed = list(validation_policy.get("coverage_positive_failed_details") or [])
    repair_passed = list(validation_policy.get("coverage_positive_repair_passed_details") or [])
    repair_regressions = list(validation_policy.get("coverage_positive_repair_regression_details") or [])
    combination_conflicts = list(validation_policy.get("combination_conflict_failed_candidates") or [])
    target_positive_rows = [
        row for row in details
        if isinstance(row, dict) and bool(row.get("target_positive"))
    ]
    high_coverage_rows = sorted(
        [
            row for row in details
            if isinstance(row, dict)
        ],
        key=lambda row: (
            float(row.get("line_coverage") or 0.0) + float(row.get("branch_coverage") or 0.0),
            int(row.get("line_covered") or 0) + int(row.get("branch_covered") or 0),
        ),
        reverse=True,
    )[:20]
    failed_details = list(validation_policy.get("streaming_validation_failed_details") or [])
    skipped_details = list(validation_policy.get("streaming_validation_skipped_details") or [])
    top_candidates: list[dict[str, Any]] = []
    for row in high_coverage_rows[:10]:
        if not isinstance(row, dict):
            continue
        top_candidates.append({
            "test_method": row.get("test_method"),
            "candidate_role": row.get("candidate_role"),
            "status": row.get("status") or row.get("outcome"),
            "target_positive": row.get("target_positive"),
            "line_coverage": row.get("line_coverage"),
            "branch_coverage": row.get("branch_coverage"),
            "line_covered": row.get("line_covered"),
            "branch_covered": row.get("branch_covered"),
            "promotion_reject_reason": row.get("promotion_reject_reason") or row.get("reject_reason"),
            "failure_category": row.get("failure_category"),
        })
    top_failures: list[dict[str, Any]] = []
    for row in failed_details[:10]:
        if not isinstance(row, dict):
            continue
        signal = row.get("failure_signal") if isinstance(row.get("failure_signal"), dict) else {}
        coverage = row.get("candidate_target_coverage") if isinstance(row.get("candidate_target_coverage"), dict) else {}
        top_failures.append({
            "test_method": row.get("test_method"),
            "failure_type": row.get("failure_type"),
            "failure_category": signal.get("category") or row.get("failure_category") or "uncertain_with_evidence",
            "candidate_role": row.get("candidate_role"),
            "coverage_status": coverage.get("status"),
            "coverage_reason": coverage.get("reason"),
            "repair_skip_reason": row.get("repair_skip_reason"),
            "stdout_tail": row.get("stdout_tail"),
            "failed_test_source_excerpt": row.get("failed_test_source_excerpt"),
        })
    audit: dict[str, Any] = {
        "schema_version": 1,
        "mode": "replay_only_candidate_salvage_audit",
        "audit_path": str(audit_path) if audit_path else None,
        "json_report": payload.get("json_report_path"),
        "live_run_id": payload.get("live_run_id"),
        "project_root": payload.get("project_root"),
        "target_file": payload.get("target_file"),
        "class_name": payload.get("class_name"),
        "method_name": payload.get("method_name"),
        "backend": payload.get("backend"),
        "test_commands": payload.get("test_commands"),
        "test_command": payload.get("test_command"),
        "coverage_report_path": payload.get("coverage_report_path"),
        "candidate_test_files": payload.get("candidate_test_files"),
        "final_validation": {
            "candidate_test_files": (
                (payload.get("final_validation") or {}).get("candidate_test_files")
                if isinstance(payload.get("final_validation"), dict)
                else []
            )
        },
        "final_method_coverage": payload.get("final_method_coverage"),
        "iteration_target_method_coverage": coverage.get("iteration_target_method_coverage"),
        "counts": {
            "generated_test_count": counts.get("generated_test_count"),
            "retained_target_positive_count": counts.get("retained_target_positive_count"),
            "passing_no_target_count": counts.get("passing_no_target_count"),
            "candidate_audit_count": len(details),
            "target_positive_candidate_audit_count": len(target_positive_rows),
            "coverage_positive_failed_count": counts.get("coverage_positive_failed_count"),
            "coverage_positive_failed_detail_count": len(coverage_positive_failed),
            "coverage_positive_repair_passed_count": counts.get("coverage_positive_repair_passed"),
            "coverage_positive_repair_regression_count": len(repair_regressions),
            "combination_conflict_count": len(combination_conflicts),
        },
        "summary": {
            "generated_test_count": counts.get("generated_test_count"),
            "retained_target_positive_count": counts.get("retained_target_positive_count"),
            "passing_no_target_count": counts.get("passing_no_target_count"),
            "candidate_audit_count": len(details),
            "target_positive_candidate_audit_count": len(target_positive_rows),
            "streaming_validation_failed_count": len(failed_details),
            "streaming_validation_skipped_count": len(skipped_details),
            "coverage_positive_failed_detail_count": len(coverage_positive_failed),
            "coverage_positive_repair_regression_count": len(repair_regressions),
            "combination_conflict_count": len(combination_conflicts),
        },
        "top_candidates": top_candidates,
        "top_failures": top_failures,
        "candidate_coverage_audit_details": details,
        "high_coverage_candidate_audit_details": high_coverage_rows,
        "coverage_positive_failed_details": coverage_positive_failed,
        "coverage_positive_repair_passed_details": repair_passed,
        "coverage_positive_repair_regression_details": repair_regressions,
        "streaming_validation_passed_details": validation_policy.get("streaming_validation_passed_details"),
        "streaming_validation_failed_details": failed_details,
        "streaming_validation_skipped_details": skipped_details,
        "passing_no_target_evidence": validation_policy.get("streaming_validation_no_target_promotion_skipped_details"),
        "combination_conflict_failed_candidates": combination_conflicts,
        "repair_passed_coverage_missing_details": validation_policy.get("repair_passed_coverage_missing_details"),
    }
    return {key: value for key, value in audit.items() if value not in (None, "", [], {})}


def _resolve_repair_mode(scope: Scope, repair_mode_raw: str | None) -> str:
    """Resolve repair mode for generate."""
    raw = str(repair_mode_raw or "").strip().lower()
    if raw in {"class", "method"}:
        return raw
    if scope == Scope.METHOD:
        return "method"
    return "class"


def _resolve_path_from_project_root(
    raw_path: str | Path | None,
    project_root: Path,
) -> Path | None:
    """Resolve a CLI project path against project_root, never process cwd."""

    if raw_path is None or not str(raw_path).strip():
        return None
    path = Path(raw_path).expanduser()
    if not path.is_absolute():
        path = project_root / path
    return path.resolve()


def _build_request(args: argparse.Namespace) -> GenerationRequest:
    scope_raw = str(getattr(args, "scope", "") or "").strip()
    if not scope_raw:
        raise ValueError("--scope is required (or set it in config file)")
    scope = Scope(scope_raw)

    backend = str(getattr(args, "backend", "") or "").strip().lower()

    project_root_raw = str(getattr(args, "project_root", "") or "").strip()
    if not project_root_raw:
        raise ValueError("--project-root is required (or set it in config file)")

    project_root = Path(project_root_raw).resolve()
    module_path = _resolve_path_from_project_root(
        args.module_path,
        project_root,
    )
    inference_root = module_path if module_path else project_root

    build_system = detect_build_system(inference_root)
    java_version, junit_version, junit_family = infer_runtime_versions(inference_root, build_system)

    build_system = None
    if getattr(args, "build_system", None):
        build_system = BuildSystem(args.build_system)
    else:
        build_system = detect_build_system(inference_root)

    with_mutation = bool(getattr(args, "with_mutation", False))
    test_commands = _normalize_test_commands(getattr(args, "test_command", ""))
    if not test_commands:
        inferred = infer_test_command(inference_root, build_system, with_mutation=with_mutation)
        if inferred and (not _is_unusable_test_command(inferred)):
            if inference_root != project_root:
                inferred = f"cd {shlex.quote(str(inference_root))} && {inferred}"
            test_commands = [inferred]
    test_command = test_commands[0] if test_commands else ""

    target_file_for_inference = _resolve_path_from_project_root(
        args.target_file,
        project_root,
    )
    coverage_report_path = args.coverage_report_path or infer_coverage_report_path(
        inference_root,
        build_system,
        source_file=target_file_for_inference,
    )
    test_command_map = _normalize_test_command_map(getattr(args, "test_command_map", "{}"))

    auto_java_version, auto_junit_version, auto_junit_family = ("", "", "")
    if args.match_project_versions:
        auto_java_version, auto_junit_version, auto_junit_family = infer_runtime_versions(inference_root, build_system)

    explicit_java_version = (args.java_version or "").strip()
    explicit_junit_version = (args.junit_version or "").strip()
    target_descriptor = str(getattr(args, "target_descriptor", "") or "").strip()
    if target_descriptor:
        os.environ["TATG_TARGET_DESCRIPTOR"] = target_descriptor
    else:
        # `_build_generation_request` is also used repeatedly in-process by
        # tests and embedding callers. Do not let a previous overload's
        # descriptor silently constrain the next method target.
        os.environ.pop("TATG_TARGET_DESCRIPTOR", None)

    java_version = explicit_java_version or auto_java_version or "11"
    junit_version = explicit_junit_version or auto_junit_version
    junit_family = auto_junit_family
    if explicit_junit_version:
        if explicit_junit_version.startswith("4"):
            junit_family = "junit4"
        elif explicit_junit_version.startswith("5"):
            junit_family = "junit5"
        else:
            junit_family = ""
    elif not junit_family:
        if junit_version.startswith("4"):
            junit_family = "junit4"
        elif junit_version.startswith("5"):
            junit_family = "junit5"

    pass_specs = args.pass_spec if isinstance(args.pass_spec, list) else [args.pass_spec]
    filter_classes = args.filter_classes if isinstance(args.filter_classes, list) else [args.filter_classes]
    filter_methods = args.filter_methods if isinstance(args.filter_methods, list) else [args.filter_methods]
    filter_modules = args.filter_modules if isinstance(args.filter_modules, list) else [args.filter_modules]
    api_config = resolve_api_config(
        api_base=getattr(args, "api_base", ""),
        model=getattr(args, "model", ""),
        api_key_env=getattr(args, "api_key_env", DEFAULT_API_KEY_ENV),
    )
    apply_api_config_to_env(api_config)
    llm_timeout_seconds = local_lmstudio_timeout_seconds(
        api_config.api_base,
        max(1, int(args.llm_timeout_seconds)),
        operation="llm",
    )
    branch_analysis_timeout_seconds = local_lmstudio_timeout_seconds(
        api_config.api_base,
        max(
            30,
            int(
                getattr(
                    args,
                    "tatg_branch_analysis_timeout_seconds",
                    600,
                )
                or 600
            ),
        ),
        operation="branch_analysis",
    )
    generation_timeout_seconds = local_lmstudio_timeout_seconds(
        api_config.api_base,
        max(
            0,
            int(
                getattr(
                    args,
                    "tatg_generation_timeout_seconds",
                    os.environ.get("TATG_GENERATION_TIMEOUT_SECONDS", "0"),
                )
                or 0
            ),
        ),
        operation="generation",
    )
    e2e_timeout_seconds = local_lmstudio_timeout_seconds(
        api_config.api_base,
        max(0, int(args.e2e_timeout_seconds)),
        operation="e2e",
    )

    request = GenerationRequest(
        backend=args.backend,
        scope=scope,
        project_root=project_root,
        target_file=target_file_for_inference,
        class_name=args.class_name,
        method_name=args.method_name,
        model=api_config.model,
        api_base=api_config.api_base,
        api_key_env=api_config.api_key_env,
        test_command=test_command,
        test_commands=test_commands,
        coverage_report_path=coverage_report_path,
        coverage_type=args.coverage_type,
        prompt_extra_text=args.prompt_extra_text,
        prompt_extra_file=Path(args.prompt_extra_file).resolve() if args.prompt_extra_file else None,
        prompt_insert=PromptInsertPosition(args.prompt_insert),
        static_analysis_json=Path(args.static_analysis_json).resolve() if args.static_analysis_json else None,
        pass_specs=[p for p in pass_specs if p],
        dry_run=args.dry_run,
        max_iterations=args.max_iterations,
        cat_engine_root=Path(args.cat_engine_root).resolve() if args.cat_engine_root else project_root,
        method_engine_root=Path(args.method_engine_root).resolve() if args.method_engine_root else project_root,
        target_descriptor=target_descriptor,
        module_path=module_path,
        test_command_map=test_command_map,
        java_version=java_version,
        junit_version=junit_version,
        junit_family=junit_family,
        repair_iterations=max(0, int(args.repair_iterations)),
        llm_timeout_seconds=llm_timeout_seconds,
        test_timeout_seconds=max(1, int(args.test_timeout_seconds)),
        e2e_timeout_seconds=e2e_timeout_seconds,
        parallel_targets=max(1, int(getattr(args, "generation_parallelism", None) or args.parallel_targets)),
        generation_parallelism=max(1, int(getattr(args, "generation_parallelism", None) or args.parallel_targets)),
        repair_parallelism=max(1, int(getattr(args, "repair_parallelism", 1) or 1)),
        validation_parallelism=max(1, int(getattr(args, "validation_parallelism", 4) or 4)),
        filter_classes=_expand_comma_args([x for x in filter_classes if x]),
        filter_methods=_expand_comma_args([x for x in filter_methods if x]),
        filter_modules=_expand_comma_args([x for x in filter_modules if x]),
        repair_mode=_resolve_repair_mode(scope, getattr(args, "repair_mode", None)),
        streaming_repair_mode=str(getattr(args, "streaming_repair_mode", "deferred") or "deferred"),
        with_mutation=with_mutation,
        mutation_extra_iterations=max(0, int(getattr(args, "mutation_extra_iterations", 1) or 0)),
        retain_existing_tests=bool(getattr(args, "retain_existing_tests", False)),
        retained_test_seed_evidence=(
            json.loads(os.environ.get("TATG_RETAINED_TEST_SEED_EVIDENCE", "{}"))
            if os.environ.get("TATG_RETAINED_TEST_SEED_EVIDENCE", "").strip()
            else {}
        ),
        pre_generate_teardown=bool(getattr(args, "pre_generate_teardown", True)),
        log_unrepaired_tests=bool(getattr(args, "log_unrepaired_tests", False)),
        log_prompts=bool(getattr(args, "log_prompts", False)),
        log_prompts_limit=max(0, int(getattr(args, "log_prompts_limit", 20) or 20)),
        tatg_preanalysis_timeout_seconds=max(
            0,
            int(getattr(args, "tatg_preanalysis_timeout_seconds", 180) or 0),
        ),
        tatg_branch_analysis_timeout_seconds=branch_analysis_timeout_seconds,
        tatg_generation_timeout_seconds=generation_timeout_seconds,
        memory_dir=(
            Path(
                str(
                    getattr(args, "memory_dir", "")
                    or getattr(args, "import_library_dir", "")
                    or ""
                )
            ).resolve()
            if str(
                getattr(args, "memory_dir", "")
                or getattr(args, "import_library_dir", "")
                or ""
            ).strip()
            else None
        ),
    )

    setattr(request, "live_run_id", uuid.uuid4().hex[:12])

    if request.memory_dir:
        os.environ["TATG_MEMORY_DIR"] = str(request.memory_dir)
        if str(getattr(args, "import_library_dir", "") or "").strip():
            os.environ["TATG_IMPORT_LIBRARY_DIR"] = str(request.memory_dir)

    sootup_jar = getattr(args, "sootup_jar", None)
    if sootup_jar:
        os.environ["SOOTUP_CG_JAR"] = str(Path(sootup_jar).resolve())
        # Reset the default registry so it picks up the new env var.
        import tatg.analysis.registry as _cg_reg
        _cg_reg._default_registry = None

    return request


def _salvage_replay_source_file(report: dict[str, Any], row: dict[str, Any]) -> Path | None:
    for value in (row.get("target_label"), row.get("label"), report.get("target_file")):
        text = str(value or "").strip()
        if "::" in text:
            text = text.split("::", 1)[0]
        if text:
            path = Path(text)
            if path.exists():
                return path.resolve()
    for row_target in list(report.get("targets") or []):
        match = re.search(r"source_file=PosixPath\('([^']+)'\)", str(row_target))
        if match:
            path = Path(match.group(1))
            if path.exists():
                return path.resolve()
    return None


def _salvage_replay_class_method(
    report: dict[str, Any],
    row: dict[str, Any],
    source_file: Path | None,
) -> tuple[str, str]:
    class_name = str(report.get("class_name") or "").strip()
    method_name = str(report.get("method_name") or "").strip()
    target_label = str(row.get("target_label") or row.get("label") or "").strip()
    parts = [part for part in target_label.split("::") if part]
    if len(parts) >= 3:
        class_name = class_name or parts[-2]
        method_name = method_name or parts[-1].split("#", 1)[0]
    elif len(parts) >= 2:
        method_name = method_name or parts[-1].split("#", 1)[0]
    if not class_name and source_file is not None:
        class_name = source_file.stem
    return class_name, method_name


def _salvage_replay_candidate_test_file(
    report: dict[str, Any],
    project_root: Path,
) -> tuple[Path | None, dict[str, str | None]]:
    snapshots: dict[str, str | None] = {}
    candidates: list[Any] = list(report.get("candidate_test_files") or [])
    final_validation = report.get("final_validation")
    if isinstance(final_validation, dict):
        candidates.extend(list(final_validation.get("candidate_test_files") or []))
    first_path: Path | None = None
    for entry in candidates:
        path_text = ""
        content: str | None = None
        if isinstance(entry, dict):
            path_text = str(entry.get("path") or entry.get("test_file") or "")
            if isinstance(entry.get("content"), str):
                content = str(entry.get("content") or "")
        else:
            path_text = str(entry or "")
        if not path_text:
            continue
        path = Path(path_text).resolve()
        if first_path is None and path.suffix == ".java":
            first_path = path
        if content is None:
            try:
                content = path.read_text(encoding="utf-8", errors="ignore")
            except OSError:
                content = None
        snapshots[str(path)] = content
    return first_path, snapshots


def _salvage_replay_candidate_code(row: dict[str, Any]) -> tuple[str, bool, str]:
    replay_code = str(row.get("candidate_code_replay") or "")
    replay_truncated = bool(row.get("candidate_code_replay_truncated")) or _looks_truncated_for_replay(replay_code)
    if replay_code.strip():
        return replay_code, replay_truncated, "candidate_code_replay"
    excerpt = str(row.get("candidate_code_excerpt") or "")
    if excerpt.strip():
        return excerpt, True, "candidate_code_excerpt_only"
    failed_excerpt = str(row.get("failed_test_source_excerpt") or "")
    if failed_excerpt.strip():
        return failed_excerpt, True, "failed_test_source_excerpt_only"
    return "", False, "missing_candidate_code"


def _salvage_replay_extract_method_excerpt(code: str, method_name: str) -> str:
    source = str(code or "")
    name = str(method_name or "").strip()
    if not source.strip() or not name:
        return ""
    match = re.search(rf"\b{re.escape(name)}\s*\(", source)
    if not match:
        return ""
    signature_start = source.rfind("\n", 0, match.start()) + 1
    brace = source.find("{", match.end())
    if brace < 0:
        return source[signature_start: min(len(source), match.end() + 1600)].strip()
    depth = 0
    in_string = False
    escaped = False
    for pos in range(brace, len(source)):
        ch = source[pos]
        if in_string:
            if escaped:
                escaped = False
            elif ch == "\\":
                escaped = True
            elif ch == '"':
                in_string = False
            continue
        if ch == '"':
            in_string = True
        elif ch == "{":
            depth += 1
        elif ch == "}":
            depth -= 1
            if depth == 0:
                return source[signature_start:pos + 1].strip()
    return source[signature_start:].strip()


def _salvage_replay_rows(report: dict[str, Any], *, max_candidates: int) -> list[dict[str, Any]]:
    policy = report.get("validation_policy")
    if not isinstance(policy, dict):
        policy = {}
    rows: list[dict[str, Any]] = []
    seen: set[tuple[str, str, str]] = set()
    for source_rows in (
        policy.get("coverage_positive_failed_details"),
        policy.get("coverage_positive_repair_submitted_details"),
        report.get("coverage_positive_failed_details"),
        report.get("candidate_coverage_audit_details"),
        report.get("high_coverage_candidate_audit_details"),
    ):
        for raw in list(source_rows or []):
            if not isinstance(raw, dict):
                continue
            status_text = str(raw.get("status") or "").strip().lower()
            promotion_status = str(raw.get("promotion_status") or "").strip().lower()
            if status_text == "passed" and promotion_status not in {"rejected", "not_promoted", "not_promoted_validation_failed"}:
                continue
            cov = raw.get("candidate_target_coverage")
            target_positive = _coverage_positive_candidate(cov) if isinstance(cov, dict) else (
                bool(raw.get("has_target_coverage")) or int(raw.get("line_covered") or 0) > 0
            )
            if not target_positive:
                continue
            key = (
                str(raw.get("target_label") or raw.get("label") or ""),
                str(raw.get("test_method") or ""),
                str(raw.get("failure_type") or raw.get("reason") or ""),
            )
            if key in seen:
                continue
            seen.add(key)
            rows.append(dict(raw))
            if len(rows) >= max(1, int(max_candidates or 1)):
                return rows
    return rows


def _salvage_replay_failure_output(row: dict[str, Any]) -> str:
    return "\n".join(
        str(row.get(key) or "")
        for key in ("failure_report_tail", "stdout_tail", "stderr_tail", "error", "reason")
    ).strip()


def _salvage_replay_diagnostic_present(row: dict[str, Any], failure_output: str) -> bool:
    text = "\n".join(
        str(row.get(key) or "")
        for key in (
            "failure_report_tail",
            "stdout_tail",
            "stderr_tail",
            "error",
            "reason",
            "failed_test_source_excerpt",
        )
    )
    text = "\n".join([text, str(failure_output or "")])
    return bool(
        re.search(r"\b(?:cannot find symbol|incompatible types|method .* cannot be applied|actual and formal argument lists differ|Compilation failure|\\[ERROR\\])\b", text, re.IGNORECASE)
        or extract_junit_expected_actual(text) is not None
        or re.search(r"\bat\s+[\w.$]+\.[\w$<>]+\([^)]+:\d+\)", text)
    )


def _repair_prompt_has_positive_coverage_exploration_wording(prompt: str) -> bool:
    for match in re.finditer(r"\b(improve coverage|explore new path|explore new scenario)\b", str(prompt or ""), re.IGNORECASE):
        prefix = str(prompt or "")[max(0, match.start() - 80):match.start()].lower()
        if "do not" in prefix or "no_coverage_exploration" in prefix or "forbidden" in prefix:
            continue
        return True
    return False


def _salvage_replay_payload(
    *,
    report: dict[str, Any],
    row: dict[str, Any],
    candidate_code: str,
    test_file: Path,
    source_file: Path | None,
) -> dict[str, Any]:
    class_name, method_name = _salvage_replay_class_method(report, row, source_file)
    payload: dict[str, Any] = {
        "status": "success",
        "test_file": str(test_file),
        "source_file": str(source_file) if source_file else "",
        "class_name": class_name,
        "method_name": method_name,
        "target_label": str(row.get("target_label") or row.get("label") or ""),
        "generated_code": candidate_code,
        "final_code": candidate_code,
        "streaming_test_method_name": row.get("test_method"),
        "test_name": row.get("test_method"),
        "candidate_role": row.get("candidate_role"),
        "objective_id": row.get("objective_id"),
        "coverage_obligation_id": row.get("coverage_obligation_id"),
        "baseline_skeleton_id": row.get("baseline_skeleton_id"),
        "skeleton_fact_ids": row.get("skeleton_fact_ids"),
        "input_family": row.get("input_family"),
        "oracle_type": row.get("oracle_type"),
        "repair_axis": row.get("repair_axis"),
        "tatg_baseline_skeleton_section": report.get("tatg_baseline_skeleton_section") or "",
        "tatg_baseline_skeletons": report.get("tatg_baseline_skeletons") or [],
        "tatg_generation_control_receipt": report.get("tatg_generation_control_receipt") or "",
        "tatg_target_receipt_contract": report.get("tatg_target_receipt_contract") or "",
    }
    return {key: value for key, value in payload.items() if value not in (None, "", [], {})}


def _salvage_replay_prompt_preview(
    *,
    request: GenerationRequest,
    project_root: Path,
    row: dict[str, Any],
    payload: dict[str, Any],
    candidate_code: str,
    source_file: Path | None,
    test_file: Path,
) -> dict[str, Any]:
    source_code = ""
    if source_file is not None:
        try:
            source_code = source_file.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            source_code = ""
    failure_output = _salvage_replay_failure_output(row)
    failure_signal = row.get("failure_signal") if isinstance(row.get("failure_signal"), dict) else {}
    if not failure_signal:
        failure_signal = _classify_validation_failure_feedback(failure_output) or {}
    if failure_signal and not str(failure_signal.get("category") or "").strip():
        failure_signal = dict(failure_signal)
        failure_signal["category"] = "uncertain_with_evidence"
    callable_surface_grounding = ""
    if source_file is not None:
        try:
            from tatg.analysis.api_surface import extract_surface, render_surface_anchor

            callable_surface_grounding = render_surface_anchor(
                extract_surface(source_file, str(payload.get("class_name") or source_file.stem))
            )
        except Exception:
            callable_surface_grounding = ""
    ctx = RepairContext(
        source_code=source_code,
        test_code=candidate_code,
        failure_output=failure_output,
        method_focus=str(row.get("test_method") or payload.get("method_name") or "") or None,
        java_version=request.java_version,
        junit_version=request.junit_version,
        junit_family=request.junit_family,
        extra={
            "target_label": row.get("target_label") or payload.get("target_label"),
            "test_file": str(test_file),
            "source_file": str(source_file) if source_file else "",
            "streaming_validation_failure": row,
            "streaming_failure_signal": failure_signal,
            "repair_failure_signals": extract_repair_failure_signals(failure_output),
            "production_method_focus": str(payload.get("method_name") or ""),
            "repair_test_method": str(row.get("test_method") or ""),
            "callback_signature_grounding": render_callback_signature_grounding_section(project_root, source_code),
            "callable_surface_grounding": callable_surface_grounding,
            "coverage_feedback": row.get("candidate_target_coverage") if isinstance(row.get("candidate_target_coverage"), dict) else {},
            "coverage_gate": row.get("coverage_gate") if isinstance(row.get("coverage_gate"), dict) else {},
            "baseline_skeleton_id": row.get("baseline_skeleton_id"),
            "skeleton_fact_ids": row.get("skeleton_fact_ids"),
            "baseline_skeleton_satisfaction": row.get("baseline_skeleton_satisfaction"),
            "repair_output_mode": "method_patch_json",
        },
    )
    strategy = LLMRepairStrategy(
        api_base=request.api_base or "",
        model=request.model,
        api_key_env=request.api_key_env or DEFAULT_API_KEY_ENV,
        timeout_seconds=max(1, int(request.llm_timeout_seconds or 1)),
    )
    system_prompt, user_prompt = strategy.build_prompt(ctx)
    failure_message = str(failure_signal.get("message") or "").strip()
    failed_excerpt = str(row.get("failed_test_source_excerpt") or "").strip()
    failed_statement = str((row.get("pre_target_failure") or {}).get("statement") or "") if isinstance(row.get("pre_target_failure"), dict) else ""
    failure_category = str(failure_signal.get("category") or "").strip()
    return {
        "system_prompt_chars": len(system_prompt),
        "user_prompt_chars": len(user_prompt),
        "prompt_audit": {
            "failure_category_resolved": bool(failure_category),
            "failure_category": failure_category or None,
            "diagnostic_present": _salvage_replay_diagnostic_present(row, failure_output),
            "high_priority_truncation_warnings": _prompt_high_priority_truncation_warnings(user_prompt),
            "contains_failure_message": bool(failure_message and failure_message in user_prompt),
            "contains_failed_test_excerpt": bool(failed_excerpt and failed_excerpt[:120] in user_prompt),
            "repair_prompt_has_original_test": "[Original Test To Preserve]" in user_prompt and bool(failed_excerpt and failed_excerpt[:80] in user_prompt),
            "repair_prompt_has_failed_statement": bool(failed_statement and failed_statement in user_prompt),
            "repair_prompt_has_candidate_coverage": "candidate_coverage:" in user_prompt or "candidate_target_coverage" in user_prompt,
            "contains_candidate_coverage": "line_covered" in user_prompt or "candidate_target_coverage" in user_prompt,
            "coverage_exploration_wording": _repair_prompt_has_positive_coverage_exploration_wording(user_prompt),
        },
        "system_prompt": system_prompt,
        "user_prompt": user_prompt,
    }


def _salvage_replay_command(args: argparse.Namespace) -> int:
    report_path = Path(str(getattr(args, "json_in", "") or "")).resolve()
    try:
        report = json.loads(report_path.read_text(encoding="utf-8"))
    except Exception as exc:
        print(f"Failed to read replay JSON: {exc}", file=sys.stderr)
        return 1
    if not isinstance(report, dict):
        print("Replay JSON must be an object report", file=sys.stderr)
        return 1
    project_root_text = str(getattr(args, "project_root", "") or report.get("project_root") or "")
    if not project_root_text:
        print("Replay JSON does not contain project_root; pass --project-root", file=sys.stderr)
        return 1
    project_root = Path(project_root_text).resolve()
    test_file, snapshots = _salvage_replay_candidate_test_file(report, project_root)
    if test_file is None:
        print("Replay JSON does not contain a candidate test file", file=sys.stderr)
        return 1
    if str(test_file) not in snapshots:
        try:
            snapshots[str(test_file)] = test_file.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            snapshots[str(test_file)] = None
    try:
        original_snapshot = snapshots.get(str(test_file))
        snapshots[str(test_file)] = _empty_java_test_class_skeleton(
            test_file,
            original_snapshot,
            junit_family=str(getattr(args, "junit_family", "") or report.get("junit_family") or ""),
        )
    except Exception:
        pass
    rows = _salvage_replay_rows(report, max_candidates=max(1, int(getattr(args, "max_candidates", 6) or 6)))
    test_commands = _normalize_test_commands(str(getattr(args, "test_command", "") or ""))
    if not test_commands:
        test_commands = [str(item) for item in list(report.get("test_commands") or []) if str(item or "").strip()]
    if not test_commands and report.get("test_command"):
        test_commands = [str(report.get("test_command") or "")]
    api_config = resolve_api_config(
        api_base=getattr(args, "api_base", "") or str(report.get("api_base") or ""),
        model=getattr(args, "model", "") or str(report.get("model") or ""),
        api_key_env=getattr(args, "api_key_env", "") or str(report.get("api_key_env") or DEFAULT_API_KEY_ENV),
    )
    apply_api_config_to_env(api_config)
    request = GenerationRequest(
        backend="tatg",
        scope=Scope.METHOD,
        project_root=project_root,
        target_file=None,
        class_name=None,
        method_name=None,
        model=api_config.model,
        api_base=api_config.api_base,
        api_key_env=api_config.api_key_env,
        test_command=test_commands[0] if test_commands else "",
        test_commands=test_commands,
        coverage_report_path=str(getattr(args, "coverage_report_path", "") or report.get("coverage_report_path") or ""),
        coverage_type=str(report.get("coverage_type") or "jacoco"),
        prompt_extra_text="",
        prompt_extra_file=None,
        prompt_insert=PromptInsertPosition.AFTER_USER,
        static_analysis_json=None,
        pass_specs=[],
        dry_run=False,
        max_iterations=1,
        cat_engine_root=project_root,
        method_engine_root=project_root,
        java_version=str(getattr(args, "java_version", "") or report.get("java_version") or ""),
        junit_version=str(getattr(args, "junit_version", "") or report.get("junit_version") or ""),
        junit_family=str(getattr(args, "junit_family", "") or report.get("junit_family") or ""),
        repair_iterations=max(1, int(getattr(args, "repair_iterations", 1) or 1)),
        llm_timeout_seconds=max(1, int(getattr(args, "llm_timeout_seconds", 120) or 120)),
        test_timeout_seconds=max(1, int(getattr(args, "test_timeout_seconds", 900) or 900)),
        e2e_timeout_seconds=0,
        parallel_targets=1,
        generation_parallelism=1,
        repair_parallelism=max(1, int(getattr(args, "repair_parallelism", 1) or 1)),
        validation_parallelism=max(1, int(getattr(args, "validation_parallelism", 4) or 4)),
        repair_mode="method",
        log_prompts=bool(getattr(args, "log_prompts", False)),
        log_prompts_limit=max(0, int(getattr(args, "log_prompts_limit", 20) or 20)),
    )
    request.live_run_id = uuid.uuid4().hex[:12]
    request.streaming_coverage_report_path = request.coverage_report_path
    output: dict[str, Any] = {
        "source_report": str(report_path),
        "live_run_id": request.live_run_id,
        "project_root": str(project_root),
        "test_file": str(test_file),
        "target_label": rows[0].get("target_label") if rows else None,
        "mode": "prompt_only" if bool(getattr(args, "prompt_only", False)) else "repair_and_validate",
        "isolated_test_file_snapshot": True,
        "candidate_count": len(rows),
        "submitted_count": 0,
        "passed_count": 0,
        "target_positive_passed_count": 0,
        "skipped_count": 0,
        "candidates": [],
    }
    for index, row in enumerate(rows, start=1):
        source_file = _salvage_replay_source_file(report, row)
        candidate_code, code_truncated, code_source = _salvage_replay_candidate_code(row)
        replay_row = dict(row)
        if not str(replay_row.get("failed_test_source_excerpt") or "").strip() and candidate_code.strip():
            method_excerpt = ""
            test_method_name = str(replay_row.get("test_method") or "").strip()
            if test_method_name:
                method_excerpt = _salvage_replay_extract_method_excerpt(candidate_code, test_method_name) or ""
            replay_row["failed_test_source_excerpt"] = _compact_feedback_text(
                method_excerpt or candidate_code,
                max_chars=2200,
                omitted_label="salvage replay original test",
            )
        payload = _salvage_replay_payload(
            report=report,
            row=replay_row,
            candidate_code=candidate_code,
            test_file=test_file,
            source_file=source_file,
        )
        candidate_report: dict[str, Any] = {
            "index": index,
            "label": replay_row.get("label"),
            "target_label": replay_row.get("target_label"),
            "test_method": replay_row.get("test_method"),
            "candidate_role": replay_row.get("candidate_role"),
            "failure_category": (
                (replay_row.get("failure_signal") or {}).get("category")
                if isinstance(replay_row.get("failure_signal"), dict)
                else None
            ) or "uncertain_with_evidence",
            "candidate_coverage_before": replay_row.get("candidate_target_coverage"),
            "candidate_code_source": code_source,
            "candidate_code_truncated": bool(code_truncated),
            "has_full_candidate_code": bool(candidate_code.strip() and not code_truncated),
        }
        try:
            preview = _salvage_replay_prompt_preview(
                request=request,
                project_root=project_root,
                row=replay_row,
                payload=payload,
                candidate_code=candidate_code,
                source_file=source_file,
                test_file=test_file,
            )
            candidate_report["prompt_audit"] = preview.get("prompt_audit")
            candidate_report["repair_prompt_built"] = True
            if bool(getattr(args, "include_prompts", False)):
                candidate_report["repair_prompt"] = {
                    "system": preview.get("system_prompt"),
                    "user": preview.get("user_prompt"),
                }
        except Exception as exc:
            candidate_report["prompt_audit_error"] = str(exc)
            candidate_report["repair_prompt_built"] = False
        if bool(getattr(args, "prompt_only", False)):
            candidate_report["status"] = "skipped"
            candidate_report["reason"] = "prompt_only"
            output["skipped_count"] += 1
            output["candidates"].append(candidate_report)
            continue
        if code_truncated or not candidate_code.strip() or "@Test" not in candidate_code:
            candidate_report["status"] = "skipped"
            candidate_report["reason"] = "candidate_code_replay_unavailable_or_truncated"
            output["skipped_count"] += 1
            output["candidates"].append(candidate_report)
            continue
        if not test_commands:
            candidate_report["status"] = "skipped"
            candidate_report["reason"] = "missing_test_command"
            output["skipped_count"] += 1
            output["candidates"].append(candidate_report)
            continue
        result = SimpleNamespace(command=str(replay_row.get("label") or replay_row.get("target_label") or ""), return_code=0, payload=payload)
        output["submitted_count"] += 1
        repaired_item, _ = _repair_streaming_validation_candidate(
            request=request,
            project_root=project_root,
            candidate_test_files=[test_file],
            test_file_snapshots=snapshots,
            result=result,
            validation_failure=replay_row,
            test_commands=test_commands,
            timeout_seconds=request.test_timeout_seconds,
            llm_timeout_seconds=request.llm_timeout_seconds,
        )
        candidate_report["repair_status"] = repaired_item.get("status") if isinstance(repaired_item, dict) else None
        candidate_report["repair_reason"] = repaired_item.get("reason") if isinstance(repaired_item, dict) else None
        candidate_report["repair_item"] = repaired_item
        repair_usage = repaired_item.get("repair_usage") if isinstance(repaired_item, dict) else {}
        applied_rules = list(repair_usage.get("applied_rules") or []) if isinstance(repair_usage, dict) else []
        candidate_report["structural_patch_applied"] = bool(applied_rules)
        if applied_rules:
            candidate_report["structural_patch_rules"] = applied_rules[:12]
        infra_blocker = None
        if isinstance(repaired_item, dict):
            infra_blocker = repaired_item.get("validation_infra_blocker")
            if not infra_blocker:
                repair_text = "\n".join(
                    str(repaired_item.get(key) or "")
                    for key in ("failure_report_tail", "stdout_tail", "stderr_tail", "error")
                )
                infra_blocker = _validation_infra_blocker_from_output(repair_text)
        if isinstance(infra_blocker, dict) and infra_blocker:
            candidate_report["validation_infra_blocked"] = True
            candidate_report["validation_infra_blocker"] = infra_blocker
            candidate_report["replay_outcome"] = "validation_infra_blocked"
        elif isinstance(repaired_item, dict) and str(repaired_item.get("status") or "") == "passed":
            candidate_report["validation_infra_blocked"] = False
            candidate_report["replay_outcome"] = "target_positive_repaired" if _target_positive_candidate_coverage(
                repaired_item.get("candidate_target_coverage"),
                repaired_item.get("coverage_gate") if isinstance(repaired_item.get("coverage_gate"), dict) else None,
            ) else "repair_passed_no_target"
        elif applied_rules:
            candidate_report["validation_infra_blocked"] = False
            candidate_report["replay_outcome"] = "structural_patch_applied_then_failed_semantically"
        else:
            candidate_report["validation_infra_blocked"] = False
            candidate_report["replay_outcome"] = "repair_failed_semantically"
        if isinstance(repaired_item, dict) and str(repaired_item.get("status") or "") == "passed":
            output["passed_count"] += 1
            if _target_positive_candidate_coverage(
                repaired_item.get("candidate_target_coverage"),
                repaired_item.get("coverage_gate") if isinstance(repaired_item.get("coverage_gate"), dict) else None,
            ):
                output["target_positive_passed_count"] += 1
        output["candidates"].append(candidate_report)
    if bool(getattr(args, "log_prompts", False)):
        output["prompt_logs"] = list(getattr(request, "prompt_logs", []) or [])
    output_path = str(getattr(args, "json_out", "") or "").strip()
    if output_path:
        _safe_write_json(Path(output_path), output)
        print(f"Salvage replay report saved to: {output_path}", file=sys.stderr)
    if bool(getattr(args, "print_json", False)) or not output_path:
        print(json.dumps(output, ensure_ascii=True, indent=2))
    return 0


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="tatg",
        description=(
            "TATG: target-aware LLM test generation for Java with "
            "method/class/singlemodule/multimodule scopes, validation, repair, "
            "coverage and mutation evaluation"
        ),
    )
    sub = parser.add_subparsers(dest="command", required=True)

    gen = sub.add_parser("generate", help="Run test generation")
    gen.add_argument(
        "--config-file",
        default="",
        help=(
            "Optional JSON config file. If omitted, auto-loads one of: "
            ".tatg.generate.json, tatg.generate.json, .tatg.json, tatg.json"
        ),
    )
    gen.add_argument(
        "--backend",
        choices=["tatg"],
        default="tatg",
        help=(
            "Generation backend (only 'tatg' is available). "
            "For class/module scopes, method targets are auto-expanded when no method is specified."
        ),
    )
    gen.add_argument(
        "--scope",
        choices=["method", "class", "singlemodule", "multimodule"],
        default="",
        help="Target scope: method | class | singlemodule | multimodule",
    )
    gen.add_argument("--project-root", default="")
    gen.add_argument("--module-path", help="Optional module root under project-root (multi-module support)")
    gen.add_argument("--target-file")
    gen.add_argument("--class-name")
    gen.add_argument(
        "--method-name",
        help=(
            "Primary method name for method scope. Optional when --filter-methods is provided. "
            "If both are set, --method-name must be included in --filter-methods."
        ),
    )

    gen.add_argument("--model", default="", help="Model id. Defaults to MODEL from shell environment.")
    gen.add_argument("--api-base", default="", help="OpenAI-compatible API base URL. Defaults to API_BASE from shell environment.")
    gen.add_argument("--api-key-env", default=DEFAULT_API_KEY_ENV, help="Environment variable containing the API key.")
    gen.add_argument(
        "--skip-api-preflight",
        action="store_true",
        help="Skip startup API environment/connectivity validation.",
    )
    gen.add_argument(
        "--skip-sootup-preflight",
        action="store_true",
        help="Skip SootUp JAR/Java/smoke-test connectivity check at startup.",
    )

    gen.add_argument(
        "--test-command",
        default="",
        help=(
            "Test command. Supports a single command or a JSON array string for multiple commands, "
            "e.g. '[\"mvn -pl common test\", \"mvn -pl spot test\"]'. "
            "Auto-detected if omitted."
        ),
    )
    gen.add_argument(
        "--test-command-map",
        default="{}",
        metavar="JSON",
        help=(
            'JSON object mapping module paths (relative to --project-root) to test commands. '
            'Each value can be a single command or a JSON array of commands. '
            'Example: \'{"module-a": ["mvn -pl module-a test", "mvn -pl module-a -Dtest=Foo test"], '
            '"module-b": "gradle :module-b:test"}\'. '
            'Falls back to --test-command when no entry matches.'
        ),
    )
    gen.add_argument("--build-system", choices=["maven", "gradle", "bazel", "python", "direct_java"], help="Build system (auto-detected if omitted)")
    gen.add_argument("--java-version", default="", help="Java language level to target in generated tests (e.g. 8, 11, 17)")
    gen.add_argument("--junit-version", default="", help="JUnit version to target in generated tests (e.g. 4.13.2, 5.10.2)")
    gen.add_argument(
        "--match-project-versions",
        action="store_true",
        default=True,
        help="Auto-detect Java/JUnit versions from project config when not explicitly provided (default: enabled)",
    )
    gen.add_argument(
        "--no-match-project-versions",
        dest="match_project_versions",
        action="store_false",
        help="Disable auto-detection of Java/JUnit versions from project config",
    )
    gen.add_argument("--coverage-report-path", default="")
    gen.add_argument("--coverage-type", default="jacoco")
    gen.add_argument(
        "--target-descriptor",
        default="",
        help=(
            "Exact JVM descriptor for method-scope overloaded targets, e.g. "
            "'(Ljava/lang/String;)V'. Also exported as TATG_TARGET_DESCRIPTOR."
        ),
    )
    gen.add_argument("--max-iterations", type=int, default=6)
    gen.add_argument("--repair-iterations", type=int, default=1, help="Repair passes after each failed test run")
    gen.add_argument(
        "--streaming-repair-mode",
        choices=["deferred", "eager"],
        default="deferred",
        help=(
            "How streaming validation schedules repair. 'deferred' streams "
            "generation+validation and repairs failed candidates after generation "
            "finishes, avoiding LLM contention. 'eager' repairs each failed "
            "candidate immediately, overlapping repair with generation."
        ),
    )
    gen.add_argument(
        "--skip-skeleton-verify",
        action="store_true",
        help=(
            "Skip the one-shot test-command verification that runs after "
            "seeding missing test class skeletons. By default, after creating "
            "an empty test class file, the configured test command is rerun "
            "once to ensure the skeleton compiles. Use this flag to bypass "
            "the gate when the cost is unacceptable (NOT recommended for "
            "large projects where per-method retries would amplify failures)."
        ),
    )
    gen.add_argument(
        "--no-pre-generate-teardown",
        dest="pre_generate_teardown",
        action="store_false",
        help=(
            "Disable the teardown pre-generation stage. By default a "
            "heuristic source scan decides which target classes likely need "
            "@AfterEach/@After cleanup; for each match the LLM generates ONE "
            "teardown method, patches it into the seeded skeleton, and "
            "verifies that the project test command still passes. On "
            "verification failure the teardown is rolled back and per-method "
            "generation proceeds without teardown."
        ),
    )
    gen.set_defaults(pre_generate_teardown=True)
    gen.add_argument(
        "--log-unrepaired-tests",
        dest="log_unrepaired_tests",
        action="store_true",
        default=False,
        help=(
            "After all repair iterations, parse the final test-runner output and "
            "record each still-failing test method name under 'unrepaired_tests' "
            "in the JSON report.  Off by default."
        ),
    )
    gen.add_argument(
        "--log-prompts",
        dest="log_prompts",
        action="store_true",
        default=False,
        help=(
            "Record bounded generation/repair prompt samples in the JSON report "
            "under 'prompt_logs' (default: first 20 prompts, clipped)."
        ),
    )
    gen.add_argument(
        "--log-prompts-limit",
        type=int,
        default=20,
        help="Maximum number of prompt samples to record when --log-prompts is set (default: 20).",
    )
    gen.add_argument(
        "--tatg-preanalysis-timeout-seconds",
        type=int,
        default=int(os.environ.get("TATG_PREANALYSIS_TIMEOUT_SECONDS", "180") or "180"),
        help=(
            "Wide per-target timeout for TATG static/type preanalysis run before formal generation. "
            "Use 0 to disable preanalysis prewarm and compute context during generation."
        ),
    )
    gen.add_argument(
        "--tatg-branch-analysis-timeout-seconds",
        type=int,
        default=int(os.environ.get("TATG_BRANCH_ANALYSIS_TIMEOUT_SECONDS", "600") or "600"),
        help=(
            "Timeout for the separate TATG semantic branch/state analysis call used in "
            "low-coverage feedback rounds. Slow local LM Studio models may need 600-900 seconds."
        ),
    )
    gen.add_argument(
        "--tatg-generation-timeout-seconds",
        type=int,
        default=int(os.environ.get("TATG_GENERATION_TIMEOUT_SECONDS", "0") or "0"),
        help=(
            "Per-target hard timeout budget surfaced by batch/live observability. "
            "Use 0 to disable the generate-level budget."
        ),
    )
    gen.add_argument(
        "--memory-dir",
        default=os.environ.get(
            "TATG_MEMORY_DIR",
            str(Path(tempfile.gettempdir()) / "tatg-memory"),
        ),
        help=(
            "Directory for persistent TATG memory files such as Java import libraries. "
            "Defaults to TATG_MEMORY_DIR or a tatg-memory directory "
            "under the platform temporary directory."
        ),
    )
    gen.add_argument(
        "--import-library-dir",
        default=os.environ.get("TATG_IMPORT_LIBRARY_DIR", ""),
        help=argparse.SUPPRESS,
    )
    gen.add_argument(
        "--repair-mode",
        choices=["class", "method"],
        default=None,
        help=(
            "Repair granularity hint (kept for compatibility). "
            "Generate now always uses class-level repair with per-test acceptance validation for all scopes."
        ),
    )
    gen.add_argument(
        "--with-mutation",
        action="store_true",
        help=(
            "Also run PITest's mutationCoverage goal (Maven/Gradle only) so that "
            "test_runs[].methods_coverage entries are populated with mutation_score. "
            "Slow — opt in for end-to-end runs only."
        ),
    )
    gen.add_argument(
        "--mutation-extra-iterations",
        type=int,
        default=int(os.environ.get("TATG_MUTATION_EXTRA_ITERATIONS", "1") or "1"),
        help=(
            "Run this many mutation-focused generation rounds after the regular "
            "coverage-first loop. Each round first tries PITest feedback and "
            "uses the normal repair-iterations value. Default: 1."
        ),
    )
    gen.add_argument(
        "--no-mutation-extra-round",
        dest="mutation_extra_iterations",
        action="store_const",
        const=0,
        help="Disable the default final mutation-focused generation round.",
    )
    gen.add_argument(
        "--retain-existing-tests",
        action="store_true",
        default=os.environ.get("TATG_RETAIN_EXISTING_TESTS", "0").strip().lower()
        in {"1", "true", "yes", "on"},
        help=(
            "Keep existing target test file content as generation context. "
            "Default is disabled so generation starts from zero retained tests."
        ),
    )
    gen.add_argument("--llm-timeout-seconds", type=int, default=120, help="Timeout for each LLM call (generation/repair)")
    gen.add_argument("--test-timeout-seconds", type=int, default=900, help="Timeout for each test command execution")
    gen.add_argument("--e2e-timeout-seconds", type=int, default=0, help="Overall timeout for generate->test->repair workflow (0 = no limit)")

    gen.add_argument("--prompt-extra-text", default="")
    gen.add_argument("--prompt-extra-file")
    gen.add_argument(
        "--prompt-insert",
        choices=["before_system", "after_system", "before_user", "after_user"],
        default="after_user",
    )
    gen.add_argument("--static-analysis-json", help="Static analysis JSON input for built-in CAT pass")
    gen.add_argument(
        "--pass-spec",
        action="append",
        default=[],
        help="Custom pass spec: '<module_or_file.py>:<ClassOrFactory>'",
    )

    gen.add_argument(
        "--cat-engine-root",
        default="",
        help="Reserved for backward compatibility (not required by native engine)",
    )
    gen.add_argument(
        "--method-engine-root",
        default="",
        help="Reserved for backward compatibility (not required by native engine)",
    )
    gen.add_argument(
        "--sootup-jar",
        default="",
        metavar="PATH",
        help=(
            "Path to the sootup-callgraph-pathfinder fat-JAR. "
            "When set, the live call-graph analyzer uses this JAR instead of "
            "the auto-resolved one. Takes precedence over the SOOTUP_CG_JAR "
            "environment variable."
        ),
    )

    gen.add_argument("--dry-run", action="store_true")
    gen.add_argument("--json-out", default="")
    gen.add_argument(
        "--print-json",
        action="store_true",
        help="Also print final JSON payload to stdout (disabled by default).",
    )
    gen.add_argument(
        "--no-progress",
        action="store_true",
        help="Suppress the live progress panel on stderr (always off when stderr is not a TTY).",
    )
    gen.add_argument(
        "--preflight-only",
        action="store_true",
        help="Run test-command preflight checks and exit before generation or repair work.",
    )
    gen.add_argument(
        "--parallel-targets",
        type=int,
        default=1,
        metavar="N",
        help=(
            "Backward-compatible alias for --generation-parallelism (default: 1). "
            "Controls concurrent model generation calls across targets."
        ),
    )
    gen.add_argument(
        "--generation-parallelism",
        type=int,
        default=None,
        metavar="N",
        help="Concurrent model generation calls across targets (default: --parallel-targets, usually 1).",
    )
    gen.add_argument(
        "--repair-parallelism",
        type=int,
        default=1,
        metavar="N",
        help="Concurrent model repair calls (default: 1).",
    )
    gen.add_argument(
        "--validation-parallelism",
        type=int,
        default=4,
        metavar="N",
        help="Concurrent sandbox validations for generated/repaired test methods (default: 4).",
    )
    gen.add_argument(
        "--filter-classes",
        action="append",
        default=[],
        metavar="CLASS[,CLASS...]",
        help=(
            "Restrict generation to these class names (comma-separated or repeated). "
            "Works with all scopes: only targets whose class_name matches are emitted."
        ),
    )
    gen.add_argument(
        "--filter-methods",
        action="append",
        default=[],
        metavar="METHOD[,METHOD...]",
        help=(
            "Restrict method-scope generation to these method names "
            "(comma-separated or repeated). When provided, --method-name is optional."
        ),
    )
    gen.add_argument(
        "--filter-modules",
        action="append",
        default=[],
        metavar="MODULE[,MODULE...]",
        help=(
            "Restrict multimodule generation to these module path suffixes "
            "(comma-separated or repeated)."
        ),
    )

    eval = sub.add_parser("evaluate", help="Evaluate generated tests (coverage + mutation)")
    eval.add_argument("--project-root", required=True, help="Project root directory")
    eval.add_argument("--coverage-report-path", default="", help="Path to coverage report (auto-detected if omitted)")
    eval.add_argument("--coverage-type", choices=["jacoco", "pytest"], default="jacoco")
    eval.add_argument("--mutation-json-path", default="", help="Path to PITest mutations.json")
    eval.add_argument("--mutation-log-path", default="", help="Path to PITest log file")
    eval.add_argument("--run-coverage-if-missing", action="store_true", help="Run native coverage command if report is missing")
    eval.add_argument("--run-mutation-if-missing", action="store_true", help="Run native mutation command if report is missing")
    eval.add_argument("--test-count", type=int, default=0, help="Number of generated tests")
    eval.add_argument("--json-out", default="", help="Output evaluation report as JSON")

    replay = sub.add_parser(
        "salvage-replay",
        help="Replay coverage-positive failed candidates from a live JSON report through repair/validation",
    )
    replay.add_argument("--json-in", required=True, help="Live TATG JSON report to inspect")
    replay.add_argument("--json-out", default="", help="Write replay diagnostics to JSON")
    replay.add_argument("--project-root", default="", help="Override project_root from the report")
    replay.add_argument("--test-command", default="", help="Override test command from the report")
    replay.add_argument("--coverage-report-path", default="", help="Override JaCoCo report path")
    replay.add_argument("--java-version", default="", help="Override Java version")
    replay.add_argument("--junit-version", default="", help="Override JUnit version")
    replay.add_argument("--junit-family", default="", help="Override JUnit family")
    replay.add_argument("--model", default="", help="Model id. Defaults to report/env")
    replay.add_argument("--api-base", default="", help="OpenAI-compatible API base URL. Defaults to report/env")
    replay.add_argument("--api-key-env", default=DEFAULT_API_KEY_ENV, help="Environment variable containing the API key")
    replay.add_argument("--max-candidates", type=int, default=6, help="Maximum coverage-positive failed candidates to replay")
    replay.add_argument("--repair-iterations", type=int, default=1, help="Repair attempts per replayed candidate")
    replay.add_argument("--llm-timeout-seconds", type=int, default=120, help="Timeout for each replay repair LLM call")
    replay.add_argument("--test-timeout-seconds", type=int, default=900, help="Timeout for each replay validation command")
    replay.add_argument("--repair-parallelism", type=int, default=1, help="Reserved for consistency with generate")
    replay.add_argument("--validation-parallelism", type=int, default=4, help="Sandbox validation workers")
    replay.add_argument(
        "--prompt-only",
        action="store_true",
        help="Build/audit repair prompts but do not call the LLM or run validation",
    )
    replay.add_argument(
        "--include-prompts",
        action="store_true",
        help="Include full repair prompts in the replay JSON report",
    )
    replay.add_argument("--log-prompts", action="store_true", help="Collect prompt log entries during replay")
    replay.add_argument("--log-prompts-limit", type=int, default=20)
    replay.add_argument("--print-json", action="store_true", help="Print replay JSON to stdout")

    cfg = sub.add_parser("config", help="Manage TATG configuration files")
    cfg_sub = cfg.add_subparsers(dest="config_command", required=True)

    cfg_init = cfg_sub.add_parser("init", help="Create a generate-config JSON template")
    cfg_init.add_argument(
        "--output",
        default=".tatg.generate.json",
        help="Path of generated config file (default: .tatg.generate.json)",
    )
    cfg_init.add_argument("--minimal", action="store_true", help="Generate a minimal starter template")
    cfg_init.add_argument("--force", action="store_true", help="Overwrite existing file")

    return parser


def main() -> int:
    parser = build_parser()
    args = parser.parse_args()

    if args.command == "config":
        if args.config_command == "init":
            return _config_init_command(args)
        parser.error("Unsupported config command")
        return 1
    elif args.command == "evaluate":
        return _evaluate_command(args)
    elif args.command == "salvage-replay":
        return _salvage_replay_command(args)
    elif args.command == "generate":
        try:
            args = _load_generate_config(args, sys.argv[1:])
        except Exception as exc:
            print(f"Config error: {exc}", file=sys.stderr)
            return 1
        return _generate_command(args)
    else:
        parser.error("Unsupported command")
        return 1


def _generate_command(args: argparse.Namespace) -> int:
    setup_started = time.perf_counter()
    e2e_started = setup_started
    e2e_timed_out = False
    try:
        request = _build_request(args)
    except Exception as exc:
        print(f"Argument error: {exc}", file=sys.stderr)
        return 1
    request.parallel_targets = max(1, int(getattr(request, "parallel_targets", 1) or 1))
    request.generation_parallelism = max(
        1,
        int(getattr(request, "generation_parallelism", request.parallel_targets) or request.parallel_targets),
    )
    request.repair_parallelism = max(1, int(getattr(request, "repair_parallelism", 1) or 1))
    request.validation_parallelism = max(1, int(getattr(request, "validation_parallelism", 4) or 4))
    request.prompt_iteration = max(1, int(getattr(request, "prompt_iteration", 1) or 1))
    request_has_api_config = all(
        hasattr(request, field)
        for field in ("api_base", "model", "api_key_env")
    )
    if (
        (not request.dry_run)
        and request_has_api_config
        and (not bool(getattr(args, "skip_api_preflight", False)))
    ):
        try:
            preflight_api_config(
                resolve_api_config(
                    api_base=getattr(request, "api_base", None),
                    model=getattr(request, "model", None),
                    api_key_env=getattr(request, "api_key_env", None),
                ),
                timeout_seconds=min(15, max(5, int(getattr(request, "llm_timeout_seconds", 30)))),
            )
        except Exception as exc:
            print(f"API configuration error: {exc}", file=sys.stderr)
            return 1
    # SootUp preflight: runs when static analysis is configured and not explicitly skipped.
    # Failure is a warning (not a hard error) since SootUp is optional enrichment.
    _sootup_jar_arg = getattr(args, "sootup_jar", None)
    _sootup_configured = bool(_sootup_jar_arg or os.environ.get("SOOTUP_CG_JAR"))
    if (
        not request.dry_run
        and _sootup_configured
        and not bool(getattr(args, "skip_sootup_preflight", False))
    ):
        _sootup_ok = _run_sootup_preflight(
            jar_path=_sootup_jar_arg,
            java_exe=str(os.environ.get("SOOTUP_JAVA", "") or "java"),
            require_ok=bool(_sootup_jar_arg),  # hard fail only when user explicitly configured JAR
        )
        if not _sootup_ok and bool(_sootup_jar_arg):
            return 1
    try:
        targets = resolve_targets(request)
    except TargetResolutionError as exc:
        print(f"Target resolution error: {exc}", file=sys.stderr)
        return 1
    if (
        not getattr(args, "repair_mode", None)
        and targets
        and all(getattr(t, "method_name", None) for t in targets)
    ):
        request.repair_mode = "method"

    # Initial generation must start from zero measured feedback.  Feedback is
    # populated only after iter1 validation and scoped to generation rounds 2+.
    request.generation_coverage_feedback_by_label = {}
    request.streaming_baseline_methods_coverage = None
    request.streaming_coverage_report_path = None
    stage_events: list[dict[str, Any]] = []

    def _record_stage_event(stage: str, **extra: Any) -> None:
        event = {
            "stage": str(stage),
            "at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
            "elapsed_since_setup_seconds": round(time.perf_counter() - setup_started, 3),
        }
        event.update({str(k): v for k, v in extra.items()})
        stage_events.append(event)

    def _write_early_generate_partial_checkpoint(stage: str, **extra: Any) -> None:
        json_out_text = str(getattr(args, "json_out", "") or "").strip()
        if not json_out_text:
            return
        _record_stage_event(stage, **extra)
        partial_path = Path(json_out_text + ".partial")
        payload = {
            "status": "running",
            "stage": stage,
            "updated_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
            "backend": request.backend,
            "scope": request.scope.value,
            "project_root": str(request.project_root) if request.project_root else None,
            "target_count": len(targets),
            "timeout_config": {
                "preanalysis_timeout_seconds": int(getattr(request, "tatg_preanalysis_timeout_seconds", 0) or 0),
                "generation_worker_timeout_seconds": int(getattr(request, "tatg_generation_timeout_seconds", 0) or 0),
                "llm_timeout_seconds": int(getattr(request, "llm_timeout_seconds", 0) or 0),
                "test_timeout_seconds": int(getattr(request, "test_timeout_seconds", 0) or 0),
                "e2e_timeout_seconds": int(getattr(request, "e2e_timeout_seconds", 0) or 0),
            },
            "stage_events": list(stage_events),
        }
        try:
            partial_path.parent.mkdir(parents=True, exist_ok=True)
            _safe_write_json(partial_path, payload)
        except Exception:
            pass

    # Keep the true pre-run contents separate from the empty working baseline
    # used by structural generation.  Historically the snapshot was captured
    # after the early skeleton reset, so a preflight/generation failure could
    # "roll back" a user's existing test file to an empty class.
    pre_run_test_file_snapshots: dict[str, str | None] = {}

    def _capture_pre_run_test_files(paths: Sequence[Path]) -> None:
        missing = [
            Path(path).resolve()
            for path in paths
            if str(Path(path).resolve()) not in pre_run_test_file_snapshots
        ]
        if missing:
            pre_run_test_file_snapshots.update(_snapshot_test_files(missing))

    def _restore_pre_run_test_files() -> None:
        if pre_run_test_file_snapshots:
            _restore_test_file_snapshots(pre_run_test_file_snapshots)

    early_candidate_test_files: list[Path] = []
    if not request.dry_run:
        _write_early_generate_partial_checkpoint("early_candidate_test_skeleton_reset_start")
        early_candidate_test_files = _collect_target_test_files([], targets)
        _capture_pre_run_test_files(early_candidate_test_files)
        if early_candidate_test_files and not bool(getattr(request, "retain_existing_tests", False)):
            _reset_test_files_to_empty_skeletons(
                early_candidate_test_files,
                junit_family=getattr(request, "junit_family", None),
            )
        _write_early_generate_partial_checkpoint(
            "early_candidate_test_skeleton_reset_done",
            candidate_test_file_count=len(early_candidate_test_files),
        )

    preflight_commands = _collect_test_commands_for_run(request, targets)
    if (not request.dry_run) and (not preflight_commands):
        print(
            "No usable test command found (inference failed or not provided). "
            "Pass --test-command explicitly, configure --test-command-map, "
            "or adjust --scope/--target so command inference can resolve.",
            file=sys.stderr,
        )
        _restore_pre_run_test_files()
        return 1

    if (not request.dry_run) and preflight_commands:
        preflight_result = _invoke_run_project_tests(
            request.project_root,
            preflight_commands,
            request.test_timeout_seconds,
            java_version=getattr(request, "java_version", None),
        )
        if preflight_result["return_code"] != 0:
            _log_test_command_failure(preflight_result)
            _restore_pre_run_test_files()
            return 1
        if getattr(args, "preflight_only", False):
            _log_test_command_success(preflight_result)
            _restore_pre_run_test_files()
            return 0

    pass_list: list[PromptPass] = []
    pass_list.append(StatefulProtocolTargetPass())
    additional_text = _read_optional_text(request.prompt_extra_text, request.prompt_extra_file)
    if additional_text:
        pass_list.append(AdditionalPromptPass(additional_text, request.prompt_insert))
    if request.static_analysis_json:
        pass_list.append(CATPass(request.static_analysis_json))
    pass_list.extend(_load_custom_passes(request.pass_specs))
    pipeline = PromptPipeline(pass_list)

    _write_early_generate_partial_checkpoint("base_prompt_pipeline_start")
    prompts: dict[str, PromptBundle] = {}
    for target in targets:
        base = _build_base_prompt(target)
        prompts[target.label] = pipeline.run(base, request, target)
    _write_early_generate_partial_checkpoint("base_prompt_pipeline_done", prompt_count=len(prompts))

    # ------------------------------------------------------------------
    # Teardown pre-generation stage (best-effort, gated by:
    #   - not dry_run
    #   - request.pre_generate_teardown (CLI flag, default on)
    #   - method scope (we only enable for the strict per-method validation
    #     path right now; class/file scope wiring will follow)
    #   - at least one preflight test command available so we can verify the
    #     generated teardown actually compiles+runs
    # ------------------------------------------------------------------
    mutation_extra_only_from_existing_tests = (
        _is_mutation_extra_only_from_existing_tests(request)
    )
    teardown_by_file: dict[str, str] = {}
    if _should_run_pre_generate_teardown(request, preflight_commands):
        try:
            _write_early_generate_partial_checkpoint("teardown_pre_generation_start")
            teardown_by_file = _pre_generate_teardown_stage(
                request,
                targets,
                effective_test_commands=preflight_commands,
                args=args,
            )
            _write_early_generate_partial_checkpoint(
                "teardown_pre_generation_done",
                verified_teardown_count=len(teardown_by_file),
            )
        except Exception as exc:  # safety net: teardown stage must never abort the run
            print(
                f"[teardown] Pre-generation stage crashed; continuing without "
                f"teardown context. Reason: {exc}",
                file=sys.stderr,
            )
            teardown_by_file = {}
            _write_early_generate_partial_checkpoint(
                "teardown_pre_generation_error",
                reason=str(exc),
            )
        if teardown_by_file:
            teardown_by_file = _filter_existing_teardown_by_file(teardown_by_file)
            _inject_teardown_context_into_prompts(prompts, targets, teardown_by_file)

    try:
        _write_early_generate_partial_checkpoint("tatg_preanalysis_start")
        tatg_preanalysis_stats = _prewarm_tatg_preanalysis(request, targets, progress=None)
        _write_early_generate_partial_checkpoint(
            "tatg_preanalysis_done",
            tatg_preanalysis=tatg_preanalysis_stats,
        )
    except Exception as exc:  # noqa: BLE001
        tatg_preanalysis_stats = {
            "enabled": str(getattr(request, "backend", "")).lower() == "tatg",
            "status": "error",
            "reason": str(exc),
        }
        _write_early_generate_partial_checkpoint("tatg_preanalysis_error", reason=str(exc))
    request.tatg_preanalysis_stats = tatg_preanalysis_stats

    if mutation_extra_only_from_existing_tests:
        tatg_initial_branch_analysis_stats = {
            "enabled": False,
            "status": "skipped",
            "reason": "mutation_extra_only_from_existing_tests",
        }
        request.tatg_initial_branch_analysis_by_label = {}
        request.tatg_initial_branch_analysis_stats = tatg_initial_branch_analysis_stats
        _write_early_generate_partial_checkpoint(
            "tatg_initial_branch_analysis_skipped",
            tatg_initial_branch_analysis=tatg_initial_branch_analysis_stats,
        )
    else:
        try:
            _write_early_generate_partial_checkpoint("tatg_initial_branch_analysis_start")
            tatg_initial_branch_analysis_stats = _prepare_initial_llm_branch_analysis(
                request,
                targets,
            )
            _write_early_generate_partial_checkpoint(
                "tatg_initial_branch_analysis_done",
                tatg_initial_branch_analysis=tatg_initial_branch_analysis_stats,
            )
        except Exception as exc:  # noqa: BLE001
            tatg_initial_branch_analysis_stats = {
                "enabled": str(getattr(request, "backend", "")).lower() == "tatg",
                "status": "error",
                "reason": f"{type(exc).__name__}:{exc}",
            }
            request.tatg_initial_branch_analysis_by_label = {}
            request.tatg_initial_branch_analysis_stats = tatg_initial_branch_analysis_stats
            _write_early_generate_partial_checkpoint(
                "tatg_initial_branch_analysis_error",
                reason=f"{type(exc).__name__}:{exc}",
            )

    # Formal e2e timing starts after preflight, prompt setup, teardown pre-generation,
    # bounded TATG preanalysis, and initial semantic branch analysis. These
    # analysis phases have their own timeout/stat blocks.
    e2e_started = time.perf_counter()

    backend = get_backend(request.backend)
    _write_early_generate_partial_checkpoint("backend_build_commands_start")
    commands = backend.build_commands(request, targets, prompts)
    _write_early_generate_partial_checkpoint("backend_build_commands_done", commands_count=len(commands))

    validation_policy = {
        "enabled": not request.dry_run,
        "unit": "test_method_with_lifecycle",
        "per_test_validation": False,
        "streaming_validation": False,
        "generation_timeout_count": 0,
        "generation_timeout_labels": [],
        "generation_timeout_details": [],
        "timeout_config": {
            "preanalysis_timeout_seconds": int(getattr(request, "tatg_preanalysis_timeout_seconds", 0) or 0),
            "generation_worker_timeout_seconds": int(getattr(request, "tatg_generation_timeout_seconds", 0) or 0),
            "llm_timeout_seconds": int(getattr(request, "llm_timeout_seconds", 0) or 0),
            "streaming_validation_method_timeout_seconds": int(
                os.getenv("TATG_STREAMING_VALIDATION_METHOD_TIMEOUT_SECONDS", "300") or "300"
            ),
            "streaming_validation_high_budget_timeout_seconds": int(
                os.getenv("TATG_STREAMING_VALIDATION_HIGH_BUDGET_TIMEOUT_SECONDS", "180") or "180"
            ),
            "test_timeout_seconds": int(getattr(request, "test_timeout_seconds", 0) or 0),
            "e2e_timeout_seconds": int(getattr(request, "e2e_timeout_seconds", 0) or 0),
        },
        "stage_events": stage_events,
        "streaming_validation_submitted": 0,
        "streaming_validation_completed": 0,
        "streaming_validation_passed": 0,
        "streaming_validation_failed": 0,
        "streaming_validation_skipped": 0,
        "streaming_validation_candidate_extraction_empty": 0,
        "streaming_validation_duplicate_behavior_rejected": 0,
        "mutation_candidate_duplicates_existing_tests_count": 0,
        "mutation_candidate_duplicates_existing_tests_details": [],
        "streaming_validation_llm_empty_response": 0,
        "streaming_validation_extraction_skipped_backend": None,
        "streaming_validation_errors": 0,
        "streaming_validation_repair_submitted": 0,
        "streaming_validation_repair_completed": 0,
        "streaming_validation_repair_passed": 0,
        "streaming_validation_repair_failed": 0,
        "streaming_validation_repair_errors": 0,
        "streaming_validation_repair_skipped": 0,
        "repair_passed_target_positive_count": 0,
        "repair_passed_no_target_count": 0,
        "streaming_validation_repair_e2e_timed_out": False,
        "streaming_validation_late_results_ignored": 0,
        "streaming_validation_passed_details": [],
        "streaming_validation_failed_details": [],
        "streaming_validation_skipped_details": [],
        "streaming_candidate_coverage_audit_details": [],
        "streaming_validation_static_failure_details": [],
        "streaming_validation_failure_type_counts": {},
        "streaming_validation_coverage_gate_reason_counts": {},
        "streaming_validation_applied_details": [],
        "streaming_validation_elapsed_seconds": 0.0,
        "streaming_validation_written_files": 0,
        "streaming_validation_applied_candidates": 0,
        "streaming_validation_apply_skipped": 0,
        "streaming_validation_candidate_coverage_measured": 0,
        "streaming_validation_candidate_target_covered": 0,
        "streaming_validation_candidate_closes_baseline_gap": 0,
        "coverage_positive_failed_count": 0,
        "coverage_positive_failed_details": [],
        "validation_infra_blocker_count": 0,
        "validation_infra_blocker_details": [],
        "coverage_positive_repair_eligible": 0,
        "coverage_positive_repair_submitted": 0,
        "coverage_positive_repair_submitted_details": [],
        "coverage_positive_repair_passed": 0,
        "coverage_positive_repair_passed_details": [],
        "coverage_positive_repair_regression_count": 0,
        "coverage_positive_repair_regression_details": [],
        "candidate_role_integrity_failed": 0,
        "candidate_role_integrity_failed_details": [],
        "role_unverified_after_repair_count": 0,
        "role_unverified_after_repair_details": [],
        "repair_destroyed_deep_role_semantics": 0,
        "repair_destroyed_deep_role_semantics_details": [],
        "repair_mutation_oracle_promotion_rejected": 0,
        "repair_mutation_oracle_promotion_rejected_details": [],
        "repair_weakened_mutation_oracle_count": 0,
        "semantic_replay_objective_satisfied_count": 0,
        "semantic_replay_objective_missed_count": 0,
        "semantic_replay_objective_unsatisfied_after_repair": 0,
        "semantic_replay_objective_missed_details": [],
        "streaming_validation_static_failures": 0,
        "static_failure_repair_cap": 0,
        "static_failure_repair_submitted": 0,
        "static_failure_repair_skipped": 0,
        "streaming_validation_target_coverage_gate_mode": _target_coverage_gate_mode(),
        "streaming_validation_target_coverage_gate_rejected": 0,
        "streaming_validation_target_coverage_gate_unavailable_allowed": 0,
        "streaming_validation_coverage_unavailable_retained": 0,
        "streaming_validation_axis_stats": {},
        "validated_tests": 0,
        "rolled_back": False,
        "rolled_back_writes": 0,
        "restored_files": 0,
        "deleted_new_files": 0,
        "restore_skipped": 0,
        "rollback_baseline_updates": 0,
        "compile_isolation_probes": 0,
        "compile_isolation_promoted": 0,
        "rollback_snapshot_kind": "pre_run",
        "round_baseline_updates": 0,
    }
    if mutation_extra_only_from_existing_tests:
        validation_policy["mutation_extra_only_from_existing_tests"] = True
        validation_policy["structural_generation_skipped_reason"] = (
            "max_iterations_zero_with_retained_tests_and_mutation_extra"
        )
    candidate_test_files: list[Path] = []
    test_file_snapshots: dict[str, str | None] = {}
    initial_existing_test_names_by_file: dict[str, set[str]] = {}
    initial_existing_test_count = 0
    if not request.dry_run:
        candidate_by_path = {str(p.resolve()): p.resolve() for p in early_candidate_test_files}
        for path in _collect_target_test_files(commands, targets):
            candidate_by_path[str(path.resolve())] = path.resolve()
        candidate_test_files = list(candidate_by_path.values())
        _capture_pre_run_test_files(candidate_test_files)
        if candidate_test_files and not bool(getattr(request, "retain_existing_tests", False)):
            teardown_paths = {str(Path(p).resolve()) for p in (teardown_by_file or {}).keys()}
            reset_candidate_files = [
                path for path in candidate_test_files if str(path.resolve()) not in teardown_paths
            ]
            _record_stage_event(
                "candidate_test_skeleton_reset_start",
                candidate_test_file_count=len(candidate_test_files),
                reset_candidate_test_file_count=len(reset_candidate_files),
                preserved_teardown_file_count=len(candidate_test_files) - len(reset_candidate_files),
            )
            _reset_test_files_to_empty_skeletons(
                reset_candidate_files,
                junit_family=getattr(request, "junit_family", None),
            )
            _record_stage_event(
                "candidate_test_skeleton_reset_done",
                candidate_test_file_count=len(candidate_test_files),
                reset_candidate_test_file_count=len(reset_candidate_files),
                preserved_teardown_file_count=len(candidate_test_files) - len(reset_candidate_files),
            )
        test_file_snapshots = _snapshot_test_files(candidate_test_files)
        initial_existing_test_names_by_file = {
            str(path.resolve()): _at_test_method_names_in_text(
                test_file_snapshots.get(str(path.resolve())) or ""
            )
            for path in candidate_test_files
        }
        initial_existing_test_count = sum(
            len(names) for names in initial_existing_test_names_by_file.values()
        )
        validation_policy["existing_test_count"] = initial_existing_test_count
        request.mutation_candidate_test_files = [str(p.resolve()) for p in candidate_test_files]

    if targets and all(getattr(t, "method_name", None) for t in targets):
        _unit_label = "method"
    else:
        _unit_label = _SCOPE_TO_UNIT_LABEL.get(str(request.scope.value).lower(), "target")
    progress = ProgressDisplay(
        total_targets=len(targets),
        max_iterations=max(1, int(request.max_iterations)),
        repair_iterations=max(1, int(request.repair_iterations)),
        worker_count=max(1, int(request.generation_parallelism)),
        unit_label=_unit_label,
        java_version=request.java_version,
        junit_version=request.junit_version,
        junit_family=request.junit_family,
        enabled=not getattr(args, "no_progress", False),
    )
    progress.register_targets([t.label for t in targets])

    effective_test_commands = _collect_test_commands_for_run(request, targets)
    iterative_test_commands = _build_iterative_test_commands(
        effective_test_commands,
        candidate_test_files,
        scope=request.scope,
    )
    test_command_enabled = bool(effective_test_commands)
    validation_policy["per_test_validation"] = (not request.dry_run) and test_command_enabled

    results: list = []
    artifacts: list[dict] = []
    repair_candidates: list[dict] = []
    test_runs: list[dict] = []
    _cov_line: float | None = None
    _cov_branch: float | None = None
    _methods_cov: list[dict[str, Any]] | None = None
    current: dict | None = None
    outcome: dict | None = None
    best_test_file_snapshots: dict[str, str | None] = dict(test_file_snapshots)
    best_failed_test_count: int = 10**9
    best_return_code: int = 1
    best_total_test_methods: int = -1
    best_partial_test_file_snapshots: dict[str, str | None] = dict(test_file_snapshots)
    best_partial_total_test_methods: int = -1
    best_live_coverage_snapshots: dict[str, str | None] = {}
    best_live_coverage_score: float = -1.0
    best_live_coverage_line: float | None = None
    best_live_coverage_branch: float | None = None
    best_live_coverage_total_methods: int = -1
    last_per_method_validation_failures: dict[str, set[str]] = {}
    last_per_method_validation_summary: dict[str, Any] = {}
    compile_isolation_events: list[dict[str, Any]] = []
    method_probe_workers = max(1, int(getattr(request, "validation_parallelism", 4) or 4))
    validation_policy["per_method_probe_workers"] = method_probe_workers
    validation_policy["model_generation_workers"] = max(1, int(getattr(request, "generation_parallelism", request.parallel_targets) or 1))
    validation_policy["model_repair_workers"] = max(1, int(getattr(request, "repair_parallelism", 1) or 1))
    validation_policy["per_method_probe_sandboxes"] = 0
    validation_policy["per_method_probe_sandbox_files"] = 0
    validation_policy["per_method_probe_sandboxes_cleaned"] = 0

    json_out_path = _resolve_generate_json_out_path(args, request)
    partial_json_out_path = Path(json_out_path + ".partial")
    prompt_sidecar_path = Path(json_out_path + ".prompts.jsonl")
    request.prompt_sidecar_path = prompt_sidecar_path
    request.prompt_sidecar_flushed_count = 0
    if bool(getattr(request, "log_prompts", False)):
        try:
            prompt_sidecar_path.parent.mkdir(parents=True, exist_ok=True)
            prompt_sidecar_path.write_text("", encoding="utf-8")
        except Exception:
            pass
    checkpoint_lock = threading.Lock()
    prompt_sidecar_offset = 0

    def _flush_prompt_sidecar() -> None:
        nonlocal prompt_sidecar_offset
        if not bool(getattr(request, "log_prompts", False)):
            return
        prompt_sidecar_offset = max(
            prompt_sidecar_offset,
            int(getattr(request, "prompt_sidecar_flushed_count", 0) or 0),
        )
        logs = list(getattr(request, "prompt_logs", []) or [])
        if prompt_sidecar_offset >= len(logs):
            return
        rows: list[dict[str, Any]] = []
        for idx in range(prompt_sidecar_offset, len(logs)):
            entry = logs[idx]
            row = dict(entry) if isinstance(entry, dict) else {"value": str(entry)}
            row["index"] = idx
            try:
                prompt_text = "\n".join(
                    str(row.get(key) or "") for key in ("system_prompt", "user_prompt")
                )
                label_text = str(row.get("label") or row.get("target_label") or "")
                contaminating: list[str] = []
                for tgt in targets:
                    t_label = str(getattr(tgt, "label", "") or "")
                    if t_label and t_label in label_text:
                        continue
                    for token in (
                        str(getattr(tgt, "class_name", "") or "").strip(),
                        str(getattr(tgt, "method_name", "") or "").strip(),
                    ):
                        if token and token in prompt_text and token not in contaminating:
                            contaminating.append(token)
                if contaminating:
                    row["prompt_cross_target_contamination"] = contaminating[:8]
                    validation_policy.setdefault("prompt_cross_target_contamination", [])
                    validation_policy["prompt_cross_target_contamination"].append({
                        "prompt_index": idx,
                        "label": label_text,
                        "tokens": contaminating[:8],
                    })
                audit = row.get("prompt_audit") if isinstance(row.get("prompt_audit"), dict) else {}
                warnings = [
                    dict(item)
                    for item in list(audit.get("high_priority_truncation_warnings") or [])
                    if isinstance(item, dict)
                ]
                if warnings:
                    row["prompt_high_priority_truncation_warnings"] = warnings
                    validation_policy.setdefault("prompt_high_priority_truncation_warnings", [])
                    validation_policy["prompt_high_priority_truncation_warnings"].append({
                        "prompt_index": idx,
                        "phase": row.get("phase"),
                        "label": label_text,
                        "warnings": warnings[:8],
                    })
            except Exception:
                pass
            rows.append(row)
        written = _append_jsonl_rows(prompt_sidecar_path, rows)
        prompt_sidecar_offset += written

    def _write_generate_partial_checkpoint(stage: str) -> None:
        _record_stage_event(stage)
        with checkpoint_lock:
            state = "completed" if str(stage).strip().lower() == "completed" else "running"
            payload = {
                "status": state,
                "stage": stage,
                "updated_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
                "backend": request.backend,
                "scope": request.scope.value,
                "project_root": str(request.project_root) if request.project_root else None,
                "e2e_timeout_seconds": request.e2e_timeout_seconds,
                "e2e_timed_out": e2e_timed_out,
                "e2e_seconds": round(time.perf_counter() - e2e_started, 3),
                "pre_e2e_seconds": round(e2e_started - setup_started, 3),
                "tatg_preanalysis": dict(getattr(request, "tatg_preanalysis_stats", {}) or {}),
                "tatg_initial_branch_analysis": dict(
                    getattr(request, "tatg_initial_branch_analysis_stats", {}) or {}
                ),
                "tatg_branch_analysis": dict(getattr(request, "tatg_branch_analysis_stats", {}) or {}),
                "timeout_config": {
                    "preanalysis_timeout_seconds": int(getattr(request, "tatg_preanalysis_timeout_seconds", 0) or 0),
                    "branch_analysis_timeout_seconds": int(
                        getattr(request, "tatg_branch_analysis_timeout_seconds", 0) or 0
                    ),
                    "generation_worker_timeout_seconds": int(getattr(request, "tatg_generation_timeout_seconds", 0) or 0),
                    "llm_timeout_seconds": int(getattr(request, "llm_timeout_seconds", 0) or 0),
                    "streaming_validation_method_timeout_seconds": int(
                        os.getenv("TATG_STREAMING_VALIDATION_METHOD_TIMEOUT_SECONDS", "300") or "300"
                    ),
                    "streaming_validation_high_budget_timeout_seconds": int(
                        os.getenv("TATG_STREAMING_VALIDATION_HIGH_BUDGET_TIMEOUT_SECONDS", "180") or "180"
                    ),
                    "test_timeout_seconds": int(getattr(request, "test_timeout_seconds", 0) or 0),
                    "e2e_timeout_seconds": int(getattr(request, "e2e_timeout_seconds", 0) or 0),
                },
                "stage_events": list(stage_events),
                "target_count": len(targets),
                "commands_count": len(commands),
                "generated_test_count": _count_generated_tests(artifacts) if artifacts else 0,
                "return_codes": [int(getattr(r, "return_code", 1) or 1) for r in results],
                "test_runs": list(test_runs),
                "validation_policy": dict(validation_policy),
                "repair_candidates_count": len(repair_candidates),
                "repair_events_count": len(repair_events) if 'repair_events' in locals() else 0,
                "prompt_logs_count": len(list(getattr(request, "prompt_logs", []) or [])),
            }
            try:
                _safe_write_json(partial_json_out_path, payload)
            except Exception:
                pass
            try:
                _flush_prompt_sidecar()
            except Exception:
                pass

    _write_generate_partial_checkpoint("initialized")

    def _mark_e2e_timeout(stage: str) -> None:
        nonlocal e2e_timed_out
        if e2e_timed_out:
            return
        e2e_timed_out = True
        validation_policy["streaming_validation_repair_e2e_timed_out"] = True
        try:
            progress.write(f"[timeout] e2e timeout reached during {stage}; stopping remaining work")
        except Exception:
            pass
        _write_generate_partial_checkpoint(stage)

    def _bounded_test_timeout(stage: str, *, safety_margin: float = 0.0) -> int:
        remaining = _e2e_remaining_seconds(e2e_started, request.e2e_timeout_seconds)
        if remaining is None:
            return request.test_timeout_seconds
        if remaining <= safety_margin:
            _mark_e2e_timeout(stage)
            return 1
        return max(1, min(request.test_timeout_seconds, int(max(1.0, remaining - safety_margin))))

    def _probe_compile_isolation_and_promote() -> bool:
        """Mid-repair probe: capture the passing subset as `best`.

        Triggers in two scenarios:

          * ``failure_type == "compile"`` — the whole file fails to compile
            and no @Test method runs, but many methods in the file may
            already be syntactically valid and would pass if the still-
            broken ones were stripped.
          * ``failure_type == "test"`` — the file compiles and runs, but
            some @Test methods fail their assertions. The PASSING subset
            (the methods that ran cleanly) is exactly what we want to
            preserve, so we drop only the asserted-failing ones and check
            whether the remainder is fully green.

        Either way:
          1) snapshot the current candidate test files,
          2) drop only the methods identified as failing,
          3) re-run the test command,
          4) if the resulting state is fully green with ``@Test`` methods,
             promote the dropped-subset snapshot as ``best`` so it survives
             later regressions / final fallback,
          5) restore the original snapshot so the LLM repair loop can keep
             trying to fix the dropped methods in subsequent rounds.

        Returns True when a green subset was discovered and promoted.
        """
        nonlocal current, outcome, _cov_line, _cov_branch, _methods_cov
        nonlocal best_test_file_snapshots, best_failed_test_count
        nonlocal best_return_code, best_total_test_methods
        if request.dry_run or not test_command_enabled:
            return False
        if current is None or outcome is None:
            return False
        failure_type = str(outcome.get("failure_type") or "none")
        if failure_type not in ("compile", "test"):
            return False
        if failure_type != "compile" and int(outcome.get("failed_test_count", 0) or 0) <= 0:
            return False
        if not candidate_test_files:
            return False
        failure_output = (
            str(current.get("stdout", "") or "")
            + "\n"
            + str(current.get("stderr", "") or "")
        ).strip()
        failing_by_file: dict[str, set[str]] = {}
        for cand in repair_candidates:
            tf = str(cand.get("test_file") or "")
            if not tf:
                continue
            tf_path = Path(tf)
            methods = extract_failing_methods(failure_output, tf_path.stem)
            if not methods:
                methods = _extract_failing_methods_from_compile_output(
                    failure_output, tf_path,
                )
            if methods:
                failing_by_file.setdefault(tf, set()).update(
                    m for m in methods if m
                )
        if not failing_by_file:
            return False
        # Snapshot the full pre-probe state so we can restore afterwards.
        try:
            probe_pre_snapshot = _snapshot_test_files(candidate_test_files)
        except OSError:
            return False
        dropped_any = 0
        for tf, methods in failing_by_file.items():
            try:
                drop_res = _drop_failing_methods(Path(tf), sorted(methods))
                dropped_any += int(drop_res.get("removed_count", 0) or 0)
            except Exception:
                continue
        if dropped_any <= 0:
            # Nothing actually changed on disk; nothing to probe.
            return False
        # Re-test with the failing methods stripped.
        try:
            probe_current = _invoke_run_project_tests(
                request.project_root,
                effective_test_commands,
                _bounded_test_timeout("compile_isolation_probe_timeout"),
                java_version=getattr(request, "java_version", None),
            )
            probe_outcome = _parse_test_outcome(probe_current)
        except Exception:
            _restore_test_file_snapshots(probe_pre_snapshot)
            return False
        probe_rc_raw = probe_current.get("return_code", 1)
        probe_rc = int(probe_rc_raw if probe_rc_raw is not None else 1)
        probe_failed_raw = probe_outcome.get("failed_test_count", 10**9)
        probe_failed = int(probe_failed_raw if probe_failed_raw is not None else 10**9)
        probe_methods = _sum_at_test_methods_for_files(candidate_test_files)
        promoted = False
        if (
            probe_rc == 0
            and probe_failed == 0
            and probe_methods > max(best_total_test_methods, 0)
        ):
            saved_current = current
            saved_outcome = outcome
            saved_cov_line = _cov_line
            saved_cov_branch = _cov_branch
            saved_methods_cov = _methods_cov
            best_failed_test_count = 0
            best_return_code = 0
            best_total_test_methods = probe_methods
            best_test_file_snapshots = _snapshot_test_files(candidate_test_files)
            current = probe_current
            outcome = probe_outcome
            _cov_line, _cov_branch = _read_coverage(request)
            _methods_cov = _read_method_coverage(request)
            _promote_live_coverage_snapshot("compile_isolation_probe")
            current = saved_current
            outcome = saved_outcome
            _cov_line = saved_cov_line
            _cov_branch = saved_cov_branch
            _methods_cov = saved_methods_cov
            validation_policy["rollback_baseline_updates"] = int(
                validation_policy.get("rollback_baseline_updates", 0)
            ) + 1
            promoted = True
            try:
                progress.write(
                    f"[preserve] compile-isolation probe captured a green subset"
                    f" ({probe_methods} @Test method(s) pass after dropping"
                    f" {dropped_any} broken method(s)); promoted as best"
                )
            except Exception:
                pass
        compile_isolation_events.append({
            "dropped_methods": dropped_any,
            "probe_return_code": probe_rc,
            "probe_failed_test_count": probe_failed,
            "probe_test_methods": probe_methods,
            "promoted": promoted,
        })
        validation_policy["compile_isolation_probes"] = int(
            validation_policy.get("compile_isolation_probes", 0)
        ) + 1
        if promoted:
            validation_policy["compile_isolation_promoted"] = int(
                validation_policy.get("compile_isolation_promoted", 0)
            ) + 1
        # Restore the pre-probe state so repair can continue trying to fix
        # the methods we just dropped. The "best" snapshot we just captured
        # remains as a safety floor for later rollback.
        _restore_test_file_snapshots(probe_pre_snapshot)
        # Refresh current/outcome to reflect the restored on-disk state.
        # We deliberately do NOT re-run tests here — we already know the
        # state: it's the same as before the probe, which `current` /
        # `outcome` already describe correctly.
        return promoted

    def _per_method_isolation_probe_and_promote() -> bool:
        """Validate each ``@Test`` method one-by-one and keep only the passing ones.

        For every candidate test file, run a single-method filtered command for
        each ``@Test`` method. Methods that pass are retained; methods that fail
        are recorded for the repair queue and omitted from the kept union. The
        resulting kept union is written back to disk immediately so later repair
        rounds start from the verified subset instead of an all-or-nothing
        rollback baseline.

        Returns True when at least one method validated and the kept subset was
        written back to disk.
        """
        nonlocal current, outcome, _cov_line, _cov_branch, _methods_cov
        nonlocal best_test_file_snapshots, best_failed_test_count
        nonlocal best_return_code, best_total_test_methods
        nonlocal best_partial_test_file_snapshots, best_partial_total_test_methods
        nonlocal last_per_method_validation_failures, last_per_method_validation_summary
        nonlocal test_file_snapshots, e2e_timed_out

        if request.dry_run or not test_command_enabled:
            return False
        if _is_e2e_timed_out(e2e_started, request.e2e_timeout_seconds):
            _mark_e2e_timeout("per_method_probe_timeout_before_start")
            return False
        if not candidate_test_files:
            return False

        build_system = detect_build_system(request.project_root)
        default_test_commands = request.test_commands or ([request.test_command] if request.test_command else [])
        source_by_test_file: dict[str, Path] = {}
        for cand in repair_candidates:
            tf_text = str(cand.get("test_file") or "")
            sf_text = str(cand.get("source_file") or "")
            if tf_text and sf_text:
                try:
                    source_by_test_file[str(Path(tf_text).resolve())] = Path(sf_text)
                except Exception:
                    pass

        def _commands_for_test_file(tf: Path) -> list[str]:
            source_file = source_by_test_file.get(str(tf.resolve()))
            if source_file is not None and request.test_command_map:
                return _resolve_test_commands_for_source(
                    source_file=source_file,
                    project_root=request.project_root,
                    default_commands=default_test_commands,
                    test_command_map=request.test_command_map,
                )
            return effective_test_commands

        # Collect per-file method lists from the current on-disk state.
        per_file_methods: list[tuple[Path, list[str]]] = []
        original_source_by_file: dict[str, str] = {}
        existing_method_names_by_file: dict[str, set[str]] = {}
        targeted_method_names_by_file: dict[str, set[str]] = {}
        failed_per_file: dict[str, set[str]] = {}
        for cand in repair_candidates:
            tf_text = str(cand.get("test_file") or "")
            if not tf_text:
                continue
            try:
                tf_key = str(Path(tf_text).resolve())
            except Exception:
                continue
            for method_name in list(cand.get("failed_methods_hint") or []):
                if method_name:
                    targeted_method_names_by_file.setdefault(tf_key, set()).add(str(method_name))

        for tf in candidate_test_files:
            tf_key = str(tf.resolve())
            try:
                if not tf.exists():
                    continue
                src = tf.read_text(encoding="utf-8", errors="ignore")
            except Exception:
                continue
            current_names = _at_test_method_names_in_text(src)
            baseline_source = test_file_snapshots.get(tf_key)
            baseline_names = _at_test_method_names_in_text(baseline_source)
            existing_method_names_by_file[tf_key] = set(baseline_names)
            delta_names = current_names - baseline_names
            targeted_names = delta_names | targeted_method_names_by_file.get(tf_key, set())
            if targeted_names:
                names = sorted(n for n in targeted_names if n in current_names)
            else:
                names = sorted(current_names)
                if len(names) > 120:
                    failed_per_file.setdefault(tf_key, set()).update(names)
                    last_per_method_validation_summary = {
                        "tested_count": 0,
                        "validated_count": 0,
                        "failed_count": len(names),
                        "validated_per_file": {},
                        "failed_per_file": {tf_key: names},
                        "failed_support_per_file": {},
                        "failed_details": [
                            {
                                "test_file": tf_key,
                                "reason": "too_many_existing_methods_without_delta",
                                "method_count": len(names),
                            }
                        ],
                    }
                    return False
            if names:
                original_source_by_file[tf_key] = src
                per_file_methods.append((tf, names))
        if not per_file_methods:
            return False
        try:
            probe_pre_snapshot = _snapshot_test_files(candidate_test_files)
        except OSError:
            return False

        validated_per_file: dict[str, set[str]] = {}
        tested_count = 0

        # Isolation-first validation: execute each method with other @Test
        # methods removed from the same file, so one broken test does not
        # pollute pass/fail judgement for unrelated methods. When sandboxes are
        # available, jobs are partitioned by worker so methods from the same
        # class can be validated in parallel across isolated workspaces.
        method_jobs: list[dict[str, Any]] = []
        for tf, names in per_file_methods:
            tf_key = str(tf.resolve())
            try:
                full_src = original_source_by_file.get(tf_key)
                if full_src is None:
                    full_src = tf.read_text(encoding="utf-8", errors="ignore")
            except Exception:
                for m in names:
                    failed_per_file.setdefault(tf_key, set()).add(m)
                tested_count += len(names)
                continue

            rel_tf: str | None
            try:
                rel_tf = str(tf.resolve().relative_to(request.project_root.resolve()))
            except Exception:
                rel_tf = None

            for m in names:
                tested_count += 1
                test_filter = _isolated_method_test_filter_for_build_system(build_system, tf.stem, m)
                method_commands = _apply_test_filter_to_commands(
                    _commands_for_test_file(tf),
                    build_system,
                    test_filter,
                )
                if not method_commands:
                    failed_per_file.setdefault(tf_key, set()).add(m)
                    continue

                drop_others = [n for n in names if n != m]
                isolated_src = full_src
                if drop_others:
                    try:
                        isolated_src, _ = _drop_junit_test_methods_from_source(isolated_src, drop_others)
                    except Exception:
                        pass
                isolated_src = _strip_orphan_junit_annotations(isolated_src)
                try:
                    helper_ranges = _non_test_method_ranges(isolated_src)
                    if helper_ranges:
                        reachable = _helper_reachability(isolated_src, {m}, helper_ranges)
                        unreached = {
                            name
                            for (name, _s, _e) in helper_ranges
                            if name not in reachable
                        }
                        if unreached:
                            isolated_src = _drop_helpers_by_name(
                                isolated_src,
                                helper_ranges,
                                unreached,
                            )
                            isolated_src = _strip_orphan_junit_annotations(isolated_src)
                except Exception:
                    pass

                method_jobs.append({
                    "tf_key": tf_key,
                    "method_name": m,
                    "commands": method_commands,
                    "isolated_src": isolated_src,
                    "abs_test_file": str(tf.resolve()),
                    "rel_test_file": rel_tf,
                })

        def _run_method_job(job: dict[str, Any], sandbox_root: Path | None) -> tuple[str, str, bool, dict[str, Any]]:
            tf_key = str(job.get("tf_key") or "")
            method_name = str(job.get("method_name") or "")
            method_commands = list(job.get("commands") or [])
            isolated_src = str(job.get("isolated_src") or "")
            rel_test_file = job.get("rel_test_file")
            abs_test_file = str(job.get("abs_test_file") or "")
            detail: dict[str, Any] = {
                "test_file": abs_test_file,
                "method": method_name,
                "commands": method_commands,
            }
            if sandbox_root is None or not rel_test_file:
                detail["reason"] = "missing_sandbox"
                return tf_key, method_name, False, detail

            target_file = sandbox_root / str(rel_test_file)
            run_root = sandbox_root

            try:
                for other_tf in candidate_test_files:
                    try:
                        other_rel = other_tf.resolve().relative_to(request.project_root.resolve())
                    except Exception:
                        continue
                    other_target = sandbox_root / other_rel
                    if other_target.resolve() == target_file.resolve():
                        continue
                    if other_tf.suffix == ".java":
                        other_key = str(other_tf.resolve())
                        package_source = (
                            original_source_by_file.get(other_key)
                            or probe_pre_snapshot.get(other_key)
                            or test_file_snapshots.get(other_key)
                        )
                        other_target.parent.mkdir(parents=True, exist_ok=True)
                        other_target.write_text(
                            _empty_java_test_class_skeleton(
                                other_tf,
                                package_source,
                                junit_family=getattr(request, "junit_family", None),
                            ),
                            encoding="utf-8",
                        )
                    else:
                        try:
                            other_target.unlink()
                        except FileNotFoundError:
                            pass
                        except Exception:
                            pass
                target_file.parent.mkdir(parents=True, exist_ok=True)
                target_file.write_text(isolated_src, encoding="utf-8")
            except Exception:
                detail["reason"] = "write_failed"
                return tf_key, method_name, False, detail

            try:
                m_run = _invoke_run_project_tests(
                    run_root,
                    method_commands,
                    _bounded_test_timeout("per_method_probe_test_timeout"),
                    java_version=getattr(request, "java_version", None),
                )
                m_outcome = _parse_test_outcome(m_run)
            except Exception:
                detail["reason"] = "run_failed"
                return tf_key, method_name, False, detail

            rc_raw = m_run.get("return_code", 1)
            rc = int(rc_raw if rc_raw is not None else 1)
            failed_raw = m_outcome.get("failed_test_count", 10**9)
            failed = int(failed_raw if failed_raw is not None else 10**9)
            output_text = (
                str(m_run.get("stdout", "") or "")
                + "\n"
                + str(m_run.get("stderr", "") or "")
            )
            tests_run_match = re.search(r"Tests run:\s*(\d+)", output_text)
            tests_run = int(tests_run_match.group(1)) if tests_run_match else -1
            method_passed = rc == 0 and failed == 0 and (tests_run == -1 or tests_run >= 1)
            detail.update({
                "return_code": rc,
                "failed_test_count": failed,
                "tests_run": tests_run,
                "stdout_tail": str(m_run.get("stdout", "") or "")[-2000:],
                "stderr_tail": str(m_run.get("stderr", "") or "")[-2000:],
            })
            support_failures: list[str] = []
            try:
                support_failures = [
                    name
                    for name in _extract_failing_methods_from_compile_output(
                        output_text,
                        target_file,
                    )
                    if name and name != method_name
                ]
                if support_failures:
                    detail["failed_support_methods"] = sorted(set(support_failures))
            except Exception:
                pass
            if (not method_passed) and support_failures:
                lifecycle_names = {name for (name, _s, _e) in _junit_lifecycle_method_ranges(isolated_src)}
                lifecycle_drop = sorted({name for name in support_failures if name in lifecycle_names})
                if lifecycle_drop:
                    try:
                        retry_src = _drop_helpers_by_name(
                            isolated_src,
                            _junit_lifecycle_method_ranges(isolated_src),
                            set(lifecycle_drop),
                        )
                        retry_src = _strip_orphan_junit_annotations(retry_src)
                        if retry_src != isolated_src:
                            target_file.write_text(retry_src, encoding="utf-8")
                            retry_run = _invoke_run_project_tests(
                                run_root,
                                method_commands,
                                _bounded_test_timeout("per_method_probe_retry_timeout"),
                                java_version=getattr(request, "java_version", None),
                            )
                            retry_outcome = _parse_test_outcome(retry_run)
                            retry_rc_raw = retry_run.get("return_code", 1)
                            retry_rc = int(retry_rc_raw if retry_rc_raw is not None else 1)
                            retry_failed_raw = retry_outcome.get("failed_test_count", 10**9)
                            retry_failed = int(
                                retry_failed_raw if retry_failed_raw is not None else 10**9
                            )
                            retry_output_text = (
                                str(retry_run.get("stdout", "") or "")
                                + "\n"
                                + str(retry_run.get("stderr", "") or "")
                            )
                            retry_tests_run_match = re.search(r"Tests run:\s*(\d+)", retry_output_text)
                            retry_tests_run = (
                                int(retry_tests_run_match.group(1))
                                if retry_tests_run_match
                                else -1
                            )
                            retry_passed = (
                                retry_rc == 0
                                and retry_failed == 0
                                and (retry_tests_run == -1 or retry_tests_run >= 1)
                            )
                            detail["support_retry"] = {
                                "dropped_support_methods": lifecycle_drop,
                                "return_code": retry_rc,
                                "failed_test_count": retry_failed,
                                "tests_run": retry_tests_run,
                            }
                            if retry_passed:
                                method_passed = True
                                rc = retry_rc
                                failed = retry_failed
                                tests_run = retry_tests_run
                                detail.update({
                                    "return_code": rc,
                                    "failed_test_count": failed,
                                    "tests_run": tests_run,
                                    "stdout_tail": str(retry_run.get("stdout", "") or "")[-2000:],
                                    "stderr_tail": str(retry_run.get("stderr", "") or "")[-2000:],
                                    "dropped_support_methods": lifecycle_drop,
                                })
                    except Exception as exc:
                        detail["support_retry_error"] = str(exc)
            if not method_passed:
                if rc != 0:
                    detail["reason"] = "nonzero_return_code"
                elif failed != 0:
                    detail["reason"] = "failed_tests"
                elif tests_run == 0:
                    detail["reason"] = "zero_tests_run"
                else:
                    detail["reason"] = "not_passed"
            return tf_key, method_name, method_passed, detail

        method_results: list[tuple[str, str, bool, dict[str, Any]]] = []
        jobs_by_file: dict[str, list[dict[str, Any]]] = {}
        for job in method_jobs:
            jobs_by_file.setdefault(str(job.get("tf_key") or ""), []).append(job)

        if method_jobs:
            active_files = [tf_key for tf_key, jobs in jobs_by_file.items() if jobs]
            sandbox_counts: dict[str, int] = {tf_key: 1 for tf_key in active_files}
            if len(active_files) < method_probe_workers:
                remaining = method_probe_workers - len(active_files)
                while remaining > 0:
                    expanded = False
                    for tf_key in active_files:
                        if remaining <= 0:
                            break
                        if sandbox_counts[tf_key] < len(jobs_by_file.get(tf_key, [])):
                            sandbox_counts[tf_key] += 1
                            remaining -= 1
                            expanded = True
                    if not expanded:
                        break

            validation_policy["per_method_probe_sandbox_files"] = len(sandbox_counts)

            partition_specs: list[tuple[str, list[dict[str, Any]]]] = []
            for tf_key, jobs_for_file in jobs_by_file.items():
                partition_count = max(1, int(sandbox_counts.get(tf_key, 1) or 1))
                partitions: list[list[dict[str, Any]]] = [[] for _ in range(partition_count)]
                for idx, job in enumerate(jobs_for_file):
                    partitions[idx % partition_count].append(job)
                partition_specs.extend((tf_key, jobs) for jobs in partitions if jobs)

            def _sandbox_creation_failed_results(
                tf_key: str,
                jobs: list[dict[str, Any]],
            ) -> list[tuple[str, str, bool, dict[str, Any]]]:
                out: list[tuple[str, str, bool, dict[str, Any]]] = []
                for job in jobs:
                    method_name = str(job.get("method_name") or "")
                    out.append((
                        tf_key,
                        method_name,
                        False,
                        {
                            "test_file": str(job.get("abs_test_file") or ""),
                            "method": method_name,
                            "commands": list(job.get("commands") or []),
                            "reason": "sandbox_creation_failed",
                        },
                    ))
                return out

            def _run_partition_with_owned_sandbox(
                tf_key: str,
                jobs: list[dict[str, Any]],
            ) -> tuple[list[tuple[str, str, bool, dict[str, Any]]], int, int]:
                sandbox_map: dict[str, list[Path]] = {}
                try:
                    sandboxes = _create_method_probe_sandboxes(request.project_root, 1)
                    sandbox_map[tf_key] = sandboxes
                    sandbox_root = sandboxes[0]
                except Exception:
                    return _sandbox_creation_failed_results(tf_key, jobs), 0, 0
                out: list[tuple[str, str, bool, dict[str, Any]]] = []
                cleaned = 0
                try:
                    for _job in jobs:
                        try:
                            out.append(_run_method_job(_job, sandbox_root))
                        except Exception as exc:
                            method_name = str(_job.get("method_name") or "")
                            out.append((
                                tf_key,
                                method_name,
                                False,
                                {
                                    "test_file": str(_job.get("abs_test_file") or ""),
                                    "method": method_name,
                                    "commands": list(_job.get("commands") or []),
                                    "reason": "method_probe_exception",
                                    "error": str(exc),
                                },
                            ))
                finally:
                    cleaned = _cleanup_method_probe_sandboxes(sandbox_map)
                return out, 1, cleaned

            futures = []
            created_count = 0
            cleaned_count = 0
            executor = ThreadPoolExecutor(max_workers=max(1, method_probe_workers))
            try:
                futures.extend(
                    executor.submit(_run_partition_with_owned_sandbox, tf_key, jobs)
                    for tf_key, jobs in partition_specs
                )
                pending_probe_futures = set(futures)
                while pending_probe_futures:
                    if _is_e2e_timed_out(e2e_started, request.e2e_timeout_seconds):
                        for pending_future in pending_probe_futures:
                            pending_future.cancel()
                        _mark_e2e_timeout("per_method_probe_timeout")
                        break
                    remaining = _e2e_remaining_seconds(e2e_started, request.e2e_timeout_seconds)
                    wait_timeout = 1.0 if remaining is None else min(1.0, max(0.0, remaining))
                    done, pending_probe_futures = wait(
                        pending_probe_futures,
                        timeout=wait_timeout,
                        return_when=FIRST_COMPLETED,
                    )
                    if not done:
                        continue
                    for fut in done:
                        try:
                            partition_results, created, cleaned = fut.result()
                        except Exception:
                            continue
                        method_results.extend(partition_results)
                        created_count += int(created or 0)
                        cleaned_count += int(cleaned or 0)
            finally:
                executor.shutdown(wait=False, cancel_futures=True)
                validation_policy["per_method_probe_sandboxes"] = int(
                    validation_policy.get("per_method_probe_sandboxes", 0)
                ) + created_count
                if cleaned_count:
                    validation_policy["per_method_probe_sandboxes_cleaned"] = int(
                        validation_policy.get("per_method_probe_sandboxes_cleaned", 0)
                    ) + cleaned_count

        failed_details: list[dict[str, Any]] = []
        failed_support_per_file: dict[str, set[str]] = {}
        for tf_key, method_name, method_passed, detail in method_results:
            for support_name in detail.get("dropped_support_methods", []) or []:
                if support_name:
                    failed_support_per_file.setdefault(tf_key, set()).add(str(support_name))
            if method_passed:
                validated_per_file.setdefault(tf_key, set()).add(method_name)
            else:
                failed_per_file.setdefault(tf_key, set()).add(method_name)
                for support_name in detail.get("failed_support_methods", []) or []:
                    if support_name:
                        failed_support_per_file.setdefault(tf_key, set()).add(str(support_name))
                failed_details.append(detail)

        total_validated = sum(len(v) for v in validated_per_file.values())
        last_per_method_validation_failures = failed_per_file
        last_per_method_validation_summary = {
            "tested_count": tested_count,
            "validated_count": total_validated,
            "failed_count": sum(len(v) for v in failed_per_file.values()),
            "validated_per_file": {k: sorted(v) for k, v in validated_per_file.items()},
            "failed_per_file": {k: sorted(v) for k, v in failed_per_file.items()},
            "failed_support_per_file": {k: sorted(v) for k, v in failed_support_per_file.items()},
            "failed_details": failed_details[:20],
        }

        if total_validated == 0:
            _restore_test_file_snapshots(probe_pre_snapshot)
            compile_isolation_events.append({
                "kind": "per_method",
                "tested_methods": tested_count,
                "validated_methods": 0,
                "promoted": False,
            })
            validation_policy["per_method_probes"] = int(
                validation_policy.get("per_method_probes", 0)
            ) + 1
            return False

        helper_drops_per_file: dict[str, int] = {}
        for tf, names in per_file_methods:
            tf_key = str(tf.resolve())
            keep = validated_per_file.get(tf_key, set())
            drop = [n for n in names if n not in keep]
            existing_keep = existing_method_names_by_file.get(tf_key, set())
            try:
                full_src = original_source_by_file.get(tf_key)
                if full_src is None:
                    full_src = tf.read_text(encoding="utf-8", errors="ignore")
            except Exception:
                continue
            if not keep:
                reduced = _empty_java_test_class_skeleton(
                    tf,
                    full_src,
                    junit_family=getattr(request, "junit_family", None),
                )
                if reduced != full_src:
                    try:
                        tf.write_text(reduced, encoding="utf-8")
                    except Exception:
                        continue
                continue
            reduced = full_src
            if drop:
                try:
                    reduced, _ = _drop_junit_test_methods_from_source(reduced, drop)
                except Exception:
                    pass
            support_drop = failed_support_per_file.get(tf_key, set())
            if support_drop:
                lifecycle_ranges = _junit_lifecycle_method_ranges(reduced)
                reduced_next = _drop_helpers_by_name(reduced, lifecycle_ranges, support_drop)
                if reduced_next != reduced:
                    helper_drops_per_file[tf_key] = int(helper_drops_per_file.get(tf_key, 0)) + len(support_drop)
                    reduced = reduced_next
            try:
                helper_ranges = _non_test_method_ranges(reduced)
            except Exception:
                helper_ranges = []
            reachability_roots = set(keep) | set(existing_keep)
            if helper_ranges and reachability_roots:
                try:
                    reachable = _helper_reachability(reduced, reachability_roots, helper_ranges)
                    unreached = {name for (name, _s, _e) in helper_ranges if name not in reachable}
                    if unreached:
                        reduced = _drop_helpers_by_name(reduced, helper_ranges, unreached)
                        helper_drops_per_file[tf_key] = len(unreached)
                except Exception:
                    pass
            elif helper_ranges and not keep:
                try:
                    all_helper_names = {name for (name, _s, _e) in helper_ranges}
                    reduced = _drop_helpers_by_name(reduced, helper_ranges, all_helper_names)
                    helper_drops_per_file[tf_key] = len(all_helper_names)
                except Exception:
                    pass
            reduced = _strip_orphan_junit_annotations(reduced)
            if reduced != full_src:
                try:
                    tf.write_text(reduced, encoding="utf-8")
                except Exception:
                    continue

        best_partial_total_test_methods = _sum_at_test_methods_for_files(candidate_test_files)
        best_partial_test_file_snapshots = _snapshot_test_files(candidate_test_files)
        # Round-level rollback target: once a per-method validated subset is on
        # disk, make it the active rollback baseline for subsequent regressions.
        test_file_snapshots = dict(best_partial_test_file_snapshots)
        validation_policy["rollback_baseline_updates"] = int(
            validation_policy.get("rollback_baseline_updates", 0)
        ) + 1
        validation_policy["round_baseline_updates"] = int(
            validation_policy.get("round_baseline_updates", 0)
        ) + 1
        validation_policy["runnable_baseline_updates"] = int(
            validation_policy.get("runnable_baseline_updates", 0)
        ) + 1
        promoted = True
        try:
            progress.write(
                f"[preserve] per-method probe: validated {total_validated}/{tested_count} "
                f"@Test method(s) individually; dropped {sum(helper_drops_per_file.values())} "
                "unreachable helper(s); kept passing methods on disk"
            )
        except Exception:
            pass

        compile_isolation_events.append({
            "kind": "per_method",
            "tested_methods": tested_count,
            "validated_methods": total_validated,
            "promoted": promoted,
        })
        validation_policy["per_method_probes"] = int(
            validation_policy.get("per_method_probes", 0)
        ) + 1
        validation_policy["per_method_validated"] = int(
            validation_policy.get("per_method_validated", 0)
        ) + total_validated
        if promoted:
            validation_policy["per_method_promoted"] = int(
                validation_policy.get("per_method_promoted", 0)
            ) + 1
        return promoted

    def _live_coverage_score(
        methods_coverage: list[dict[str, Any]] | None,
        report_line_coverage: float | None,
        report_branch_coverage: float | None,
    ) -> tuple[float, float | None, float | None] | None:
        target_row = _target_method_coverage_row_for_request(request, methods_coverage)
        if target_row:
            try:
                line_covered = int(target_row.get("line_covered") or 0)
            except Exception:
                line_covered = 0
            try:
                branch_covered = int(target_row.get("branch_covered") or 0)
            except Exception:
                branch_covered = 0
            if line_covered <= 0 and branch_covered <= 0:
                return None
            line_value = target_row.get("line_coverage")
            branch_value = target_row.get("branch_coverage")
        else:
            target_name = str(getattr(request, "method_name", "") or "").strip()
            if target_name and methods_coverage is not None:
                return None
            line_value = report_line_coverage
            branch_value = report_branch_coverage
        if line_value is None and branch_value is None:
            return None
        try:
            line_score = float(line_value) if line_value is not None else 0.0
        except Exception:
            line_score = 0.0
            line_value = None
        try:
            branch_score = float(branch_value) if branch_value is not None else 0.0
        except Exception:
            branch_score = 0.0
            branch_value = None
        return line_score + branch_score, line_value, branch_value

    def _streaming_has_no_retained_green_candidates() -> bool:
        if not bool(validation_policy.get("streaming_validation")):
            return False
        submitted = int(validation_policy.get("streaming_validation_submitted", 0) or 0)
        if submitted <= 0:
            return False
        applied = int(validation_policy.get("streaming_validation_applied_candidates", 0) or 0)
        return applied <= 0

    def _discard_untrusted_zero_retained_streaming_coverage(stage: str) -> None:
        """Drop stale JaCoCo reads when no streaming candidate was retained.

        Candidate-level validation can leave report files behind even when every
        generated @Test failed or was rejected.  Such coverage is useful for
        candidate salvage, but it is not a green-suite baseline and must not
        drive snapshots or coverage-feedback rounds.
        """
        nonlocal _cov_line, _cov_branch, _methods_cov
        if not _streaming_has_no_retained_green_candidates():
            return
        if _cov_line is None and _cov_branch is None and not _methods_cov:
            return
        # A later local repair or final-suite validation can produce a green,
        # target-positive suite even when the earlier streaming promotion
        # counter remains zero. `_invoke_run_project_tests` deletes stale JaCoCo
        # artifacts before every validation command, so an exact target row
        # from that successful command is authoritative current-run evidence.
        _target_row = _target_method_coverage_row_for_request(request, _methods_cov)
        try:
            _current_green = (
                current is not None
                and outcome is not None
                and int(current.get("return_code", 1) or 0) == 0
                and int(outcome.get("failed_test_count", 1) or 0) == 0
                and _sum_at_test_methods_for_files(candidate_test_files) > 0
            )
        except Exception:
            _current_green = False
        if _current_green and _target_row and (
            int(_target_row.get("line_covered") or 0) > 0
            or int(_target_row.get("branch_covered") or 0) > 0
        ):
            validation_policy["streaming_zero_retained_green_target_coverage_preserved"] = True
            validation_policy["streaming_zero_retained_green_target_coverage_stage"] = stage
            validation_policy["best_snapshot_only"] = True
            return
        validation_policy["streaming_validation_zero_retained_coverage_discarded"] = True
        validation_policy["streaming_validation_zero_retained_coverage_discard_stage"] = stage
        validation_policy["streaming_validation_zero_retained_discarded_report_line_coverage"] = _cov_line
        validation_policy["streaming_validation_zero_retained_discarded_report_branch_coverage"] = _cov_branch
        if _target_row:
            validation_policy["streaming_validation_zero_retained_discarded_target_line_coverage"] = _target_row.get("line_coverage")
            validation_policy["streaming_validation_zero_retained_discarded_target_branch_coverage"] = _target_row.get("branch_coverage")
        _cov_line = None
        _cov_branch = None
        _methods_cov = None

    def _promote_live_coverage_snapshot(stage: str, *, allow_zero_retained: bool = False) -> None:
        """Keep the best fully-green coverage state observed in this live run."""
        nonlocal best_live_coverage_snapshots, best_live_coverage_score
        nonlocal best_live_coverage_line, best_live_coverage_branch
        nonlocal best_live_coverage_total_methods
        if request.dry_run or (not candidate_test_files):
            return
        if _streaming_has_no_retained_green_candidates() and not allow_zero_retained:
            validation_policy["live_best_coverage_snapshot_skip_reason"] = "zero_retained_streaming_candidates"
            return
        if current is None or outcome is None:
            return
        try:
            cur_failed = int(outcome.get("failed_test_count", 10**9))
            cur_rc = int(current.get("return_code", 1))
        except Exception:
            return
        if cur_failed != 0 or cur_rc != 0:
            return
        cur_total_methods = _sum_at_test_methods_for_files(candidate_test_files)
        if cur_total_methods <= 0:
            return
        scored = _live_coverage_score(_methods_cov, _cov_line, _cov_branch)
        if scored is None:
            return
        score, line_value, branch_value = scored
        improves = (
            score > best_live_coverage_score + 1e-12
            or (
                abs(score - best_live_coverage_score) <= 1e-12
                and cur_total_methods > best_live_coverage_total_methods
            )
        )
        if not improves:
            return
        best_live_coverage_score = score
        best_live_coverage_line = float(line_value) if isinstance(line_value, (int, float)) else None
        best_live_coverage_branch = float(branch_value) if isinstance(branch_value, (int, float)) else None
        best_live_coverage_total_methods = cur_total_methods
        best_live_coverage_snapshots = _snapshot_test_files(candidate_test_files)
        validation_policy["live_best_coverage_snapshot"] = {
            "available": True,
            "stage": stage,
            "score": best_live_coverage_score,
            "line_coverage": best_live_coverage_line,
            "branch_coverage": best_live_coverage_branch,
            "test_method_count": best_live_coverage_total_methods,
        }

    def _restore_live_coverage_snapshot_if_better() -> bool:
        """Restore this run's best green coverage snapshot if later work regressed it."""
        nonlocal current, outcome, _cov_line, _cov_branch, _methods_cov
        if request.dry_run or not best_live_coverage_snapshots:
            return False
        if best_live_coverage_score < 0.0:
            return False
        current_score = _live_coverage_score(_methods_cov, _cov_line, _cov_branch)
        current_total_methods = _sum_at_test_methods_for_files(candidate_test_files)
        current_score_value = current_score[0] if current_score is not None else -1.0
        regressed = (
            current_score_value + 1e-12 < best_live_coverage_score
            or (
                abs(current_score_value - best_live_coverage_score) <= 1e-12
                and current_total_methods < best_live_coverage_total_methods
            )
        )
        if not regressed:
            return False
        restore_stats = _restore_test_file_snapshots(best_live_coverage_snapshots)
        validation_policy["restored_live_best_coverage_snapshot"] = True
        validation_policy["live_best_coverage_restored_files"] = int(restore_stats.get("restored_files", 0))
        validation_policy["live_best_coverage_deleted_new_files"] = int(restore_stats.get("deleted_new_files", 0))
        validation_policy["live_best_coverage_restore_skipped"] = int(restore_stats.get("restore_skipped", 0))
        validation_policy["live_best_coverage_current_score_before_restore"] = current_score_value
        validation_policy["live_best_coverage_restored_score"] = best_live_coverage_score
        current = _invoke_run_project_tests(
            request.project_root,
            effective_test_commands,
            _bounded_test_timeout("live_best_coverage_revalidation_timeout"),
            java_version=getattr(request, "java_version", None),
        )
        outcome = _parse_test_outcome(current)
        _cov_line, _cov_branch = _read_coverage(request)
        _methods_cov = _read_method_coverage(request)
        _discard_untrusted_zero_retained_streaming_coverage("live_best_coverage_revalidation")
        next_iteration = 1
        if test_runs:
            try:
                next_iteration = int(test_runs[-1].get("iteration", 0)) + 1
            except Exception:
                next_iteration = 1
        test_runs.append({
            "iteration": next_iteration,
            "repair_attempt": int(request.repair_iterations) + 1,
            "return_code": current.get("return_code"),
            "elapsed_seconds": current.get("elapsed_seconds"),
            "failed_test_count": outcome.get("failed_test_count"),
            "failure_count": outcome.get("failure_count"),
            "error_count": outcome.get("error_count"),
            "failure_type": outcome.get("failure_type"),
            "repaired_test_count": 0,
            "restored_live_best_coverage_snapshot": True,
            "line_coverage": _cov_line,
            "branch_coverage": _cov_branch,
            "methods_coverage": _methods_cov,
        })
        try:
            progress.write(
                "[generate] restored live-run best coverage snapshot "
                f"line={best_live_coverage_line} branch={best_live_coverage_branch}"
            )
        except Exception:
            pass
        return True

    def _promote_best_rollback_snapshot(
        *,
        require_new_tests: bool = False,
        new_test_count: int = 0,
        command_failed: bool = False,
    ) -> None:
        """Promote the on-disk state to the rollback baseline.

        The baseline is the strongest "known-good" snapshot we have observed:
          - return_code == 0 AND failed_test_count == 0  (fully green), AND
          - has ``@Test`` methods (so an empty skeleton never displaces a
            previously promoted green state with real tests).

        We deliberately do NOT promote red states: a "less red" red state is
        not safe rollback material, because we can't tell which methods were
        actually passing in it.
        """
        nonlocal best_test_file_snapshots, best_failed_test_count, best_return_code
        nonlocal best_total_test_methods
        if request.dry_run or (not candidate_test_files):
            return
        if current is None or outcome is None:
            return
        if command_failed:
            return
        if require_new_tests and int(new_test_count or 0) <= 0:
            return
        try:
            cur_failed = int(outcome.get("failed_test_count", 10**9))
        except Exception:
            cur_failed = 10**9
        try:
            cur_rc = int(current.get("return_code", 1))
        except Exception:
            cur_rc = 1
        if cur_failed != 0 or cur_rc != 0:
            return  # only fully-green states are promoted
        cur_total_methods = _sum_at_test_methods_for_files(candidate_test_files)
        # Among green states, keep the one with the most @Test methods so an
        # empty/skeleton state can never displace a green state with real
        # tests.
        if str(getattr(request, "method_name", "") or "").strip():
            target_scored = _live_coverage_score(_methods_cov, _cov_line, _cov_branch)
            if target_scored is None:
                validation_policy["rollback_baseline_target_positive_skip_count"] = int(
                    validation_policy.get("rollback_baseline_target_positive_skip_count", 0) or 0
                ) + 1
                validation_policy["rollback_baseline_target_positive_skip_stage"] = "no_target_positive_coverage"
                return
        _promote_live_coverage_snapshot("rollback_baseline")
        if cur_total_methods <= max(best_total_test_methods, 0):
            return
        best_failed_test_count = cur_failed
        best_return_code = cur_rc
        best_total_test_methods = cur_total_methods
        best_test_file_snapshots = _snapshot_test_files(candidate_test_files)
        validation_policy["rollback_baseline_updates"] = int(
            validation_policy.get("rollback_baseline_updates", 0)
        ) + 1

    def _restore_best_snapshot_if_regressed() -> bool:
        """Restore best snapshot when current state is strictly worse.

        Returns True when a restore happened.
        """
        nonlocal current, outcome, _cov_line, _cov_branch, _methods_cov
        if request.dry_run or current is None or outcome is None:
            return False
        if not best_test_file_snapshots or best_total_test_methods <= 0:
            return False
        # Best is guaranteed fully-green (rc==0, failed==0). Restore if
        # current is non-green OR the on-disk @Test surface shrank below the
        # best known-good state.
        try:
            cur_failed_raw = outcome.get("failed_test_count", 10**9)
            cur_failed = int(cur_failed_raw if cur_failed_raw is not None else 10**9)
        except Exception:
            cur_failed = 10**9
        try:
            cur_rc_raw = current.get("return_code", 1)
            cur_rc = int(cur_rc_raw if cur_rc_raw is not None else 1)
        except Exception:
            cur_rc = 1
        cur_total_methods = _sum_at_test_methods_for_files(candidate_test_files)
        regressed = (
            cur_failed > 0
            or cur_rc != 0
            or cur_total_methods < best_total_test_methods
        )
        if not regressed:
            return False

        restore_stats = _restore_test_file_snapshots(best_test_file_snapshots)
        validation_policy["rolled_back"] = True
        validation_policy["rolled_back_writes"] = int(
            validation_policy.get("rolled_back_writes", 0)
        ) + 1
        validation_policy["restored_files"] = int(
            validation_policy.get("restored_files", 0)
        ) + int(restore_stats.get("restored_files", 0))
        validation_policy["deleted_new_files"] = int(
            validation_policy.get("deleted_new_files", 0)
        ) + int(restore_stats.get("deleted_new_files", 0))
        validation_policy["restore_skipped"] = int(
            validation_policy.get("restore_skipped", 0)
        ) + int(restore_stats.get("restore_skipped", 0))

        current = _invoke_run_project_tests(
            request.project_root,
            iterative_test_commands,
            _bounded_test_timeout("rollback_revalidation_timeout"),
            java_version=getattr(request, "java_version", None),
        )
        outcome = _parse_test_outcome(current)
        _cov_line, _cov_branch = _read_coverage(request)
        _methods_cov = _read_method_coverage(request)
        _discard_untrusted_zero_retained_streaming_coverage("rollback_revalidation")
        _report_progress_coverage(progress, request, _cov_line, _cov_branch, _methods_cov)
        next_iteration = 1
        if test_runs:
            try:
                next_iteration = int(test_runs[-1].get("iteration", 0)) + 1
            except Exception:
                next_iteration = 1
        test_runs.append({
            "iteration": next_iteration,
            "repair_attempt": int(request.repair_iterations) + 1,
            "return_code": current["return_code"],
            "elapsed_seconds": current["elapsed_seconds"],
            "failed_test_count": outcome["failed_test_count"],
            "failure_count": outcome["failure_count"],
            "error_count": outcome["error_count"],
            "failure_type": outcome["failure_type"],
            "repaired_test_count": 0,
            "restored_best_snapshot": True,
            "line_coverage": _cov_line,
            "branch_coverage": _cov_branch,
            "methods_coverage": _methods_cov,
        })
        return True

    validation_enabled = (not request.dry_run) and test_command_enabled
    request.defer_test_writes = False
    retained_test_behavior_fingerprints: set[str] = set()
    if validation_enabled and int(request.generation_parallelism) > 1:
        try:
            progress.write(
                "[generate] per-test acceptance is enabled; generation runs in parallel and validation runs in isolated sandboxes"
            )
        except Exception:
            pass

    def _run_generation_commands_with_streaming_validation(
        generation_snapshots: dict[str, str | None],
        generation_commands: list[Any] | None = None,
        *,
        on_start: Any | None = None,
        on_done: Any | None = None,
        allow_streaming_repair: bool = True,
    ) -> list:
        """Run generation and overlap completed-result validation in sandboxes."""
        nonlocal e2e_timed_out
        retained_test_behavior_fingerprints.update(
            _test_snapshot_behavior_fingerprints(generation_snapshots)
        )
        retained_test_behavior_fingerprints.update(
            _current_test_file_behavior_fingerprints(candidate_test_files)
        )
        retained_test_behavior_fingerprints.update(
            _test_snapshot_behavior_fingerprints(
                best_partial_test_file_snapshots
            )
        )
        for passed_item in list(
            validation_policy.get("streaming_validation_passed_details") or []
        ):
            if isinstance(passed_item, dict):
                retained_test_behavior_fingerprints.update(
                    _validation_item_behavior_fingerprints(passed_item)
                )
        seed_audit = validation_policy.setdefault(
            "streaming_validation_behavior_fingerprint_seed_counts",
            [],
        )
        if isinstance(seed_audit, list):
            seed_audit.append({
                "prompt_iteration": int(
                    getattr(request, "prompt_iteration", 1) or 1
                ),
                "fingerprint_count": len(
                    retained_test_behavior_fingerprints
                ),
                "passed_detail_count": len(
                    list(
                        validation_policy.get(
                            "streaming_validation_passed_details"
                        )
                        or []
                    )
                ),
            })
        active_commands = generation_commands if generation_commands is not None else commands
        active_on_start = on_start if on_start is not None else progress.on_target_start
        active_on_done = on_done if on_done is not None else progress.on_target_done
        stream_enabled = validation_enabled and bool(candidate_test_files) and bool(effective_test_commands)
        runner_supports_result_callback = True
        runner_supported_keywords: set[str] | None = None
        if stream_enabled:
            try:
                runner_signature = inspect.signature(run_commands)
                runner_parameters = runner_signature.parameters
                if any(
                    parameter.kind is inspect.Parameter.VAR_KEYWORD
                    for parameter in runner_parameters.values()
                ):
                    runner_supported_keywords = None
                else:
                    runner_supported_keywords = set(runner_parameters)
                    runner_supports_result_callback = "on_result" in runner_supported_keywords
            except (TypeError, ValueError):
                # Some wrappers/builtins have no inspectable signature. The
                # guarded call below remains the fallback for those cases.
                runner_supported_keywords = None
        if stream_enabled and not runner_supports_result_callback:
            validation_policy["streaming_validation"] = False
            validation_policy["streaming_validation_fallback_reason"] = (
                "runner_does_not_support_on_result"
            )
            request.defer_test_writes = False
            stream_enabled = False
        stream_futures = []
        stream_future_results: dict[Any, Any] = {}
        stream_future_deadlines: dict[Any, float] = {}
        stream_future_labels: dict[Any, str] = {}
        stream_future_jobs: dict[Any, dict[str, Any]] = {}
        stream_results: list[dict[str, Any]] = []
        stream_passed_generation_results: list[Any] = []
        stream_failed_generation_results: list[tuple[dict[str, Any], Any]] = []
        generation_callback_events = 0
        stream_started = time.perf_counter()
        stream_workers = max(1, method_probe_workers)
        stream_lock = threading.Lock()
        early_repair_futures: set[Any] = set()
        early_repair_future_labels: dict[Any, str] = {}
        early_repair_future_results: dict[Any, Any] = {}
        early_repair_future_failed_items: dict[Any, dict[str, Any]] = {}
        early_repair_future_deadlines: dict[Any, float] = {}
        validation_repair_queued: set[Any] = set()
        early_repair_progress = {
            "processed": 0,
            "repaired": 0,
            "still_failing": 0,
        }
        deterministic_dispatch_spec: dict[str, Any] = {}
        deterministic_dispatch_constants_submitted: set[str] = set()
        deterministic_dispatch_variant_cap = 12
        deterministic_json_replay_spec: dict[str, Any] = {}
        deterministic_json_rows_submitted: set[str] = set()
        deterministic_json_variant_cap = 32
        deterministic_numeric_string_replay_spec: dict[str, Any] = {}
        deterministic_numeric_string_rows_submitted: set[str] = set()
        deterministic_numeric_string_variant_cap = 16
